    #[test]
    fn initial_record_uses_the_preinitialize_game_snapshot() {
        let directory = tempdir().expect("initial record fixture");
        let scenario_path = directory.path().join("Snapshot.c4s");
        fs::create_dir(&scenario_path).expect("create scenario group");
        install_record_test_definitions(directory.path());
        fs::write(
            scenario_path.join("Scenario.txt"),
            "[Head]\nTitle=Snapshot\n\n[Definitions]\nDefinition1=Objects.c4d\n",
        )
        .expect("write scenario core");
        fs::write(
            scenario_path.join("PlayerInfos.txt"),
            b"stale initial roster",
        )
        .expect("write stale initial roster");
        fs::write(scenario_path.join("CtrlRec.txt"), b"copied text stream")
            .expect("write copied text stream");
        fs::write(
            scenario_path.join("RecPlayerInfos.txt"),
            b"copied final roster",
        )
        .expect("write copied final roster");
        let scenario_data =
            Scenario::load_from_path_with(&scenario_path, &InstallDefinitionResolver::new(None))
                .expect("load record scenario");
        let scenario = FrontendScenario::from_command_line(&scenario_path);
        let mut app = new_state_only_menu_app(320, 200);
        app.recordings_dir = Some(directory.path().join("Records.c4f"));

        let mut initial_game_data = clonk_engine::InitialNetworkGameData::default();
        initial_game_data.frame = 41;
        initial_game_data.control_tick = 17;
        initial_game_data.script_go = true;
        initial_game_data.script_counter = 9;
        initial_game_data.music_enabled = true;

        app.prepare_recording_for(
            &scenario,
            &scenario_data,
            Some(InitialRecordingSource::Fresh(&initial_game_data)),
            None,
            None,
        )
        .expect("prepare initial record");
        let packed = app
            .recording_template
            .as_ref()
            .expect("recording template")
            .group
            .pack()
            .expect("pack recording template");
        let record = Group::from_memory(PathBuf::from("Snapshot.c4s"), packed)
            .expect("open recording template");
        let game = String::from_utf8(record.read_file("Game.txt").expect("record Game.txt"))
            .expect("Game.txt is ASCII");

        assert!(!record.exists("PlayerInfos.txt"));
        assert_eq!(record.read_file("CtrlRec.txt").unwrap(), b"copied text stream");
        assert_eq!(
            record.read_file("RecPlayerInfos.txt").unwrap(),
            b"copied final roster"
        );
        assert!(game.contains("Frame=41\r\n"));
        assert!(game.contains("ControlTick=17\r\n"));
        assert!(game.contains("Go=true\r\n"));
        assert!(game.contains("Counter=9\r\n"));
        assert!(game.contains("MusicEnabled=true\r\n"));
        assert_eq!(
            app.engine.frame(),
            0,
            "live engine remains post-menu default"
        );
    }

    #[test]
    fn loaded_initial_record_reconstructs_exact_source_before_finitial_game_splice() {
        let directory = tempdir().expect("loaded initial record fixture");
        let scenario_path = directory.path().join("Loaded.c4s");
        let section_path = scenario_path.join("SectArchive.c4g");
        fs::create_dir_all(&section_path).expect("create scenario section");
        install_record_test_definitions(directory.path());
        fs::write(
            scenario_path.join("Scenario.txt"),
            "[Head]\nTitle=Loaded record\n\n[Definitions]\nDefinition1=Objects.c4d\n",
        )
        .expect("write scenario core");
        fs::write(
            scenario_path.join("Game.txt"),
            "[Game]\nTime=999\n\n[Player999]\nWealth=777\n",
        )
        .expect("write stale source game");
        fs::write(scenario_path.join("Title.png"), b"original scenario title")
            .expect("write original scenario title");
        fs::write(section_path.join("Archive.bin"), b"section payload")
            .expect("write scenario section payload");
        let scenario_data =
            Scenario::load_from_path_with(&scenario_path, &InstallDefinitionResolver::new(None))
                .expect("load record scenario");
        let scenario = FrontendScenario::from_command_line(&scenario_path);
        let mut app = new_state_only_menu_app(320, 200);
        app.recordings_dir = Some(directory.path().join("Records.c4f"));
        app.control_player_infos
            .apply(clonk_engine::PlayerInfoControlData {
                client_id: 0,
                players: vec![clonk_engine::ControlPlayerInfoEntry {
                    id: 117,
                    savegame_player: 17,
                    name: LegacyCString::from_bytes(b"Current takeover".to_vec()).unwrap(),
                    flags: 0,
                    ..Default::default()
                }],
                ..Default::default()
            });

        app.engine
            .register_definition(
                clonk_engine::Definition::from_script(
                    "TST1",
                    "Recorded object",
                    "static PostMaterialization;",
                )
                .expect("compile object definition"),
            )
            .expect("register object definition");
        app.engine
            .spawn_object(clonk_engine::SpawnConfig::new("TST1").with_id(ObjectId::new(41)))
            .expect("spawn recorded object");
        let mut landscape = clonk_engine::Landscape::flat(2, 1);
        assert!(landscape.set_mode(clonk_engine::LANDSCAPE_MODE_EXACT));
        landscape.set_pixel_grid(clonk_engine::landscape::PixelGrid::new(
            2,
            1,
            vec![0, 1],
            vec![0; 256],
            vec![None; 256],
            vec![None; 256],
        ));
        app.engine.set_landscape(landscape);

        let mut restored = app.engine.capture_state();
        restored.frame = 73;
        restored.script_globals.named.insert(
            "PostMaterialization".to_owned(),
            Value::String("materialized string".to_owned().into()),
        );
        restored.players = vec![PlayerState {
            id: 2,
            player_info_id: 17,
            name: "Loaded player".to_owned(),
            status: PlayerStatus::Active,
            wealth: 99,
            ..PlayerState::default()
        }];
        restored.last_player_info_id = 17;
        app.engine
            .restore_state(&restored)
            .expect("restore loaded runtime fixture");

        app.prepare_recording_for(
            &scenario,
            &scenario_data,
            Some(InitialRecordingSource::Loaded {
                music_enabled: false,
                source_save_player_infos: Some(b"original saved roster"),
                source_title_png: Some(b"saved game screenshot"),
            }),
            None,
            None,
        )
        .expect("prepare loaded initial record");
        // InitPlayers performs this only after InitControl has snapshotted
        // the initial record's current roster.
        app.control_player_infos
            .resume_joined_savegame_player(17, 0, false);
        let packed = app
            .recording_template
            .as_ref()
            .expect("recording template")
            .group
            .pack()
            .expect("pack recording template");
        let record = Group::from_memory(PathBuf::from("Loaded.c4s"), packed)
            .expect("open recording template");
        assert_eq!(
            record
                .read_file("SavePlayerInfos.txt")
                .expect("original restore roster"),
            b"original saved roster"
        );
        assert_eq!(
            record.read_file("Title.png").expect("loaded save title"),
            b"saved game screenshot"
        );
        let initial_players = clonk_network::decode_player_info_list_ini(
            &record
                .read_file("PlayerInfos.txt")
                .expect("pre-resume current roster"),
        )
        .expect("decode pre-resume current roster");
        assert_eq!(initial_players.clients[0].players[0].id, 117);
        assert_eq!(initial_players.clients[0].players[0].flags, 0);
        assert_eq!(
            app.control_player_infos.recreation_info_ids(),
            vec![17],
            "live takeover rows resume only after fInitial"
        );

        let objects =
            String::from_utf8(record.read_file("Objects.txt").expect("record Objects.txt"))
                .expect("Objects.txt is ASCII");
        assert!(objects.contains("id=TST1\r\n"));
        assert!(objects.contains("Number=41\r\n"));
        let landscape = clonk_resources::bitmap::IndexedBitmap::decode(
            &record
                .read_file("Landscape.bmp")
                .expect("record Landscape.bmp"),
        )
        .expect("decode exact record landscape");
        assert_eq!((landscape.width, landscape.height), (2, 1));
        assert_eq!(landscape.indices, [0, 1]);
        assert!(record.exists("Landscape.png"));
        let strings = record.read_file("Strings.txt").expect("record Strings.txt");
        assert!(strings
            .windows(b"materialized string".len())
            .any(|window| window == b"materialized string"));
        let section = record
            .open_child("SectArchive.c4g")
            .expect("record scenario section");
        assert_eq!(
            section.read_file("Archive.bin").expect("section payload"),
            b"section payload"
        );

        let scenario_core = String::from_utf8(
            record
                .read_file("Scenario.txt")
                .expect("record Scenario.txt"),
        )
        .expect("Scenario.txt is ASCII");
        for expected in ["SaveGame=1", "NoInitialize=1", "Replay=1"] {
            assert!(scenario_core.contains(expected), "missing {expected}");
        }

        let game = String::from_utf8(record.read_file("Game.txt").expect("record Game.txt"))
            .expect("Game.txt is ASCII");
        let player_start = game.find("[Player17]").expect("reconstructed player tail");
        assert!(!game.contains("[Player999]"));
        assert!(game[player_start..].contains("Wealth=99\r\n"));
        assert_eq!(game.matches("[Player").count(), 1);

        let post_materialization = app
            .engine
            .capture_initial_record_game_data(false)
            .expect("capture post-materialization initial projection");
        let expected_game = clonk_engine::serialize_initial_network_game(&post_materialization, None)
            .expect("serialize post-materialization initial projection")
            .expect("initial projection emits Game.txt");
        let expected_game = String::from_utf8(expected_game).expect("expected Game.txt is ASCII");
        assert_eq!(
            game[..player_start].trim_end(),
            expected_game.trim_end(),
            "the non-player prefix must be the post-materialization fInitial projection",
        );
        assert!(game[..player_start].contains("Frame=73\r\n"));
        assert!(game[..player_start].contains("GlobalNamed="));
    }

    #[test]
    fn runtime_join_dynamic_requests_coalesce_until_a_newer_tick() {
        let mut pending = PendingRuntimeDynamicRequest::new(7, 23);
        assert!(pending.needs_synchronize());

        pending.synchronize_queued = true;
        pending.include(8, 23);
        assert_eq!(pending.client_ids, HashSet::from([7, 8]));
        assert!(!pending.needs_synchronize());

        pending.synchronize_queued = false;
        pending.synchronized_control_tick = Some(23);
        pending.include(9, 22);
        assert_eq!(pending.synchronized_control_tick, Some(23));
        assert!(!pending.needs_synchronize());

        pending.include(10, 24);
        assert_eq!(pending.requested_control_tick, 24);
        assert_eq!(pending.synchronized_control_tick, None);
        assert!(pending.needs_synchronize());
    }

    #[test]
    fn delayed_join_data_needed_after_fanout_does_not_request_a_second_capture() {
        let null_dynamic = clonk_engine::NetworkResourceCore::default();
        let published_dynamic = clonk_engine::NetworkResourceCore {
            resource_type: clonk_network::HostResourceType::Dynamic as u8,
            id: 17,
            ..clonk_engine::NetworkResourceCore::default()
        };
        let mut capture_count = 0;

        // Client A's event arrives first and has no usable dynamic, so the
        // application queues one synchronized capture.
        if !published_runtime_dynamic_covers_request(&null_dynamic, -1, 23) {
            capture_count += 1;
        }

        // SyncScheduled is processed next. Its publication fans the new
        // tick-24 dynamic out to both A and already-waiting client B. B's
        // earlier JoinDataNeeded event is still queued behind SyncScheduled.
        assert!(published_runtime_dynamic_covers_request(
            &published_dynamic,
            24,
            23,
        ));
        if !published_runtime_dynamic_covers_request(&published_dynamic, 24, 23) {
            capture_count += 1;
        }
        assert_eq!(capture_count, 1);

        // A genuinely newer request and a null resource must still schedule
        // regeneration.
        assert!(!published_runtime_dynamic_covers_request(
            &published_dynamic,
            24,
            25,
        ));
        assert!(!published_runtime_dynamic_covers_request(
            &null_dynamic,
            24,
            23,
        ));
    }

    #[test]
    fn runtime_join_restore_infos_come_from_dynamic_not_join_data_parameters() {
        let restore_infos = |id: i32, name: &[u8]| clonk_network::PlayerInfoListSnapshot {
            last_player_id: id,
            clients: vec![clonk_network::ClientPlayerInfosSnapshot {
                client_id: 3,
                flags: 0,
                players: vec![clonk_engine::ControlPlayerInfoEntry {
                    id,
                    name: LegacyCString::from_bytes(name.to_vec()).expect("fixture player name"),
                    player_type: clonk_engine::PLAYER_INFO_TYPE_USER,
                    flags: clonk_engine::PLAYER_INFO_FLAG_JOINED,
                    league_progress_data_is_null: false,
                    ..clonk_engine::ControlPlayerInfoEntry::default()
                }],
            }],
        };
        let packet_restore_infos = restore_infos(7, b"Packet restore");
        let dynamic_restore_infos = restore_infos(42, b"Dynamic restore");

        let directory = tempdir().expect("runtime join scenario directory");
        let combined_path = directory.path().join("Combined9.c4s");
        let mut combined = MutableGroup::new("Combined9.c4s");
        combined
            .add_file(
                "Scenario.txt",
                b"[Head]\r\nNetworkGame=1\r\nNetworkRuntimeJoin=1\r\n".to_vec(),
            )
            .expect("add scenario core");
        combined
            .add_file(
                "SavePlayerInfos.txt",
                clonk_network::encode_player_info_list_ini(&dynamic_restore_infos)
                    .expect("encode dynamic restore infos"),
            )
            .expect("add dynamic restore infos");
        fs::write(
            &combined_path,
            combined.pack().expect("pack combined runtime scenario"),
        )
        .expect("write combined runtime scenario");
        let combined = Group::open(&combined_path).expect("open combined runtime scenario");

        let selected = client_network_restore_player_infos(
            true,
            &combined,
            &packet_restore_infos,
            &[],
            &LanguagePacks::default(),
        );
        assert_eq!(selected.last_player_id, 42);
        assert_eq!(selected.clients[0].players[0].id, 42);
        assert_eq!(packet_restore_infos.last_player_id, 7);

        let ordinary = client_network_restore_player_infos(
            false,
            &combined,
            &packet_restore_infos,
            &[],
            &LanguagePacks::default(),
        );
        assert_eq!(ordinary.last_player_id, 7);
        assert_eq!(ordinary.clients[0].players[0].id, 7);

        let missing_path = directory.path().join("Combined10.c4s");
        let mut missing = MutableGroup::new("Combined10.c4s");
        missing
            .add_file(
                "Scenario.txt",
                b"[Head]\r\nNetworkGame=1\r\nNetworkRuntimeJoin=1\r\n".to_vec(),
            )
            .expect("add scenario core without restore infos");
        fs::write(
            &missing_path,
            missing.pack().expect("pack missing-restore scenario"),
        )
        .expect("write missing-restore scenario");
        let missing = Group::open(&missing_path).expect("open missing-restore scenario");
        let selected = client_network_restore_player_infos(
            true,
            &missing,
            &packet_restore_infos,
            &[],
            &LanguagePacks::default(),
        );
        assert_eq!(selected.last_player_id, 0);
        assert!(selected.clients.is_empty());
    }

    #[test]
    fn l028_console_input_and_open_parameters_follow_native_framing() {
        assert_eq!(
            parse_classic_console_parameters(
                "\"Missions/My Round/Scenario.txt\" /network /lobby:17 \"/comment:console game\"",
            ),
            [
                OsString::from("Missions/My Round/Scenario.txt"),
                OsString::from("/network"),
                OsString::from("/lobby:17"),
                OsString::from("/comment:console game"),
            ]
        );

        let (sender, receiver) = mpsc::channel();
        forward_console_input(
            std::io::Cursor::new(b"\n   \r\n/quit\r\nhello\tworld\nunterminated"),
            sender,
        )
        .expect("read redirected console input");
        let mut events = receiver.into_iter();
        assert!(matches!(
            events.next(),
            Some(ConsoleInputEvent::Command(command)) if command == "   "
        ));
        assert!(matches!(
            events.next(),
            Some(ConsoleInputEvent::Command(command)) if command == "/quit"
        ));
        assert!(matches!(
            events.next(),
            Some(ConsoleInputEvent::Command(command)) if command == "helloworld"
        ));
        assert!(matches!(events.next(), Some(ConsoleInputEvent::Eof)));
        assert!(events.next().is_none());
    }

    #[test]
    fn l028_console_quit_is_global_and_headless_loop_exits_cleanly() {
        let mut app = new_state_only_menu_app(320, 200);
        for mode in [AppMode::Menu, AppMode::Loading, AppMode::Running] {
            app.mode = mode;
            app.process_console_command("/quit")
                .expect("dispatch global console quit");
            assert!(app.take_exit_request(), "quit must exit from {mode:?}");
        }

        let app = new_menu_app(320, 200);
        let (sender, receiver) = mpsc::channel();
        sender
            .send(ConsoleInputEvent::Command("/quit".to_string()))
            .expect("queue console quit");
        run_console_event_loop(app, receiver).expect("headless scheduler exits on /quit");

        let app = new_menu_app(320, 200);
        let (sender, receiver) = mpsc::channel();
        sender
            .send(ConsoleInputEvent::Error(io::Error::new(
                io::ErrorKind::Other,
                "fixture stdin failure",
            )))
            .expect("queue console reader failure");
        let error = run_console_event_loop(app, receiver)
            .expect_err("stdin read errors must fail the console process");
        assert!(error.to_string().contains("fixture stdin failure"));

        let mut boot = new_state_only_menu_app(320, 200);
        let (sender, receiver) = mpsc::channel();
        sender
            .send(BootLoadingEvent::Finished(None))
            .expect("finish console boot worker");
        boot.boot_loading = Some(BootLoadingState::new(receiver));
        boot.mode = AppMode::Loading;
        boot.console_mode = true;
        boot.loader_screen = None;
        boot.poll_boot_loading();
        assert_eq!(boot.mode, AppMode::Menu);
        assert!(boot.boot_loading.is_none());
    }

    #[test]
    fn l028_console_open_close_and_message_fallback_follow_app_state() {
        let mut startup = new_state_only_menu_app(320, 200);
        startup.console_mode = true;
        let (boot_sender, boot_receiver) = mpsc::channel();
        startup.boot_loading = Some(BootLoadingState::new(boot_receiver));
        startup.mode = AppMode::Loading;
        startup
            .process_console_command(
                "/open \"Missions/My Round/Scenario.txt\" /network /lobby:17 \"/comment:console game\"",
            )
            .expect("queue console scenario during startup loading");
        assert_eq!(
            startup.classic_command_line.scenario,
            Some(PathBuf::from("Missions/My Round"))
        );
        assert_eq!(startup.classic_command_line.network_active, Some(true));
        assert_eq!(startup.classic_command_line.lobby_timeout, Some(Some(17)));
        assert_eq!(
            startup.classic_command_line.comment.as_deref(),
            Some("console game")
        );
        assert!(startup.auto_start_classic_command_line_scenario);
        startup
            .process_console_command("/close")
            .expect("cancel console scenario while process boot is pending");
        assert_eq!(startup.mode, AppMode::Loading);
        assert!(startup.boot_loading.is_some());
        assert!(!startup.auto_start_classic_command_line_scenario);
        boot_sender
            .send(BootLoadingEvent::Finished(None))
            .expect("finish retained boot worker");
        startup.poll_boot_loading();
        assert_eq!(startup.mode, AppMode::Menu);
        assert!(startup.boot_loading.is_none());
        assert!(startup.console_startup_active());

        let (_query_sender, query_receiver) = mpsc::channel::<
            std::result::Result<ClassicDirectReferenceQueryResult, NetworkStartError>,
        >();
        startup.classic_direct_reference_query =
            Some(ClassicDirectReferenceQuery { receiver: query_receiver });
        let pending_join_arguments = startup.classic_command_line.clone();
        startup
            .process_console_command("/open Replacement.c4s")
            .expect("ignore a second open while game initialization is pending");
        assert_eq!(startup.classic_command_line, pending_join_arguments);
        startup
            .process_console_command("/close")
            .expect("close an asynchronously initializing console round");
        assert_eq!(startup.mode, AppMode::Menu);
        assert!(startup.classic_direct_reference_query.is_none());
        assert!(startup.console_startup_active());
        startup
            .process_console_command("/open /comment:replacement")
            .expect("open a replacement after closing pending initialization");
        assert_eq!(
            startup.classic_command_line.comment.as_deref(),
            Some("replacement")
        );

        let mut running = new_state_only_lightweight_running_sandbox_app();
        let (network, _events, mut commands) =
            NetworkManager::test_stub_with_commands_for_client_id(0);
        running.network = Some(network);
        running
            .process_console_command("administrator message")
            .expect("route ordinary console input to message input");
        assert_eq!(
            commands.take_submitted_messages(),
            vec![MessageControlData {
                message_type: MESSAGE_TYPE_NORMAL,
                player: running.local_owner,
                to_player: -1,
                message: LegacyCString::from_bytes(b"administrator message".to_vec())
                    .expect("fixture message is NUL-free"),
                by_client: 0,
            }]
        );
        running.full_speed = true;
        running.frame_skip = 9;
        running
            .process_console_command("/close")
            .expect("close running console round");
        assert_eq!(running.mode, AppMode::Menu);
        assert!(running.active_scenario.is_none());
        assert!(!running.full_speed);
        assert_eq!(running.frame_skip, 1);
    }

    #[test]
    fn l028_console_lobby_start_is_host_only_and_restarts_countdown() {
        let _lock = env_lock().lock();
        let user_data = tempdir().expect("isolated console lobby config");
        let (_guard, paths) = exact_loader_test_paths(user_data.path(), None);
        persist_config_value(&paths, "Lobby", "CountdownTime", "7")
            .expect("configure console lobby countdown");
        let mut host = new_menu_app(640, 480);
        host.app_paths = Some(paths);
        let (_events, mut commands) = install_classic_host_network_stub(&mut host);
        host.process_console_command("/start")
            .expect("start configured-default countdown");
        assert_eq!(
            commands.take_submitted_lobby_countdowns(),
            vec![clonk_network::LobbyCountdownPacket::new(7)]
        );
        host.process_console_command("/abort")
            .expect("non-start lobby input routes through MessageInput");
        assert!(commands.take_submitted_lobby_countdowns().is_empty());
        assert_eq!(
            host.host_lobby_countdown,
            Some(HostLobbyCountdown::with_seconds(7))
        );
        assert!(host
            .classic_host_lobby
            .as_ref()
            .expect("classic host lobby")
            .controller
            .logs()
            .last()
            .is_some_and(|line| line.text.contains("Unknown command: \"abort\"")));
        host.process_console_command("/starter 12junk")
            .expect("native prefix command replaces countdown");
        assert_eq!(
            commands.take_submitted_lobby_countdowns(),
            vec![
                clonk_network::LobbyCountdownPacket::new(-1),
                clonk_network::LobbyCountdownPacket::new(12),
            ]
        );
        host.ui_sound_log.clear();
        host.process_console_command("/start ")
            .expect("invalid explicit timeout is consumed");
        assert!(commands.take_submitted_lobby_countdowns().is_empty());
        assert!(
            host.ui_sound_log.is_empty(),
            "native console validation only logs the usage error"
        );
        assert_eq!(
            host.classic_host_lobby
                .as_ref()
                .expect("classic host lobby")
                .controller
                .logs()
                .last()
                .map(|line| line.text.as_str()),
            Some("Usage: /start [timer]")
        );
        host.process_console_command("/start 0")
            .expect("zero remains a one-second console countdown");
        assert_eq!(
            commands.take_submitted_lobby_countdowns(),
            vec![
                clonk_network::LobbyCountdownPacket::new(-1),
                clonk_network::LobbyCountdownPacket::new(0),
            ]
        );
        assert_eq!(
            host.host_lobby_countdown,
            Some(HostLobbyCountdown::with_seconds(0))
        );
        assert_eq!(host.mode, AppMode::Menu);

        install_message_fixture(&mut host);
        host.snapshot = host.engine.snapshot();
        host.process_console_command("/private Sender secret")
            .expect("running-only private syntax is rejected in the lobby");
        assert!(commands.take_submitted_messages().is_empty());
        assert!(host
            .classic_host_lobby
            .as_ref()
            .expect("classic host lobby")
            .controller
            .logs()
            .last()
            .is_some_and(|line| line.text.contains("Unknown command: \"private\"")));
        host.process_console_command("\"hello")
            .expect("leading quote remains an ordinary lobby message");
        assert_eq!(
            commands.take_submitted_messages(),
            vec![MessageControlData {
                message_type: MESSAGE_TYPE_NORMAL,
                player: -1,
                to_player: -1,
                message: LegacyCString::from_bytes(b"\"hello".to_vec())
                    .expect("fixture message is NUL-free"),
                by_client: 0,
            }]
        );
        assert!(host.engine.set_team_distribution(4));
        host.process_console_command("^hidden")
            .expect("hidden teams reject lobby team messages");
        assert!(commands.take_submitted_messages().is_empty());
        assert_eq!(
            host.classic_host_lobby
                .as_ref()
                .expect("classic host lobby")
                .controller
                .logs()
                .last()
                .map(|line| line.text.as_str()),
            Some("Can't send team message: Teams not known.")
        );

        let mut client = new_menu_app(640, 480);
        client.startup_view = StartupView::NetworkLobby;
        client.network_lobby = Some(NetworkLobbyState::new(7, "Client".to_string(), false));
        client
            .process_console_command("/start 3")
            .expect("client start is consumed");
        assert_eq!(
            client
                .network_lobby
                .as_ref()
                .expect("generic client lobby")
                .logs
                .last()
                .map(|line| line.text.as_str()),
            Some("Host only!")
        );
    }

