    #[test]
    fn scenario_join_places_ready_crew_and_selects_cursor() {
        // C4Player::Join runs ScenarioInit -> PlaceReadyCrew for the
        // scenario's [PlayerN] Crew= spec (C4Player.cpp:670-777, 528-570)
        // and FinalInit's AdjustCursorCommand puts the cursor on the
        // hi-rank crew member (C4Player.cpp:794, 1235-1258). The app join
        // must go through that path instead of a bare player registration.
        let mut app = GameApp::new(
            320,
            200,
            AudioOptions::default(),
            None,
            RuntimeConfig {
                player_owner: 1,
                player_name: "Twonky".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("initialise app");

        let mut definition =
            Definition::from_script("WLKR", "Walker", walker_script()).expect("crew definition");
        definition.set_crew_member(true);
        app.engine
            .register_definition(definition)
            .expect("register crew definition");
        let start = clonk_engine::scenario::PlayerStart {
            ready_crew: vec![("WLKR".to_string(), 2)],
            ..Default::default()
        };
        app.engine.set_player_starts(vec![start]);

        app.join_local_player().expect("join local player");

        // C4PlayerList::GetFreeNumber (C4PlayerList.cpp:189-201): the
        // first joining player takes number 0.
        assert_eq!(app.local_owner, 0, "local owner adopts the joined number");
        let snapshot = app.engine.snapshot();
        let crew: Vec<_> = snapshot
            .objects
            .iter()
            .filter(|object| object.crew_member && object.owner == app.local_owner)
            .collect();
        assert_eq!(crew.len(), 2, "Crew=WLKR=2 places two ready crew members");
        let selection = snapshot
            .crew_selection
            .get(&app.local_owner)
            .expect("crew selection exists after join");
        assert!(
            selection.cursor.is_some(),
            "cursor lands on a crew member at join"
        );

        // A second call must not join (or place crew) twice.
        app.join_local_player().expect("idempotent rejoin");
        assert_eq!(
            app.engine.players().count(),
            1,
            "rejoining does not add a second player"
        );
    }

    #[test]
    fn offline_startup_queues_all_admitted_players_and_rejects_duplicate_file_use() {
        // C4Game freezes Config.General.Participants before OpenScenario;
        // InitLocal loads every valid module in order, assigns dense info IDs,
        // and queues every admitted local join before the first game tick
        // (pristine 9ffa0a5d src/C4Game.cpp:361-364,2699-2736,2828-2834;
        // src/C4PlayerInfo.cpp:357-395,781-807,1273-1322).
        let _env_lock = crate::tests::env_lock().lock();
        reset_cached_app_paths();
        let install = tempdir().expect("install root");
        let user_data = tempdir().expect("user data");
        install_global_gui_and_loader_test_root(install.path());
        let scenario_path = install.path().join("Scenarios/TwoPlayers.c4s");
        let definition_path = scenario_path.join("Defs.c4d");
        fs::create_dir_all(&definition_path).expect("create scenario definition");
        fs::write(
            scenario_path.join("Scenario.txt"),
            "[Head]\nTitle=Two players\nMaxPlayer=3\n\n[Definitions]\nDefinition1=Scenarios/TwoPlayers.c4s/Defs.c4d\n",
        )
        .expect("write scenario core");
        fs::write(
            definition_path.join("DefCore.txt"),
            "[DefCore]\nid=TEST\nName=Test\nCategory=1\n",
        )
        .expect("write definition core");
        write_test_definition_graphics(&definition_path);

        let write_player = |filename: &str, name: &str, control: i32, auto_stop: bool| {
            let path = install.path().join(filename);
            let mut group = clonk_resources::MutableGroup::new(filename);
            group
                .add_file_with_metadata(
                    "Player.txt",
                    format!(
                        "[Player]\nName={name}\n\n[Preferences]\nControl={control}\nMouse=0\nAutoStopControl={}\n",
                        i32::from(auto_stop),
                    )
                    .into_bytes(),
                    1,
                    false,
                )
                .expect("add player core");
            fs::write(&path, group.pack().expect("pack player")).expect("write player group");
            path
        };
        write_player("Alice.c4p", "Alice", 0, false);
        write_player("Bob.c4p", "Bob", 1, true);
        let _guard = EnvGuard::set(&[
            ("LC_INSTALL_ROOT", Some(install.path())),
            ("LC_USER_DATA_DIR", Some(user_data.path())),
        ]);
        let paths = AppPaths::discover().expect("discover app paths");
        paths.ensure_user_dirs().expect("create user directories");
        fs::write(
            paths.config_file(),
            "[General]\nLanguageEx=US\nParticipants=\"Alice.c4p;Bob.c4p\"\n",
        )
        .expect("write configured participants");

        let mut app = GameApp::new(
            320,
            200,
            AudioOptions::default(),
            Some(&paths),
            RuntimeConfig {
                player_owner: 1,
                player_name: "Player".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("initialize app");
        wait_for_menu(&mut app);
        fs::write(
            paths.config_file(),
            "[General]\nLanguageEx=US\nParticipants=\"Alice.c4p;Bob.c4p;Alice.c4p\"\n",
        )
        .expect("restore raw duplicate immediately before C4Game::Init");
        let scenario = app
            .scenario_catalog
            .get("TwoPlayers.c4s")
            .cloned()
            .expect("scenario discovered");
        app.start_scenario(scenario).expect("start scenario");
        wait_for_running(&mut app);

        assert_eq!(
            app.snapshot
                .players
                .iter()
                .map(|player| (player.id, player.player_info_id, player.name.as_str()))
                .collect::<Vec<_>>(),
            vec![(0, 1, "Alice"), (1, 2, "Bob")],
        );
        assert_eq!(app.snapshot.frame, 0, "joins precede the first game tick");
        assert_eq!(app.snapshot.hud.local_players, vec![0, 1]);
        assert_eq!(app.control_player_infos.player_count(), 3);
        for (info_id, filename) in [
            (1, b"Alice.c4p".as_slice()),
            (2, b"Bob.c4p".as_slice()),
            (3, b"Alice.c4p".as_slice()),
        ] {
            let info = app
                .control_player_infos
                .get(info_id)
                .expect("admitted player info remains registered");
            assert_eq!(info.filename.as_bytes(), filename);
            assert_eq!(
                info.flags & clonk_engine::PLAYER_INFO_FLAG_JOINED != 0,
                info_id != 3,
            );
        }

        let bob_down = app
            .bindings
            .key_for_set(1, ControlBindingId::Down)
            .expect("keyboard set two has a down key");
        app.handle_key(bob_down, ElementState::Pressed)
            .expect("press Bob's down key");
        let control = |app: &GameApp, owner| {
            app.engine
                .snapshot()
                .players
                .into_iter()
                .find(|player| player.id == owner)
                .expect("joined local player")
                .control
        };
        assert_eq!(
            control(&app, 0).pressed_coms & (1 << clonk_engine::COM_DOWN),
            0
        );
        assert_ne!(
            control(&app, 1).pressed_coms & (1 << clonk_engine::COM_DOWN),
            0
        );
        app.handle_key(bob_down, ElementState::Released)
            .expect("release Bob's down key");
        assert_eq!(
            control(&app, 1).pressed_coms & (1 << clonk_engine::COM_DOWN),
            0
        );

        let alice_left = app
            .bindings
            .key_for_set(0, ControlBindingId::Left)
            .expect("keyboard set one has a left key");
        app.handle_key(alice_left, ElementState::Pressed)
            .expect("hold Alice's left key");
        app.handle_key(bob_down, ElementState::Pressed)
            .expect("hold Bob's down key");
        assert_ne!(control(&app, 0).pressed_coms, 0);
        assert_ne!(control(&app, 1).pressed_coms, 0);
        app.handle_focus_lost()
            .expect("focus loss clears every local player");
        assert_eq!(control(&app, 0).pressed_coms, 0);
        assert_eq!(control(&app, 1).pressed_coms, 0);

        app.return_to_menu();
        fs::write(
            paths.config_file(),
            "[General]\nLanguageEx=US\nParticipants=\"\"\n",
        )
        .expect("clear configured participants");
        let scenario = app
            .scenario_catalog
            .get("TwoPlayers.c4s")
            .cloned()
            .expect("scenario remains discovered");
        // This deliberately bypasses C4StartupScenSelDlg::DoOK/CanOpen and
        // exercises C4Game's independent late fullscreen guard. The actual
        // ScenarioBrowser route is covered by
        // local_scenario_start_with_no_participants_shows_cpp_error_before_loading.
        app.start_scenario(scenario)
            .expect("begin zero-player scenario load");
        for _ in 0..480 {
            app.update().expect("poll zero-player startup");
            if !matches!(app.mode, AppMode::Loading) {
                break;
            }
            thread::sleep(Duration::from_millis(2));
        }
        assert!(matches!(app.mode, AppMode::Menu));
        assert_eq!(app.startup_view, StartupView::MainMenu);
        assert!(app.loading_state.is_none());
        assert!(app.loader_screen.is_none());
        assert_startup_error_log(
            &app,
            "Failed to start Two players: Fullscreen mode requires at least one participating player.",
        );
        assert!(app.engine.snapshot().players.is_empty());
        assert_eq!(app.control_player_infos.player_count(), 0);
        reset_cached_app_paths();
    }

    fn assert_selected_player_horizontal_release(auto_stop: bool) {
        // C4Game takes Config.General.Participants as PlayerFilenames
        // (C4Game.cpp:362-366), and C4Player::InitControl copies the player
        // file's AutoStopControl preference (C4Player.cpp:2371-2380).
        let install = tempdir().expect("install root");
        install_global_gui_test_root(install.path(), None);
        let player_dir = install.path().join("build/Tyler.c4p");
        fs::create_dir_all(&player_dir).expect("create player file group");
        fs::write(
            player_dir.join("Player.txt"),
            format!(
                "[Player]\nName=Tyler\nScore=250\nTotalPlayingTime=1234\n\n[Preferences]\nControl=0\nAutoStopControl={}\n",
                i32::from(auto_stop)
            ),
        )
        .expect("write player core");
        let user_dir = install.path().join("user-data");
        let _guard = EnvGuard::set(&[
            ("LC_INSTALL_ROOT", Some(install.path())),
            ("LC_USER_DATA_DIR", Some(user_dir.as_path())),
        ]);
        let paths = AppPaths::discover().expect("discover app paths");
        fs::create_dir_all(paths.config_dir()).expect("create config directory");
        fs::write(
            paths.config_file(),
            "[General]\nParticipants=Tyler.c4p\nPlayerPath=\n",
        )
        .expect("write config");
        let mut app = GameApp::new(
            320,
            200,
            AudioOptions::default(),
            Some(&paths),
            RuntimeConfig {
                player_owner: 1,
                player_name: "Player".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("initialise app");
        install_classic_test_assets(&mut app);

        let mut definition =
            Definition::from_script("WLKR", "Walker", walker_script()).expect("crew definition");
        definition.configure_actions(
            Some("Walk".to_string()),
            HashMap::from([(
                "Walk".to_string(),
                ActionSpec::default().with_procedure("Walk"),
            )]),
        );
        definition.set_movement_profile(MovementProfile::default());
        definition.set_crew_member(true);
        app.engine
            .register_definition(definition)
            .expect("register crew definition");
        app.engine
            .set_player_starts(vec![clonk_engine::scenario::PlayerStart {
                ready_crew: vec![("WLKR".to_string(), 1)],
                ..Default::default()
            }]);

        app.join_local_player().expect("join selected player");

        let player = app
            .engine
            .snapshot()
            .players
            .into_iter()
            .find(|player| player.id == app.local_owner)
            .expect("joined player");
        assert_eq!(
            player.control.control_style, auto_stop,
            "the selected player's AutoStopControl preference must reach C4Player"
        );
        assert_eq!(player.player_info_id, 1);
        assert_eq!(player.name, "Tyler");
        assert_eq!(player.score, 250);
        assert_eq!(player.total_playing_time, 1_234);

        let cursor = app
            .engine
            .crew_cursor(app.local_owner)
            .expect("crew cursor");
        app.mode = AppMode::Running;
        let mut keyboard = AppVirtualKeyboard::new(&mut app);
        for (key, held_direction) in [
            (VirtualKeyCode::C, CommandDirection::Right),
            (VirtualKeyCode::Z, CommandDirection::Left),
        ] {
            keyboard.press(key).expect("press movement key");
            assert_eq!(
                keyboard
                    .engine()
                    .object_snapshot(cursor)
                    .expect("cursor after press")
                    .command_direction,
                held_direction,
                "pressed horizontal key must steer"
            );

            keyboard.release(key).expect("release movement key");
            assert_eq!(
                keyboard
                    .engine()
                    .object_snapshot(cursor)
                    .expect("cursor after release")
                    .command_direction,
                if auto_stop {
                    CommandDirection::Stop
                } else {
                    held_direction
                },
                "C4Game::LocalControlKeyUp only synchronizes releases in AutoStopControl mode"
            );
            assert_eq!(
                keyboard.player_control().pressed_coms == 0,
                auto_stop,
                "classic key-up is not synchronized, so C4Player::PressedComs remains held"
            );
        }
    }

    #[test]
    fn selected_player_autostop_stops_horizontal_keys_on_release() {
        // LocalControlKeyUp forwards key-up in AutoStopControl mode
        // (C4Game.cpp:3578-3592).
        assert_selected_player_horizontal_release(true);
    }

    #[test]
    fn autostop_ignores_repeated_physical_keydown_until_release() {
        // Winit reports the operating system's key-repeat as another Pressed
        // event. C4Game::LocalControlKey swallows that repeat for
        // AutoStopControl players before C4Player::InCom can turn it into a
        // COM_Double (C4Game.cpp:3560-3573). A false Down_D makes DFA_PUSH
        // ungrab its target, which is why holding Down while tensioning CATA
        // could unexpectedly deselect the catapult.
        let mut app = GameApp::new(
            320,
            200,
            AudioOptions::default(),
            None,
            RuntimeConfig {
                player_owner: 1,
                player_name: "Repeat tester".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("initialise app");
        install_classic_test_assets(&mut app);

        let mut definition =
            Definition::from_script("WLKR", "Walker", walker_script()).expect("crew definition");
        definition.configure_actions(
            Some("Walk".to_string()),
            HashMap::from([(
                "Walk".to_string(),
                ActionSpec::default().with_procedure("Walk"),
            )]),
        );
        definition.set_movement_profile(MovementProfile::default());
        definition.set_crew_member(true);
        app.engine
            .register_definition(definition)
            .expect("register crew definition");
        app.engine
            .set_player_starts(vec![clonk_engine::scenario::PlayerStart {
                ready_crew: vec![("WLKR".to_string(), 1)],
                ..Default::default()
            }]);
        app.join_local_player().expect("join fresh player");
        app.mode = AppMode::Running;

        let mut keyboard = AppVirtualKeyboard::new(&mut app);
        keyboard
            .press(VirtualKeyCode::X)
            .expect("press physical Down");
        let first_press = keyboard.player_control();
        keyboard
            .press(VirtualKeyCode::X)
            .expect("receive repeated physical Down");
        let repeated_press = keyboard.player_control();

        assert_eq!(
            repeated_press.last_com, first_press.last_com,
            "OS key-repeat must not synthesize a gameplay COM_Down_D"
        );
        assert_eq!(
            repeated_press.last_com_down_double, first_press.last_com_down_double,
            "OS key-repeat must not arm the drop/double-down window"
        );
        keyboard
            .release(VirtualKeyCode::X)
            .expect("release physical Down");
        assert_eq!(keyboard.player_control().pressed_coms, 0);
    }

    #[test]
    fn focus_loss_clears_controls_repeat_tracking_and_pointer_state() {
        let mut app = GameApp::new(
            320,
            200,
            AudioOptions::default(),
            None,
            RuntimeConfig {
                player_owner: 1,
                player_name: "Focus tester".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("initialise app");
        install_classic_test_assets(&mut app);

        let mut definition =
            Definition::from_script("WLKR", "Walker", walker_script()).expect("crew definition");
        definition.configure_actions(
            Some("Walk".to_string()),
            HashMap::from([(
                "Walk".to_string(),
                ActionSpec::default().with_procedure("Walk"),
            )]),
        );
        definition.set_movement_profile(MovementProfile::default());
        definition.set_crew_member(true);
        app.engine
            .register_definition(definition)
            .expect("register crew definition");
        app.engine
            .set_player_starts(vec![clonk_engine::scenario::PlayerStart {
                ready_crew: vec![("WLKR".to_string(), 1)],
                ..Default::default()
            }]);
        app.join_local_player().expect("join fresh player");
        app.mode = AppMode::Running;
        app.ingame_pointer = Some(ViewportPointer {
            owner: app.local_owner,
            world: FloatVector2::new(10.0, 20.0),
            screen: GuiPoint::new(30.0, 40.0),
        });

        AppVirtualKeyboard::new(&mut app)
            .press(VirtualKeyCode::X)
            .expect("press physical Down");
        assert!(!app.pressed_engine_keys.is_empty());
        assert_ne!(
            app.engine
                .snapshot()
                .players
                .into_iter()
                .find(|player| player.id == app.local_owner)
                .expect("local player")
                .control
                .pressed_coms,
            0
        );

        app.handle_focus_lost().expect("handle focus loss");

        assert!(app.pressed_engine_keys.is_empty());
        assert_eq!(
            app.engine
                .snapshot()
                .players
                .into_iter()
                .find(|player| player.id == app.local_owner)
                .expect("local player")
                .control
                .pressed_coms,
            0,
            "focus loss clears synchronized held controls"
        );
        assert_eq!(
            app.ingame_pointer, None,
            "focus loss retains the old pointer_left lifecycle cleanup"
        );
    }

