    #[test]
    fn fresh_player_default_up_key_jumps_and_releases_like_cpp() {
        // A new C++ player selects keyboard set 1 with AutoStopControl
        // (C4StartupPlrSelDlg.cpp:1103-1113), whose Up key is S, not an arrow
        // alias (C4Config.cpp:624-635). WALK Up queues Jump
        // (C4ObjectCom.cpp:335-350), and key-up clears the registered Up bit
        // (C4Game.cpp:3579-3592; C4Player.cpp:1490-1551).
        let mut app = GameApp::new(
            320,
            200,
            AudioOptions::default(),
            None,
            RuntimeConfig {
                player_owner: 1,
                player_name: "Fresh player".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("initialise app");
        install_classic_test_assets(&mut app);

        let mut definition =
            Definition::from_script("JMPR", "Jumper", walker_script()).expect("crew definition");
        definition.configure_actions(
            Some("Walk".to_string()),
            HashMap::from([
                (
                    "Walk".to_string(),
                    ActionSpec::default().with_procedure("walk"),
                ),
                (
                    "Jump".to_string(),
                    ActionSpec::default().with_procedure("flight"),
                ),
            ]),
        );
        definition.set_movement_profile(MovementProfile::default());
        definition.set_physical(clonk_engine::PhysicalInfo {
            walk: 70_000,
            jump: 40_000,
            ..Default::default()
        });
        definition.set_crew_member(true);
        app.engine
            .register_definition(definition)
            .expect("register crew definition");
        app.engine
            .set_player_starts(vec![clonk_engine::scenario::PlayerStart {
                ready_crew: vec![("JMPR".to_string(), 1)],
                ..Default::default()
            }]);
        app.join_local_player().expect("join fresh player");
        app.mode = AppMode::Running;

        let cursor = app
            .engine
            .crew_cursor(app.local_owner)
            .expect("fresh player's cursor");
        assert!(
            app.engine
                .player(app.local_owner)
                .expect("fresh player")
                .control_style(),
            "new players default to AutoStopControl like C++"
        );
        assert_eq!(
            app.bindings.key_for(ControlBindingId::Up),
            Some(VirtualKeyCode::S)
        );

        app.handle_key(VirtualKeyCode::Up, ElementState::Pressed)
            .expect("unbound arrow press");
        assert!(
            app.engine
                .object_snapshot(cursor)
                .expect("cursor after arrow press")
                .command_stack
                .command_names()
                .is_empty(),
            "the default Up arrow must not alias keyboard-set-1 Up"
        );

        app.handle_key(VirtualKeyCode::S, ElementState::Pressed)
            .expect("press keyboard-set-1 Up");
        assert_eq!(
            app.engine
                .object_snapshot(cursor)
                .expect("cursor after S press")
                .command_stack
                .command_names(),
            vec!["Jump".to_string()],
            "S must traverse GameApp input and queue C4CMD_Jump"
        );
        assert_ne!(
            app.engine
                .snapshot()
                .players
                .into_iter()
                .find(|player| player.id == app.local_owner)
                .expect("player after S press")
                .control
                .pressed_coms
                & (1 << clonk_engine::COM_UP),
            0,
            "the Up press must be registered before release"
        );

        app.engine.tick().expect("execute queued jump");
        let jumping = app
            .engine
            .object_snapshot(cursor)
            .expect("cursor after jump tick");
        assert_eq!(jumping.action.name, "Jump");
        assert!(
            jumping.velocity.y < 0,
            "ObjectComJump launches upward (C4ObjectCom.cpp:280-307)"
        );

        app.handle_key(VirtualKeyCode::S, ElementState::Released)
            .expect("release keyboard-set-1 Up");
        assert_eq!(
            app.engine
                .snapshot()
                .players
                .into_iter()
                .find(|player| player.id == app.local_owner)
                .expect("player after S release")
                .control
                .pressed_coms
                & (1 << clonk_engine::COM_UP),
            0,
            "AutoStop key-up clears the registered Up press"
        );
    }

    #[test]
    fn activating_a_scenario_joins_the_local_player_with_crew() {
        // The scenario activation path must join like C4Game::InitPlayers ->
        // C4PlayerList::Join (C4PlayerList.cpp:271-318) so the [Player1]
        // Crew= spec materialises as crew objects, instead of registering a
        // crew-less player.
        let dir = tempdir().expect("tempdir");
        let user_data = tempdir().expect("isolated user data");
        let (_guard, paths) = exact_loader_test_paths(user_data.path(), None);
        configure_test_startup_participant(&paths, user_data.path());
        let scenario_dir = dir.path().join("JoinTest.c4s");
        let def_dir = scenario_dir.join("GOOD.c4d");
        fs::create_dir_all(&def_dir).expect("definition dir");
        fs::write(
            def_dir.join("DefCore.txt"),
            "[DefCore]\nid=GOOD\nName=Good\nCategory=0\nCrewMember=1\n",
        )
        .expect("write DefCore.txt");
        fs::write(def_dir.join("Script.c"), "// crew def\n").expect("write def script");
        write_test_definition_graphics(&def_dir);
        fs::write(
            scenario_dir.join("Scenario.txt"),
            "[Head]\nTitle=JoinTest\n\n[Player1]\nCrew=GOOD=2\nPosition=10,10\n",
        )
        .expect("write Scenario.txt");

        let scenario_data =
            clonk_engine::Scenario::load_from_path_with_languages_and_definition_modules(
                &scenario_dir,
                &InstallDefinitionResolver::new(None),
                &["US"],
                &[def_dir.to_string_lossy()],
            )
            .expect("scenario loads");

        let mut app = GameApp::new(
            320,
            200,
            AudioOptions::default(),
            Some(&paths),
            RuntimeConfig {
                player_owner: 1,
                player_name: "Twonky".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("initialise app");
        app.scenario_game_options = GameOptionButtons::new(
            GameOptionContext::LocalSelector,
            GameOptionValues {
                fair_crew: true,
                fair_crew_strength: 4_321,
                ..GameOptionValues::default()
            },
        );

        let frontend = FrontendScenario {
            identifier: "JoinTest.c4s".to_string(),
            title: "JoinTest".to_string(),
            description: None,
            kind: ScenarioKind::Scenario,
            is_editable: false,
            is_playable: true,
            mission_access: None,
            path: Some(scenario_dir.clone()),
            source_paths: Vec::new(),
            root_label: None,
            preview: None,
            children: Vec::new(),
            title_picture: None,
            folder_index: None,
            icon_index: None,
            difficulty: None,
            author: None,
            version: None,
            local_only: None,
            allow_user_change: None,
            definition_modules: Vec::new(),
        };
        app.activate_loaded_scenario(frontend.clone(), &scenario_data)
            .expect("scenario activates");
        assert!(app.engine.use_fair_crew());
        assert_eq!(app.engine.fair_crew_strength(), 4_321);

        let expected_definition = def_dir.to_string_lossy();
        assert!(matches!(
            app.active_definition_load.as_ref(),
            Some(ScenarioDefinitionLoad::Fixed {
                modules,
                definition_root: None,
            }) if modules == &[expected_definition.as_ref()]
        ));

        assert_eq!(app.local_owner, 0, "local owner adopts the joined number");
        let crew: Vec<_> = app
            .snapshot
            .objects
            .iter()
            .filter(|object| object.crew_member && object.owner == app.local_owner)
            .collect();
        assert_eq!(crew.len(), 2, "Crew=GOOD=2 joins with two crew members");
        let selection = app
            .snapshot
            .crew_selection
            .get(&app.local_owner)
            .expect("crew selection exists after join");
        let cursor = selection
            .cursor
            .expect("the crew cursor is selected at join");
        // AdjustCursorCommand selects exactly the cursor (Cursor->DoSelect,
        // C4Player.cpp:1255-1257) — the app focus must adopt it instead of
        // stacking a second selection.
        assert_eq!(
            selection.selected.as_slice(),
            &[cursor],
            "only the cursor is selected at join"
        );
        assert_eq!(
            app.focus_id,
            Some(cursor),
            "the app focus adopts the join cursor"
        );

        app.restart_current_scenario()
            .expect("restart keeps the effective fixed definition vector");
        wait_for_running(&mut app);
        assert_eq!(
            app.active_scenario
                .as_ref()
                .map(|scenario| (&scenario.identifier, &scenario.path)),
            Some((&frontend.identifier, &frontend.path))
        );
        assert!(matches!(
            app.active_definition_load.as_ref(),
            Some(ScenarioDefinitionLoad::Fixed {
                modules,
                definition_root: None,
            }) if modules == &[expected_definition.as_ref()]
        ));
    }

    #[test]
    fn control_script_errors_are_non_fatal_like_cpp() {
        // C++ surfaces control-time script errors and keeps the session
        // alive (ErrorOrWarning → C4AulExecError::show, C4AulExec.cpp:
        // 1345-1361); only the offending call fails, the game keeps running.
        let script_error = EngineError::Script {
            definition: "CLNK".into(),
            function: "Control".to_string(),
            source: ScriptError::parse("boom", 1, 1),
            recovery: None,
        };
        let status = control_script_error_to_status(script_error)
            .expect("script errors downgrade to a status message");
        assert!(
            status.contains("CLNK"),
            "status names the definition: {status}"
        );

        let fatal = EngineError::CrewSelection {
            owner: 0,
            detail: "broken".into(),
        };
        control_script_error_to_status(fatal).expect_err("engine-model errors stay fatal");

        let boundary = classic_parity_engine_error(ClassicParityBoundary::RunningShortcut {
            key: "unported-test-key",
        });
        assert!(matches!(
            control_script_error_to_status(boundary),
            Err(EngineError::ClassicMenuParityBoundary { .. })
        ));
    }

    #[test]
    fn invalid_script_output_in_controls_is_non_fatal_like_cpp() {
        // Whatever a control script RETURNS is script-caused: C++ coerces
        // every result (static_cast<bool>, C4Object.cpp:3300) and never
        // aborts the input path over it. The Rust-only InvalidScriptOutput
        // class must not kill the window event loop either — it downgrades
        // to a status message exactly like Script errors.
        let output_error = EngineError::InvalidScriptOutput {
            definition: "COWB".into(),
            function: "Control".to_string(),
            detail: "control function `ControlDig` returned garbage".into(),
        };
        let status = control_script_error_to_status(output_error)
            .expect("script-output errors downgrade to a status message");
        assert!(
            status.contains("COWB"),
            "status names the definition: {status}"
        );
    }

    #[test]
    fn engine_errors_remain_recoverable_during_scenario_activation() {
        let recoverable = scenario_activation_engine_error(
            "Broken scenario",
            EngineError::UnknownDefinition("MISS".into()),
        );
        assert!(matches!(
            recoverable,
            ScenarioActivationError::Recoverable(ref message)
                if message.contains("Broken scenario")
        ));
    }

    fn write_preview_png(path: &Path, pixel: [u8; 4]) {
        let file = File::create(path).expect("create preview image");
        let writer = BufWriter::new(file);
        let mut encoder = Encoder::new(writer, 1, 1);
        encoder.set_color(ColorType::Rgba);
        encoder.set_depth(BitDepth::Eight);
        let mut writer = encoder.write_header().expect("write PNG header");
        writer
            .write_image_data(&pixel)
            .expect("write PNG pixel data");
    }

    fn write_preview_image(path: &Path, pixel: [u8; 4], format: image::ImageFormat) {
        image::save_buffer_with_format(path, &pixel, 1, 1, image::ColorType::Rgba8, format)
            .expect("write preview image");
    }

    fn install_global_gui_test_root(root: &Path, missing_sheet: Option<&str>) {
        let repository = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(Path::parent)
            .and_then(Path::parent)
            .expect("repository root");
        let system = root.join("planet/System.c4g");
        let graphics = root.join("planet/Graphics.c4g");
        fs::create_dir_all(&system).expect("fixture System.c4g");
        fs::create_dir_all(&graphics).expect("fixture Graphics.c4g");
        fs::copy(
            repository.join("planet/System.c4g/Endeavour.ttf"),
            system.join("Endeavour.ttf"),
        )
        .expect("copy fixture Endeavour font");
        for (_, canonical_name) in CLASSIC_GLOBAL_GUI_SHEETS {
            if missing_sheet == Some(canonical_name) {
                continue;
            }
            fs::copy(
                repository.join("planet/Graphics.c4g").join(canonical_name),
                graphics.join(canonical_name),
            )
                .unwrap_or_else(|error| panic!("copy fixture {canonical_name}: {error}"));
        }
        for cursor_name in [
            "CursorSmall.png",
            "CursorMedium.png",
            "CursorLarge.png",
            "CursorXLarge.png",
            "CursorXXLarge.png",
            "CursorXXXLarge.png",
            "CursorXXXXLarge.png",
            "CursorXXXXXLarge.png",
        ] {
            fs::copy(
                repository.join("planet/Graphics.c4g").join(cursor_name),
                graphics.join(cursor_name),
            )
            .unwrap_or_else(|error| panic!("copy fixture {cursor_name}: {error}"));
        }
    }

