    #[test]
    fn definition_file_scan_is_flat_case_insensitive_and_raw_ordered() {
        let root = tempdir().expect("definition root");
        fs::create_dir(root.path().join("Folder.C4D")).expect("definition directory");
        fs::write(root.path().join("Packed.c4d"), b"pack").expect("definition file");
        fs::create_dir(root.path().join("Ignore.c4f")).expect("ignored folder");
        fs::create_dir_all(root.path().join("Nested/Hidden.c4d")).expect("nested definition");

        let expected = fs::read_dir(root.path())
            .expect("raw directory iteration")
            .map(|entry| entry.expect("entry").path())
            .filter(|path| {
                path.extension()
                    .and_then(|extension| extension.to_str())
                    .is_some_and(|extension| extension.eq_ignore_ascii_case("c4d"))
            })
            .collect::<Vec<_>>();
        let actual = enumerate_startup_definition_files(root.path()).expect("definition scan");
        assert_eq!(actual, expected, "the selector must not sort readdir order");
        assert_eq!(actual.len(), 2);
    }

    #[test]
    fn definition_selector_app_route_keeps_recursive_error_refresh_and_cancel_modal() {
        let _lock = env_lock().lock();
        reset_cached_app_paths();
        let user_data = tempdir().expect("isolated user data");
        let executable_data = tempdir().expect("isolated executable data");
        let definition_root = executable_data.path().join("Definitions");
        fs::create_dir_all(definition_root.join("Alpha.c4d")).expect("fixed definition");
        fs::create_dir(definition_root.join("Beta.C4D")).expect("optional definition");
        let (_guard, paths) =
            exact_loader_test_paths(user_data.path(), Some(executable_data.path()));
        configure_test_startup_participant(&paths, user_data.path());
        persist_config_value(&paths, "General", "DefinitionPath", "Definitions/")
            .expect("configure selector root");
        let configured_definition_paths =
            startup_definition_paths(&paths).expect("read configured definition paths");
        assert_eq!(
            configured_definition_paths,
            StartupDefinitionPaths {
                selector_root: definition_root.clone(),
                active_custom_root: Some(definition_root.clone()),
            }
        );
        assert_eq!(
            path_to_legacy_bytes(
                configured_definition_paths
                    .active_custom_root
                    .as_deref()
                    .expect("active definition prefix")
            )
            .last(),
            Some(&(std::path::MAIN_SEPARATOR as u8)),
            "the active prefix retains DefinitionPath's trailing separator"
        );
        let external = tempdir().expect("absolute definition prefix");
        let external_value = format!(
            "{}{sep}",
            external.path().display(),
            sep = std::path::MAIN_SEPARATOR
        );
        persist_config_value(&paths, "General", "DefinitionPath", &external_value)
            .expect("configure absolute definition prefix");
        let absolute_paths =
            startup_definition_paths(&paths).expect("read absolute definition prefix");
        assert_eq!(
            absolute_paths.selector_root,
            concatenate_legacy_path(
                &path_with_trailing_native_separator(executable_data.path()),
                &clonk_script::c4_string_bytes(&external_value),
            ),
            "the selector uses raw ExePath + DefinitionPath concatenation"
        );
        assert_eq!(
            path_to_legacy_bytes(
                absolute_paths
                    .active_custom_root
                    .as_deref()
                    .expect("absolute prefix is active")
            ),
            normalize_legacy_path_bytes(clonk_script::c4_string_bytes(&external_value)),
            "game loading honors an absolute DefinitionPath independently"
        );
        let missing_definition_root = executable_data.path().join("missing-definitions");
        persist_config_value(&paths, "General", "DefinitionPath", "/missing-definitions/")
            .expect("configure absent selector root");
        assert_eq!(
            startup_definition_paths(&paths).expect("read absent definition paths"),
            StartupDefinitionPaths {
                selector_root: missing_definition_root,
                active_custom_root: None,
            },
            "the selector displays an absent configured path, but C4Game does not expand it"
        );
        persist_config_value(&paths, "General", "DefinitionPath", "Definitions/")
            .expect("restore selector root");
        let mut app = GameApp::new(
            1280,
            720,
            AudioOptions {
                sound_enabled: false,
                music_enabled: false,
                menu_music_enabled: false,
                menu_sound_enabled: false,
                ..AudioOptions::default()
            },
            Some(&paths),
            RuntimeConfig {
                player_owner: 1,
                player_name: "Definition Tester".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("initialise app");
        wait_for_menu(&mut app);
        app.open_scenario_browser();

        let mut scenario = FrontendScenario::fallback();
        scenario.path = Some(user_data.path().join("Start.c4s"));
        scenario.local_only = Some(false);
        scenario.allow_user_change = Some(true);
        scenario.definition_modules = vec!["Alpha.c4d".to_string()];
        app.menu_state.definition_checkbox_checked = false;
        app.open_definition_selector(scenario.clone())
            .expect("open definition selector");

        let controller = app.definition_selector.as_ref().expect("selector opens");
        assert_eq!(
            app.pending_definition_selection
                .as_ref()
                .and_then(|pending| pending.custom_definition_root.as_deref()),
            Some(definition_root.as_path())
        );
        assert_eq!(
            controller.root_path(),
            format!(
                "{}{sep}",
                definition_root.display(),
                sep = std::path::MAIN_SEPARATOR
            )
        );
        assert!(controller
            .rows()
            .iter()
            .any(|row| { row.filename() == "Alpha.c4d" && row.is_fixed() && row.is_checked() }));
        assert!(controller
            .rows()
            .iter()
            .any(|row| row.filename() == "Beta.C4D"));
        assert_eq!(controller.selected_index(), None);

        let mut frame = vec![0_u8; 1280 * 720 * 4];
        app.render(&mut frame)
            .expect("exact classic selector resources render");
        app.handle_key(VirtualKeyCode::Return, ElementState::Pressed)
            .expect("unselected Enter opens recursive error");
        assert!(app.definition_selector.is_some());
        assert_eq!(app.message_dialogs.len(), 1);
        assert_eq!(app.message_dialogs[0].state.caption(), "Error");
        assert_eq!(
            app.message_dialogs[0].state.message(),
            "Please select a file first!"
        );
        app.render(&mut frame)
            .expect("nested message renders above inactive selector");
        app.finish_message_dialog(clonk_frontend::message_dialog::MessageDialogResult::Ok)
            .expect("close nested error");
        app.handle_key(VirtualKeyCode::Return, ElementState::Released)
            .expect("the error-opening release remains captured");

        app.handle_key(VirtualKeyCode::F5, ElementState::Pressed)
            .expect("F5 refreshes selector");
        let controller = app.definition_selector.as_ref().expect("selector remains");
        assert_eq!(controller.selected_index(), None);
        assert!(
            controller.rows().iter().all(|row| !row.is_checked()),
            "C4DefinitionSelDlg does not reapply even fixed checks after F5"
        );
        app.handle_key(VirtualKeyCode::F5, ElementState::Released)
            .expect("release refresh key");

        app.process_gamepad_event_batch([
            GamepadEvent::Direction {
                slot: GamepadSlot::new(0),
                button: ControlButton::Right,
                state: ElementState::Pressed,
            },
            GamepadEvent::GuiButton {
                slot: GamepadSlot::new(0),
                class: GuiButtonClass::Low,
                state: ElementState::Pressed,
            },
            GamepadEvent::GuiButton {
                slot: GamepadSlot::new(0),
                class: GuiButtonClass::Low,
                state: ElementState::Released,
            },
        ])
        .expect("gamepad OK release opens recursive selection error");
        assert_eq!(app.message_dialogs.len(), 1);
        app.finish_message_dialog(clonk_frontend::message_dialog::MessageDialogResult::Ok)
            .expect("dismiss gamepad selection error by non-gamepad input");
        app.process_gamepad_event_batch([
            GamepadEvent::Direction {
                slot: GamepadSlot::new(0),
                button: ControlButton::Left,
                state: ElementState::Pressed,
            },
            GamepadEvent::Direction {
                slot: GamepadSlot::new(0),
                button: ControlButton::Down,
                state: ElementState::Pressed,
            },
        ])
        .expect("next gamepad gesture reaches the selector");
        assert_eq!(
            app.definition_selector
                .as_ref()
                .and_then(|controller| controller.selected_index()),
            Some(1),
            "focus return selects the first row and the following Down reaches the second"
        );

        app.handle_key(VirtualKeyCode::Escape, ElementState::Pressed)
            .expect("Escape cancels selector");
        assert!(app.definition_selector.is_none());
        assert!(app.pending_definition_selection.is_none());
        assert!(
            app.definition_selector_consumed_keys
                .contains(&VirtualKeyCode::Escape),
            "close-on-key-down retains the matching physical release"
        );
        app.handle_key(VirtualKeyCode::Escape, ElementState::Released)
            .expect("captured Escape release");
        assert!(app.definition_selector_consumed_keys.is_empty());
        assert!(
            !app.menu_state.definition_checkbox_checked,
            "cancel must retain the user's current checkbox toggle"
        );

        app.open_definition_selector(scenario.clone())
            .expect("open definition selector");
        app.process_gamepad_event_batch([
            GamepadEvent::GuiButton {
                slot: GamepadSlot::new(0),
                class: GuiButtonClass::High,
                state: ElementState::Pressed,
            },
            GamepadEvent::Action {
                slot: GamepadSlot::new(0),
                action: GamepadActionType::Cancel,
                state: ElementState::Pressed,
            },
            GamepadEvent::GuiButton {
                slot: GamepadSlot::new(0),
                class: GuiButtonClass::High,
                state: ElementState::Released,
            },
        ])
        .expect("high gamepad button cancels and captures duplicate batch events");
        assert!(app.definition_selector.is_none());
        assert_eq!(app.startup_view, StartupView::ScenarioBrowser);

        app.open_definition_selector(scenario.clone())
            .expect("open definition selector");
        app.handle_cursor_moved(PhysicalPosition::new(10.0, 10.0))
            .expect("move over selector backdrop");
        app.handle_mouse_button(ElementState::Pressed)
            .expect("selector acquires pointer gesture");
        assert!(app.definition_selector_pointer_capture);
        app.process_definition_selector_actions(vec![
            clonk_frontend::definition_sel::DefinitionSelAction::Cancelled,
        ])
        .expect("close selector before physical pointer release");
        assert!(app.definition_selector_pointer_capture);
        app.handle_mouse_button(ElementState::Released)
            .expect("closed selector consumes pointer release");
        assert!(!app.definition_selector_pointer_capture);
        assert_eq!(app.startup_view, StartupView::ScenarioBrowser);

        app.open_definition_selector(scenario.clone())
            .expect("open definition selector");
        app.handle_touch(TouchPhase::Started, GuiPoint::new(10.0, 10.0))
            .expect("selector acquires touch gesture");
        app.process_definition_selector_actions(vec![
            clonk_frontend::definition_sel::DefinitionSelAction::Cancelled,
        ])
        .expect("close selector before touch end");
        assert!(app.definition_selector_pointer_capture);
        app.handle_touch(TouchPhase::Ended, GuiPoint::new(10.0, 10.0))
            .expect("closed selector consumes touch end");
        assert!(!app.definition_selector_pointer_capture);

        // Low activates OK on release. Keep the remainder of that same
        // gamepad batch away from the newly running sandbox.
        let mut sandbox = scenario;
        sandbox.path = None;
        app.open_definition_selector(sandbox)
            .expect("open definition selector");
        app.process_gamepad_event_batch([
            GamepadEvent::Direction {
                slot: GamepadSlot::new(0),
                button: ControlButton::Down,
                state: ElementState::Pressed,
            },
            GamepadEvent::Direction {
                slot: GamepadSlot::new(0),
                button: ControlButton::Right,
                state: ElementState::Pressed,
            },
            GamepadEvent::Direction {
                slot: GamepadSlot::new(0),
                button: ControlButton::Right,
                state: ElementState::Pressed,
            },
            GamepadEvent::GuiButton {
                slot: GamepadSlot::new(0),
                class: GuiButtonClass::Low,
                state: ElementState::Pressed,
            },
            GamepadEvent::GuiButton {
                slot: GamepadSlot::new(0),
                class: GuiButtonClass::Low,
                state: ElementState::Released,
            },
            GamepadEvent::Action {
                slot: GamepadSlot::new(0),
                action: GamepadActionType::MenuToggle,
                state: ElementState::Pressed,
            },
        ])
        .expect("release-close captures duplicate gamepad aliases");
        assert!(matches!(app.mode, AppMode::Running));
        assert!(app.definition_selector.is_none());
        assert!(app.ingame_menu.is_none());

        // Exercise the asynchronous app handoff, not only the engine API:
        // a valid DefinitionPath contributes the rooted block first, and the
        // effective fixed vector survives Restart and exact save/load.
        app.return_to_menu();
        let scenario_path = user_data.path().join("Start.c4s");
        let rooted_objects = definition_root.join("Objects.c4d");
        let original_objects = executable_data.path().join("Objects.c4d");
        fs::create_dir_all(&scenario_path).expect("rooted scenario group");
        fs::create_dir_all(&rooted_objects).expect("rooted Objects definition group");
        fs::create_dir_all(&original_objects).expect("original Objects definition group");
        fs::write(
            rooted_objects.join("DefCore.txt"),
            "[DefCore]\nid=ROOT\nName=Rooted\nCategory=1\n",
        )
        .expect("rooted Objects DefCore");
        fs::write(
            original_objects.join("DefCore.txt"),
            "[DefCore]\nid=ORIG\nName=Original\nCategory=1\n",
        )
        .expect("original Objects DefCore");
        write_test_definition_graphics(&rooted_objects);
        write_test_definition_graphics(&original_objects);
        fs::write(
            scenario_path.join("Scenario.txt"),
            "[Head]\nTitle=Definition Root Start\n",
        )
        .expect("rooted scenario core");
        let mut rooted_scenario = FrontendScenario::fallback();
        rooted_scenario.identifier = "rooted-start".to_string();
        rooted_scenario.title = "Definition Root Start".to_string();
        rooted_scenario.path = Some(scenario_path.clone());
        app.start_scenario_with_definition_modules(
            rooted_scenario.clone(),
            vec!["Objects.c4d".to_string()],
            Some(definition_root.clone()),
        )
        .expect("start with active custom definition root");
        wait_for_running(&mut app);
        let expected_effective = vec![
            rooted_objects.to_string_lossy().into_owned(),
            original_objects.to_string_lossy().into_owned(),
        ];
        assert!(matches!(
            app.active_definition_load.as_ref(),
            Some(ScenarioDefinitionLoad::Fixed {
                modules,
                definition_root: None,
            }) if modules == &expected_effective
        ));
        app.restart_current_scenario()
            .expect("restart rooted definition scenario");
        wait_for_running(&mut app);
        assert!(matches!(
            app.active_definition_load.as_ref(),
            Some(ScenarioDefinitionLoad::Fixed {
                modules,
                definition_root: None,
            }) if modules == &expected_effective
        ));
        app.quick_save()
            .expect("save preserves the effective definition vector");
        app.active_definition_load = None;
        app.quick_load()
            .expect("save reload resolves the preserved definition vector");
        assert!(matches!(
            app.active_definition_load.as_ref(),
            Some(ScenarioDefinitionLoad::Fixed {
                modules,
                definition_root: None,
            }) if modules == &expected_effective
        ));
        cleanup_quicksave_file();
        reset_cached_app_paths();
    }

    #[test]
    fn network_create_navigates_nested_selector_and_retains_netdlg_without_binding() {
        let mut target = FrontendScenario::fallback();
        target.identifier = "outer/inner/target.c4s".to_string();
        target.title = "Deep Target".to_string();
        target.path = None;
        target.allow_user_change = Some(true);

        let mut inner = FrontendScenario::fallback();
        inner.identifier = "outer/inner".to_string();
        inner.title = "Inner Target Folder".to_string();
        inner.kind = ScenarioKind::Folder;
        inner.is_playable = false;
        inner.path = None;
        inner.children = vec![target.clone()];

        let mut outer = FrontendScenario::fallback();
        outer.identifier = "outer".to_string();
        outer.title = "Outer Folder".to_string();
        outer.kind = ScenarioKind::Folder;
        outer.is_playable = false;
        outer.path = None;
        outer.children = vec![inner.clone()];

        let scenarios = vec![outer];
        let menu = StartupMenu::new(build_menu_entries(&scenarios, false), test_font(), None)
            .expect("nested selector menu");
        let mut app = new_menu_app(800, 600);
        app.menu_state = MenuState::new(menu, scenarios.clone());
        app.scenario_catalog = build_scenario_catalog(&scenarios);
        app.open_network_game_dialog();
        app.startup_network_dialog
            .as_mut()
            .expect("retained NetDlg")
            .set_join_address("remembered.example:11112");

        app.process_network_dialog_actions(vec![
            clonk_frontend::startup_netdlg::NetDlgAction::CreateGame,
        ])
        .expect("open network scenario selector");
        assert_eq!(app.startup_view, StartupView::ScenarioBrowser);
        assert_eq!(
            app.scenario_selector_mode,
            ScenarioSelectorMode::NetworkHost
        );
        assert_eq!(
            app.scenario_game_options.context(),
            GameOptionContext::NetworkHostSelector
        );
        assert!(app.network.is_none());
        assert!(app.network_mode.is_none());
        assert!(app.network_lobby.is_none());
        assert!(app.startup_network_connection.is_none());

        assert_eq!(
            app.menu_state
                .selected_scenario()
                .map(|entry| entry.identifier.as_str()),
            Some("outer")
        );
        app.handle_menu_input(|menu| menu.menu().handle_key_down(KeyCode::Enter))
            .expect("press outer folder");
        app.handle_menu_input(|menu| menu.menu().handle_key_up(KeyCode::Enter))
            .expect("release outer folder");
        assert_eq!(
            app.menu_state
                .stack
                .iter()
                .map(|layer| layer.title.as_str())
                .collect::<Vec<_>>(),
            vec!["Scenarios", "Outer Folder"]
        );
        assert_eq!(
            app.menu_state
                .selected_scenario()
                .map(|entry| entry.identifier.as_str()),
            Some("outer/inner")
        );
        app.handle_menu_input(|menu| menu.menu().handle_key_down(KeyCode::Enter))
            .expect("press inner folder");
        app.handle_menu_input(|menu| menu.menu().handle_key_up(KeyCode::Enter))
            .expect("release inner folder");
        assert_eq!(
            app.menu_state
                .stack
                .iter()
                .map(|layer| layer.title.as_str())
                .collect::<Vec<_>>(),
            vec!["Scenarios", "Outer Folder", "Inner Target Folder"]
        );
        assert_eq!(
            app.scenario_selector_mode,
            ScenarioSelectorMode::NetworkHost
        );

        app.scensel_do_back()
            .expect("leave exactly one nested folder");
        assert_eq!(app.menu_state.stack.len(), 2);
        assert_eq!(app.menu_state.book_caption(), "Outer Folder");
        assert_eq!(app.startup_view, StartupView::ScenarioBrowser);

        app.open_definition_selector(target.clone())
            .expect("open definition selector");
        assert_eq!(
            app.pending_definition_selection
                .as_ref()
                .map(|pending| pending.selector_mode),
            Some(ScenarioSelectorMode::NetworkHost)
        );
        app.process_definition_selector_actions(vec![
            clonk_frontend::definition_sel::DefinitionSelAction::RefreshRequested,
        ])
        .expect("refresh retains network selector mode");
        assert_eq!(
            app.pending_definition_selection
                .as_ref()
                .map(|pending| pending.selector_mode),
            Some(ScenarioSelectorMode::NetworkHost)
        );
        app.process_definition_selector_actions(vec![
            clonk_frontend::definition_sel::DefinitionSelAction::Cancelled,
        ])
        .expect("cancel network definition selector");
        assert_eq!(
            app.scenario_selector_mode,
            ScenarioSelectorMode::NetworkHost
        );
        assert_eq!(app.startup_view, StartupView::ScenarioBrowser);

        app.open_definition_selector(target)
            .expect("open definition selector");
        app.process_definition_selector_actions(vec![
            clonk_frontend::definition_sel::DefinitionSelAction::Accepted(Vec::new()),
        ])
        .expect("accepted definition list returns to network staging");
        assert_eq!(
            app.scenario_selector_mode,
            ScenarioSelectorMode::NetworkHost
        );
        assert!(app.startup_network_connection.is_none());
        assert!(app.network.is_none());
        assert!(app.network_lobby.is_none());

        app.scensel_do_back()
            .expect("return from outer folder to root");
        assert_eq!(app.menu_state.stack.len(), 1);
        assert_eq!(app.startup_view, StartupView::ScenarioBrowser);
        app.scensel_do_back()
            .expect("network root Back returns to NetDlg");
        assert_eq!(app.startup_view, StartupView::NetworkGame);
        assert_eq!(
            app.startup_network_dialog
                .as_ref()
                .expect("same retained NetDlg")
                .join_address(),
            "remembered.example:11112"
        );
        assert!(app.startup_network_connection.is_none());
    }

    #[test]
    fn scenario_game_options_load_persist_force_and_use_classic_input_dialog() {
        let _lock = env_lock().lock();
        let repository = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(Path::parent)
            .and_then(Path::parent)
            .expect("repository root");
        let user_data = tempdir().expect("isolated game-option config");
        let _guard = EnvGuard::set(&[
            ("LC_INSTALL_ROOT", Some(repository)),
            ("LC_USER_DATA_DIR", Some(user_data.path())),
        ]);
        let paths = AppPaths::discover().expect("discover app paths");
        if let Some(parent) = paths.config_file().parent() {
            fs::create_dir_all(parent).expect("create native config directory");
        }
        fs::write(paths.config_file(), b"[General]\r\nFairCrew=true\r\n")
            .expect("seed non-native fair-crew spelling");
        assert!(!load_fair_crew_flag(Some(&paths)));
        assert!(!load_scenario_game_option_values(Some(&paths)).fair_crew);
        fs::remove_file(paths.config_file()).expect("remove non-native fair-crew config");

        for (section, key, value) in [
            ("General", "DefCrewStrength", "777"),
            ("General", "Record", "0"),
            ("Network", "MasterServerSignUp", "0"),
            ("Network", "LeagueServerSignUp", "1"),
            ("Network", "Comment", "old comment"),
            ("Network", "LastPassword", "old password"),
        ] {
            persist_config_value(&paths, section, key, value).expect("seed game option");
        }
        persist_native_config_values(
            &paths,
            "General",
            &[("NoCrew", clonk_app::NativeConfigValue::RawAscii("true"))],
        )
        .expect("seed C++ NoCrew Boolean");
        assert!(
            load_fair_crew_flag(Some(&paths)),
            "the scen-sel flag reads C4ConfigGeneral's native NoCrew key"
        );
        let values = load_scenario_game_option_values(Some(&paths));
        assert!(values.fair_crew);
        assert_eq!(values.fair_crew_strength, 777);
        assert!(!values.record);
        assert!(!values.master_server_signup);
        assert!(values.league_server_signup);
        assert_eq!(values.comment, "old comment");
        assert_eq!(values.last_password, "old password");

        let scenario_path = user_data.path().join("Forced.c4s");
        fs::create_dir_all(&scenario_path).expect("forced scenario group");
        fs::write(
            scenario_path.join("Scenario.txt"),
            "[Head]\nTitle=Forced\nForcedNoCrew=2\n",
        )
        .expect("forced scenario core");
        let mut forced = FrontendScenario::fallback();
        forced.path = Some(scenario_path);
        assert_eq!(
            scenario_fair_crew_constraint(Some(&forced)),
            FairCrewConstraint::ForceNormal
        );
        let mut controller =
            GameOptionButtons::new(GameOptionContext::LocalSelector, values.clone());
        controller.set_selector_fair_crew_constraint(FairCrewConstraint::ForceNormal);
        let fair = controller
            .view(clonk_frontend::game_option_buttons::GameOptionButton::FairCrew)
            .expect("fair-crew button");
        assert!(!fair.enabled);
        assert_eq!(
            fair.icon,
            clonk_frontend::game_option_buttons::GameOptionIcon::NormalCrewGray
        );

        let mut app = GameApp::new(
            800,
            600,
            AudioOptions {
                sound_enabled: false,
                music_enabled: false,
                menu_music_enabled: false,
                menu_sound_enabled: false,
                ..AudioOptions::default()
            },
            Some(&paths),
            RuntimeConfig {
                player_owner: 1,
                player_name: "Option Tester".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("game-option app");
        wait_for_menu(&mut app);
        app.open_scenario_browser();
        let fonts = app
            .assets
            .clonk_fonts
            .as_deref()
            .expect("classic GUI fonts");
        let bounds = startup_scensel_game_option_bounds(800, 600, fonts);
        let option_layout = clonk_frontend::game_option_buttons::game_option_buttons_layout(
            bounds,
            GameOptionContext::LocalSelector,
        );
        let scensel_layout = clonk_frontend::startup_scensel::scen_sel_layout(800, 600, fonts);
        assert_eq!(
            option_layout.rect(clonk_frontend::game_option_buttons::GameOptionButton::FairCrew),
            Some(scensel_layout.fair_crew_button)
        );
        assert_eq!(
            option_layout.rect(clonk_frontend::game_option_buttons::GameOptionButton::Record),
            Some(scensel_layout.record_button)
        );

        app.process_game_option_actions(vec![GameOptionAction::FairCrewPreferenceChanged(false)])
            .expect("persist disabled native fair-crew preference");
        let native_config = fs::read(paths.config_file()).expect("read disabled native preference");
        assert!(native_config
            .split(|byte| matches!(*byte, b'\r' | b'\n'))
            .any(|line| line == b"NoCrew=false"));
        assert!(!native_config
            .windows(b"FairCrew=".len())
            .any(|window| window == b"FairCrew="));
        assert!(!load_fair_crew_flag(Some(&paths)));
        assert!(!load_scenario_game_option_values(Some(&paths)).fair_crew);

        app.process_game_option_actions(vec![
            GameOptionAction::RecordPreferenceChanged(true),
            GameOptionAction::InternetSignupChanged {
                enabled: true,
                live_lobby: false,
            },
            GameOptionAction::LeagueSignupChanged(false),
            GameOptionAction::CommentChanged("new comment".to_string()),
        ])
        .expect("persist selector options");
        let config = Config::load(paths.config_file()).expect("reload persisted options");
        assert_eq!(config.get_in(Some("General"), "NoCrew"), Some("false"));
        assert_eq!(config.get_in(Some("General"), "FairCrew"), None);
        assert_eq!(config.get_in(Some("General"), "Record"), Some("1"));
        assert_eq!(
            config.get_in(Some("General"), "DefCrewStrength"),
            Some("777")
        );
        assert_eq!(
            config.get_in(Some("Network"), "MasterServerSignUp"),
            Some("1")
        );
        assert_eq!(
            config.get_in(Some("Network"), "LeagueServerSignUp"),
            Some("0")
        );
        assert_eq!(
            config.get_in(Some("Network"), "Comment"),
            Some("new comment")
        );

        app.process_game_option_actions(vec![GameOptionAction::FairCrewPreferenceChanged(true)])
            .expect("persist native fair-crew preference");
        let config = Config::load(paths.config_file()).expect("reload native fair-crew key");
        assert_eq!(config.get_in(Some("General"), "NoCrew"), Some("true"));
        assert_eq!(config.get_in(Some("General"), "FairCrew"), None);
        let native_config = fs::read(paths.config_file()).expect("read enabled native preference");
        assert!(native_config
            .split(|byte| matches!(*byte, b'\r' | b'\n'))
            .any(|line| line == b"NoCrew=true"));
        assert!(!native_config
            .windows(b"FairCrew=".len())
            .any(|window| window == b"FairCrew="));
        assert!(load_fair_crew_flag(Some(&paths)));
        assert!(load_scenario_game_option_values(Some(&paths)).fair_crew);

        app.scenario_game_options =
            GameOptionButtons::new(GameOptionContext::NetworkHostSelector, values);
        let actions = app.scenario_game_options.handle_hotkey('P');
        app.finish_game_option_input(actions)
            .expect("open classic password input");
        let dialog = app
            .game_option_input_dialog
            .as_ref()
            .expect("password InputDialog");
        assert_eq!(
            dialog.purpose,
            PendingInputDialogPurpose::GameOption(GameOptionInputKind::Password)
        );
        assert_eq!(dialog.controller.caption(), "Password");
        assert_eq!(dialog.controller.text(), "old password");
        app.process_game_option_input_dialog_actions(vec![InputDialogAction::Accepted(
            "new password".to_string(),
        )])
        .expect("accept classic password input");
        assert_eq!(app.scenario_game_options.values().password, "new password");
        assert_eq!(
            Config::load(paths.config_file())
                .expect("reload password")
                .get_in(Some("Network"), "LastPassword"),
            Some("new password")
        );
        reset_cached_app_paths();
    }

    #[test]
    fn game_option_input_dialog_is_modal_and_pointer_capture_is_per_gesture() {
        let _lock = env_lock().lock();
        let repository = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(Path::parent)
            .and_then(Path::parent)
            .expect("repository root");
        let user_data = tempdir().expect("isolated input-dialog config");
        let _guard = EnvGuard::set(&[
            ("LC_INSTALL_ROOT", Some(repository)),
            ("LC_USER_DATA_DIR", Some(user_data.path())),
        ]);
        let paths = AppPaths::discover().expect("discover app paths");
        let mut app = GameApp::new(
            800,
            600,
            AudioOptions::default(),
            Some(&paths),
            RuntimeConfig {
                player_owner: 1,
                player_name: "Modal Tester".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("input-dialog app");
        wait_for_menu(&mut app);
        app.open_scenario_browser();
        app.menu_state.set_search_text("underlying search");
        let selected = app.menu_state.menu.selected_index();
        let stack_len = app.menu_state.stack.len();
        app.scenario_game_options = GameOptionButtons::new(
            GameOptionContext::NetworkHostSelector,
            GameOptionValues::default(),
        );
        let actions = app.scenario_game_options.handle_hotkey('P');
        app.finish_game_option_input(actions)
            .expect("open password modal");

        app.handle_modifiers_changed(ModifiersState::CTRL | ModifiersState::ALT)
            .expect("hold combined mnemonic modifiers");
        app.handle_key(VirtualKeyCode::O, ElementState::Pressed)
            .expect("combined modifiers do not activate the exact Alt mnemonic");
        app.handle_key(VirtualKeyCode::O, ElementState::Released)
            .expect("release combined mnemonic probe");
        assert!(app.game_option_input_dialog.is_some());
        app.handle_modifiers_changed(ModifiersState::SHIFT)
            .expect("hold Shift over regular input dialog");
        app.handle_key(VirtualKeyCode::Escape, ElementState::Pressed)
            .expect("modified Escape does not cancel the regular dialog");
        app.handle_key(VirtualKeyCode::Escape, ElementState::Released)
            .expect("release modified Escape probe");
        assert!(app.game_option_input_dialog.is_some());
        app.handle_modifiers_changed(ModifiersState::empty())
            .expect("release modal modifiers");

        for key in [
            VirtualKeyCode::Up,
            VirtualKeyCode::Down,
            VirtualKeyCode::Left,
        ] {
            app.handle_key(key, ElementState::Pressed)
                .expect("modal key down");
            app.handle_key(key, ElementState::Released)
                .expect("modal key up");
        }
        assert_eq!(app.menu_state.menu.selected_index(), selected);
        assert_eq!(app.menu_state.stack.len(), stack_len);
        assert_eq!(app.menu_state.search_text(), "underlying search");
        assert_eq!(app.startup_view, StartupView::ScenarioBrowser);

        app.handle_key(VirtualKeyCode::Apps, ElementState::Pressed)
            .expect("open modal edit context");
        assert!(app.context_menu.is_some());
        assert!(
            GameApp::startup_base_context_menu(app.context_menu.as_ref(), true,).is_none(),
            "modal owns the one context-menu render pass"
        );
        app.handle_key(VirtualKeyCode::Apps, ElementState::Released)
            .expect("consume Apps release inside modal");
        app.close_context_menu_silently();

        let layout = app.game_option_input_layout().expect("modal layout");
        let edit_point = PhysicalPosition::new(
            f64::from(layout.edit.x + layout.edit.w / 2),
            f64::from(layout.edit.y + layout.edit.h / 2),
        );
        app.handle_cursor_moved(edit_point)
            .expect("point into modal edit");
        app.handle_mouse_button(ElementState::Pressed)
            .expect("hold modal left button");
        assert_eq!(
            app.game_option_input_pointer_capture,
            Some(ContextMenuPointerButton::Left)
        );
        app.process_game_option_input_dialog_actions(vec![InputDialogAction::Cancelled])
            .expect("close modal while left is held");
        assert!(app.game_option_input_dialog.is_none());
        app.handle_mouse_button(ElementState::Released)
            .expect("consume modal-owned left release");
        assert_eq!(app.game_option_input_pointer_capture, None);
        assert_eq!(app.menu_state.menu.selected_index(), selected);

        let actions = app.scenario_game_options.handle_hotkey('P');
        app.finish_game_option_input(actions)
            .expect("reopen password modal");
        app.handle_cursor_moved(edit_point)
            .expect("point into reopened modal");
        app.handle_other_mouse_button(ElementState::Pressed)
            .expect("modal middle down");
        assert_eq!(
            app.game_option_input_pointer_capture,
            Some(ContextMenuPointerButton::Other)
        );
        app.handle_other_mouse_button(ElementState::Released)
            .expect("modal middle up");
        assert_eq!(app.game_option_input_pointer_capture, None);
        reset_cached_app_paths();
    }

    #[test]
    fn resize_cancels_selector_option_and_input_dialog_interactions() {
        let _lock = env_lock().lock();
        let repository = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(Path::parent)
            .and_then(Path::parent)
            .expect("repository root");
        let user_data = tempdir().expect("isolated resize config");
        let _guard = EnvGuard::set(&[
            ("LC_INSTALL_ROOT", Some(repository)),
            ("LC_USER_DATA_DIR", Some(user_data.path())),
        ]);
        let paths = AppPaths::discover().expect("discover app paths");
        let mut app = new_menu_app_with_paths(800, 600, &paths);
        app.open_scenario_browser();
        app.scenario_game_options.set_focused_button(Some(
            clonk_frontend::game_option_buttons::GameOptionButton::Record,
        ));
        app.menu_state.set_dialog_focus(ScenselDialogFocus::Options);
        app.handle_key(VirtualKeyCode::Space, ElementState::Pressed)
            .expect("hold Record keyboard activation");
        assert!(!app.game_option_consumed_keys.is_empty());
        let record = app
            .scenario_game_options
            .layout()
            .rect(clonk_frontend::game_option_buttons::GameOptionButton::Record)
            .expect("Record bounds");
        app.handle_cursor_moved(PhysicalPosition::new(
            f64::from(record.x + record.w / 2),
            f64::from(record.y + record.h / 2),
        ))
        .expect("point at held Record");
        app.handle_mouse_button(ElementState::Pressed)
            .expect("hold Record pointer activation");
        assert!(app.game_option_pointer_capture);
        app.resize(1024, 768).expect("resize held option strip");
        assert!(app.game_option_consumed_keys.is_empty());
        assert!(!app.game_option_pointer_capture);
        app.handle_key(VirtualKeyCode::Space, ElementState::Released)
            .expect("release cancelled Record keyboard activation");
        app.handle_mouse_button(ElementState::Released)
            .expect("release cancelled Record pointer activation");
        assert!(!app.scenario_game_options.values().record);

        app.scenario_game_options = GameOptionButtons::new(
            GameOptionContext::NetworkHostSelector,
            GameOptionValues::default(),
        );
        app.sync_scenario_game_option_bounds();
        let actions = app.scenario_game_options.handle_hotkey('P');
        app.finish_game_option_input(actions)
            .expect("open resize password modal");
        let input_layout = app.game_option_input_layout().expect("input layout");
        let edit_point = PhysicalPosition::new(
            f64::from(input_layout.edit.x + input_layout.edit.w / 2),
            f64::from(input_layout.edit.y + input_layout.edit.h / 2),
        );
        app.handle_cursor_moved(edit_point)
            .expect("point into password edit");
        app.handle_mouse_button(ElementState::Pressed)
            .expect("start password edit drag");
        app.handle_key(VirtualKeyCode::Tab, ElementState::Pressed)
            .expect("focus password OK button");
        app.handle_key(VirtualKeyCode::Tab, ElementState::Released)
            .expect("release password focus traversal");
        app.handle_key(VirtualKeyCode::Return, ElementState::Pressed)
            .expect("hold password OK button");
        assert_eq!(
            app.game_option_input_pointer_capture,
            Some(ContextMenuPointerButton::Left)
        );
        assert!(!app.game_option_input_consumed_keys.is_empty());
        assert!(app.game_option_input_pointer_position.is_some());
        app.resize(1280, 720).expect("resize open password modal");
        assert!(app.game_option_input_dialog.is_some());
        assert_eq!(app.game_option_input_pointer_capture, None);
        assert!(app.game_option_input_consumed_keys.is_empty());
        assert!(app.game_option_input_pointer_position.is_none());
        assert!(app.game_option_input_last_click.is_none());
        assert!(!app.game_option_pointer_capture);
        app.handle_key(VirtualKeyCode::Return, ElementState::Released)
            .expect("release cancelled modal OK button");
        app.handle_mouse_button(ElementState::Released)
            .expect("release cancelled modal drag");
        assert!(app.game_option_input_dialog.is_some());
        reset_cached_app_paths();
    }

    #[test]
    fn scensel_recursive_focus_and_gamepad_pass_through_match_dialog_order() {
        let mut first = FrontendScenario::fallback();
        first.identifier = "first".to_string();
        first.title = "First".to_string();
        first.allow_user_change = Some(false);
        let mut second = FrontendScenario::fallback();
        second.identifier = "second".to_string();
        second.title = "Second".to_string();
        second.local_only = Some(true);
        second.allow_user_change = Some(false);
        let scenarios = vec![first, second];
        let menu = StartupMenu::new(build_menu_entries(&scenarios, false), test_font(), None)
            .expect("focus-order menu");
        let mut app = new_menu_app(800, 600);
        app.menu_state = MenuState::new(menu, scenarios.clone());
        app.scenario_catalog = build_scenario_catalog(&scenarios);
        app.open_scenario_browser();
        assert_eq!(app.menu_state.dialog_focus(), ScenselDialogFocus::List);
        assert!(app.menu_state.definition_checkbox_enabled);

        let tap_tab = |app: &mut GameApp| {
            app.handle_key(VirtualKeyCode::Tab, ElementState::Pressed)
                .expect("Tab down");
            app.handle_key(VirtualKeyCode::Tab, ElementState::Released)
                .expect("Tab up");
        };
        tap_tab(&mut app);
        assert_eq!(app.menu_state.dialog_focus(), ScenselDialogFocus::Back);
        tap_tab(&mut app);
        assert_eq!(
            app.menu_state.dialog_focus(),
            ScenselDialogFocus::Definitions
        );
        tap_tab(&mut app);
        assert_eq!(
            app.scenario_game_options.focused_button(),
            Some(clonk_frontend::game_option_buttons::GameOptionButton::FairCrew)
        );
        tap_tab(&mut app);
        assert_eq!(
            app.scenario_game_options.focused_button(),
            Some(clonk_frontend::game_option_buttons::GameOptionButton::Record)
        );
        tap_tab(&mut app);
        assert_eq!(app.menu_state.dialog_focus(), ScenselDialogFocus::Open);
        tap_tab(&mut app);
        assert_eq!(app.menu_state.dialog_focus(), ScenselDialogFocus::Search);
        tap_tab(&mut app);
        assert_eq!(app.menu_state.dialog_focus(), ScenselDialogFocus::List);

        app.handle_modifiers_changed(ModifiersState::SHIFT)
            .expect("set keyboard modifiers");
        tap_tab(&mut app);
        app.handle_modifiers_changed(ModifiersState::empty())
            .expect("set keyboard modifiers");
        assert_eq!(app.menu_state.dialog_focus(), ScenselDialogFocus::Search);

        app.set_scensel_dialog_focus(ScenselDialogFocus::List);
        app.handle_gamepad_direction(
            GamepadSlot::new(0),
            ControlButton::Right,
            ElementState::Pressed,
        )
        .expect("List -> Back");
        assert_eq!(app.menu_state.dialog_focus(), ScenselDialogFocus::Back);
        app.handle_gamepad_direction(
            GamepadSlot::new(0),
            ControlButton::Right,
            ElementState::Pressed,
        )
        .expect("Back -> Definitions");
        assert_eq!(
            app.menu_state.dialog_focus(),
            ScenselDialogFocus::Definitions
        );
        app.handle_gamepad_direction(
            GamepadSlot::new(0),
            ControlButton::Right,
            ElementState::Pressed,
        )
        .expect("Definitions -> first option");
        assert_eq!(
            app.scenario_game_options.focused_button(),
            Some(clonk_frontend::game_option_buttons::GameOptionButton::FairCrew)
        );

        let selected_before = app.menu_state.menu.selected_index();
        app.handle_gamepad_direction(
            GamepadSlot::new(0),
            ControlButton::Down,
            ElementState::Pressed,
        )
        .expect("unhandled option Down reaches list");
        assert_ne!(app.menu_state.menu.selected_index(), selected_before);
        assert_eq!(
            app.scenario_game_options.focused_button(),
            Some(clonk_frontend::game_option_buttons::GameOptionButton::FairCrew)
        );
        assert!(!app.menu_state.definition_checkbox_enabled);

        app.set_scensel_dialog_focus(ScenselDialogFocus::List);
        app.handle_gamepad_direction(
            GamepadSlot::new(0),
            ControlButton::Right,
            ElementState::Pressed,
        )
        .expect("List -> Back with disabled definitions");
        app.handle_gamepad_direction(
            GamepadSlot::new(0),
            ControlButton::Right,
            ElementState::Pressed,
        )
        .expect("disabled Definitions are skipped");
        assert_eq!(
            app.scenario_game_options.focused_button(),
            Some(clonk_frontend::game_option_buttons::GameOptionButton::FairCrew)
        );
        app.handle_gamepad_direction(
            GamepadSlot::new(0),
            ControlButton::Left,
            ElementState::Pressed,
        )
        .expect("option boundary skips disabled Definitions backwards");
        assert_eq!(app.menu_state.dialog_focus(), ScenselDialogFocus::Back);

        app.handle_menu_input(|menu| menu.select_list_index(0))
            .expect("reselect first scenario");
        app.scenario_game_options.set_focused_button(Some(
            clonk_frontend::game_option_buttons::GameOptionButton::FairCrew,
        ));
        app.menu_state.set_dialog_focus(ScenselDialogFocus::Options);
        app.scenario_game_options
            .set_selector_fair_crew_constraint(FairCrewConstraint::ForceNormal);
        app.handle_gamepad_action(
            GamepadSlot::new(0),
            GamepadActionType::Select,
            ElementState::Pressed,
        )
        .expect("disabled option passes low down");
        app.handle_gamepad_action(
            GamepadSlot::new(0),
            GamepadActionType::Select,
            ElementState::Released,
        )
        .expect("disabled option passes low up to scenario Enter");
        assert_eq!(app.mode, AppMode::Running);
    }

    #[test]
    fn empty_search_clears_forced_crew_constraint() {
        let scenario_root = tempdir().expect("forced scenario root");
        let scenario_path = scenario_root.path().join("Forced.c4s");
        fs::create_dir_all(&scenario_path).expect("forced scenario group");
        fs::write(
            scenario_path.join("Scenario.txt"),
            "[Head]\nTitle=Forced\nForcedNoCrew=2\n",
        )
        .expect("forced scenario core");
        let mut scenario = FrontendScenario::fallback();
        scenario.identifier = "forced".to_string();
        scenario.title = "Forced".to_string();
        scenario.path = Some(scenario_path);
        let scenarios = vec![scenario];
        let menu = StartupMenu::new(build_menu_entries(&scenarios, false), test_font(), None)
            .expect("forced scenario menu");
        let mut app = new_menu_app(800, 600);
        app.menu_state = MenuState::new(menu, scenarios.clone());
        app.scenario_catalog = build_scenario_catalog(&scenarios);
        app.open_scenario_browser();
        assert_eq!(
            app.scenario_game_options
                .values()
                .selector_fair_crew_constraint,
            FairCrewConstraint::ForceNormal
        );
        assert!(
            !app.scenario_game_options
                .view(clonk_frontend::game_option_buttons::GameOptionButton::FairCrew)
                .expect("fair-crew option")
                .enabled
        );

        app.menu_state.set_search_text("no matching scenario");
        app.submit_scenario_search().expect("submit empty search");
        assert!(app.menu_state.selected_scenario().is_none());
        assert_eq!(
            app.scenario_game_options
                .values()
                .selector_fair_crew_constraint,
            FairCrewConstraint::Free
        );
        assert!(
            app.scenario_game_options
                .view(clonk_frontend::game_option_buttons::GameOptionButton::FairCrew)
                .expect("reset fair-crew option")
                .enabled
        );
    }

    fn assert_startup_error_log(app: &GameApp, expected_message: &str) {
        use clonk_frontend::message_dialog::{
            MessageDialogButton, MessageDialogButtons, MessageDialogIcon, MessageDialogSize,
        };

        assert_eq!(app.message_dialogs.len(), 1);
        let dialog = &app.message_dialogs[0];
        assert_eq!(dialog.state.caption(), "Error Log");
        assert_eq!(dialog.state.message(), expected_message);
        assert_eq!(dialog.state.buttons(), MessageDialogButtons::OK);
        assert_eq!(dialog.state.focused_button(), Some(MessageDialogButton::Ok));
        assert_eq!(dialog.state.icon(), MessageDialogIcon::ERROR);
        assert_eq!(dialog.state.size(), MessageDialogSize::Regular);
        assert!(matches!(dialog.continuation, MessageDialogContinuation::None));
        assert!(app.status_text.is_empty());
    }

    #[test]
    fn local_scenario_load_failure_returns_to_remembered_selector_with_error_log() {
        let _lock = env_lock().lock();
        reset_cached_app_paths();
        let user_data = tempdir().expect("isolated local-start failure user data");
        let (_guard, paths) = exact_loader_test_paths(user_data.path(), None);
        let repository = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(Path::parent)
            .and_then(Path::parent)
            .expect("repository root");
        let mut app = new_menu_app_with_paths(800, 600, &paths);
        let StagedNetworkHostScenario {
            frontend,
            loader_screen,
            loader_refreshed_resources,
            ..
        } = prepare_tutorial_host_lobby(&app, repository);
        app.open_scenario_browser();
        wait_for_scenario_selector_discovery(&mut app);

        let (sender, receiver) = mpsc::channel();
        app.loader_screen = loader_screen;
        app.loading_state = Some(ScenarioLoadingState::new(
            frontend,
            loader_refreshed_resources,
            HashMap::new(),
            Vec::new(),
            receiver,
        ));
        app.mode = AppMode::Loading;
        sender
            .send(ScenarioLoadingEvent::Finished(Err(
                "controlled local load failure".to_string(),
            )))
            .expect("queue controlled local load failure");

        app.poll_loading()
            .expect("failed local load restarts the startup selector");

        assert_eq!(app.mode, AppMode::Menu);
        assert_eq!(app.startup_view, StartupView::ScenarioBrowser);
        assert_eq!(app.scenario_selector_mode, ScenarioSelectorMode::Local);
        assert_eq!(
            app.last_startup_dialog,
            StartupDialog::ScenarioBrowser(ScenarioSelectorMode::Local)
        );
        assert_eq!(app.startup_scenario_back_dialog, None);
        assert!(app.loading_state.is_none());
        assert!(app.loader_screen.is_none());
        assert!(app.loader_error.is_none());
        assert!(app.active_scenario.is_none());
        assert!(app.active_definition_load.is_none());
        assert!(app.active_global_gui_failures.is_empty());
        assert!(app.runtime_client_list.is_none());
        assert_startup_error_log(&app, "controlled local load failure");
        assert_eq!(
            app.startup_restart_diagnostics,
            StartupRestartDiagnostics::default()
        );

        let mut frame = vec![0x4c; 800 * 600 * 4];
        app.render(&mut frame)
            .expect("render restored local selector and Error Log");
        assert!(frame.iter().any(|byte| *byte != 0x4c));
        app.finish_message_dialog(clonk_frontend::message_dialog::MessageDialogResult::Ok)
            .expect("dismiss local startup Error Log");
        assert!(app.message_dialogs.is_empty());
        assert_eq!(app.startup_view, StartupView::ScenarioBrowser);
        assert_eq!(app.scenario_selector_mode, ScenarioSelectorMode::Local);
        assert_eq!(app.startup_scenario_back_dialog, None);
        reset_cached_app_paths();
    }

    #[test]
    fn l148_restart_diagnostics_bound_order_deduplicate_and_reset() {
        let mut diagnostics = StartupRestartDiagnostics::default();
        diagnostics.mark_quit_with_error();
        for index in 0..=STARTUP_RESTART_LOG_CAPACITY {
            diagnostics.add_log_entry(format!("entry-{index:03}"));
        }
        assert_eq!(
            diagnostics.take_presentation(),
            Some(StartupRestartPresentation::Ringbuffer(
                (1..=STARTUP_RESTART_LOG_CAPACITY)
                    .map(|index| format!("entry-{index:03}"))
                    .collect()
            ))
        );
        assert_eq!(diagnostics, StartupRestartDiagnostics::default());

        diagnostics.add_fatal_error("fatal");
        diagnostics.add_fatal_error("fatal");
        diagnostics.begin_game_init();
        diagnostics.add_log_entry("ordinary");
        assert_eq!(
            diagnostics.take_presentation(),
            Some(StartupRestartPresentation::Fatal("fatal".to_string()))
        );
        assert_eq!(diagnostics, StartupRestartDiagnostics::default());

        diagnostics.mark_quit_with_error();
        assert_eq!(
            diagnostics.take_presentation(),
            Some(StartupRestartPresentation::Empty)
        );
        assert_eq!(diagnostics, StartupRestartDiagnostics::default());
    }

    #[test]
    fn l148_disconnected_startup_worker_reaches_ringbuffer_only_restart_branch() {
        let mut app = new_real_classic_menu_app(800, 600);
        attach_l040_network_dialog(&mut app);
        let (sender, receiver) = mpsc::channel::<std::result::Result<
            (NetworkMode, NetworkManager),
            NetworkStartError,
        >>();
        drop(sender);
        app.startup_network_connection = Some(StartupNetworkConnection::new(
            receiver,
            None,
            StartupNetworkPurpose::Join,
        ));

        app.poll_startup_network_connection()
            .expect("disconnected worker restarts startup with retained log");

        let info = app.runtime_client_list.as_ref().expect("static Error Log");
        assert!(info.is_static_info_only());
        assert_eq!(
            info.info_lines(),
            ["network worker disconnected before reporting readiness"]
        );
        assert!(app.message_dialogs.is_empty());
        assert!(app.status_text.is_empty());
        let (preferred, line_height) = app
            .runtime_client_list_input_geometry()
            .expect("static InfoDialog geometry");
        let bottom_close = app
            .runtime_client_list
            .as_ref()
            .and_then(|dialog| dialog.info_layout(preferred, line_height))
            .and_then(|layout| layout.bottom_close_button)
            .expect("bottom Close button");
        app.handle_cursor_moved(PhysicalPosition::new(
            f64::from(bottom_close.x + bottom_close.w / 2),
            f64::from(bottom_close.y + bottom_close.h / 2),
        ))
        .expect("point at bottom Close button");
        app.handle_mouse_button(ElementState::Pressed)
            .expect("press bottom Close button");
        app.handle_mouse_button(ElementState::Released)
            .expect("release bottom Close button");
        assert!(app.runtime_client_list.is_none());
        assert_eq!(
            app.startup_restart_diagnostics,
            StartupRestartDiagnostics::default()
        );
    }

    #[test]
    fn l148_restart_ringbuffer_uses_static_ten_line_error_log_info_dialog() {
        let mut app = new_real_classic_menu_app(800, 600);
        attach_l040_network_dialog(&mut app);
        app.startup_network_dialog
            .as_mut()
            .expect("remembered NetDlg")
            .set_join_address("remembered.example:11112");
        app.status_text = "stale generic status".to_string();
        let mut entries = (0..16)
            .map(|index| format!("retained-log-{index:02}"))
            .collect::<Vec<_>>();
        entries[15] = format!("retained-log-15 {}TAIL", "wrapped-segment ".repeat(80));

        app.startup_restart_diagnostics.mark_quit_with_error();
        for entry in &entries {
            app.startup_restart_diagnostics.add_log_entry(entry.clone());
        }
        app.finish_startup_network_restart(StartupNetworkPurpose::Join)
            .expect("reconstruct NetDlg and show retained log");

        assert_eq!(app.mode, AppMode::Menu);
        assert_eq!(app.startup_view, StartupView::NetworkGame);
        assert!(app.startup_network_dialog.is_some());
        assert!(app.message_dialogs.is_empty());
        assert!(app.status_text.is_empty());
        let info = app.runtime_client_list.as_ref().expect("Error Log info");
        assert!(info.is_info_only());
        assert!(info.info_is_open());
        assert_eq!(info.info_client_id(), None);
        assert_eq!(info.info_caption(), "Error Log");
        assert_eq!(info.info_requested_line_count(), 10);
        assert_eq!(info.info_lines(), entries);

        let (preferred, _) = app
            .runtime_client_list_input_geometry()
            .expect("InfoDialog geometry");
        let fonts = app.assets.clonk_fonts.clone().expect("classic fonts");
        assert_eq!(
            app.runtime_client_list
                .as_ref()
                .expect("Error Log info")
                .visible_info_lines(preferred, &fonts.text)
                .first()
                .map(String::as_str),
            Some("retained-log-00")
        );
        assert!(app
            .runtime_client_list
            .as_ref()
            .expect("Error Log info")
            .info_scroll_metrics(preferred, &fonts.text)
            .is_some_and(|metrics| metrics.max_scroll > 0));
        let mut frame = vec![0x4c; 800 * 600 * 4];
        app.render(&mut frame)
            .expect("render reconstructed NetDlg and Error Log info");
        assert!(frame.iter().any(|byte| *byte != 0x4c));

        app.handle_key(VirtualKeyCode::End, ElementState::Pressed)
            .expect("scroll retained log to end");
        assert!(
            app.runtime_client_list
                .as_ref()
                .expect("scrolled Error Log info")
                .visible_info_lines(preferred, &fonts.text)
                .last()
                .is_some_and(|line| line.ends_with("TAIL"))
        );
        app.handle_key(VirtualKeyCode::End, ElementState::Released)
            .expect("release retained-log scroll key");
        app.handle_key(VirtualKeyCode::Return, ElementState::Pressed)
            .expect("dismiss retained Error Log info");
        assert!(app.runtime_client_list.is_none());
        assert_eq!(app.startup_view, StartupView::NetworkGame);
        assert!(app.startup_network_dialog.is_some());
        app.handle_key(VirtualKeyCode::Return, ElementState::Released)
            .expect("dismissed info owns Return release");
        assert_eq!(app.startup_view, StartupView::NetworkGame);
        assert_eq!(
            app.startup_restart_diagnostics,
            StartupRestartDiagnostics::default()
        );
    }

    #[test]
