    #[test]
    fn startup_irc_warning_persists_login_and_checkbox_on_cancel_then_connects_on_ok() {
        use clonk_frontend::message_dialog::{
            MessageDialogButton, MessageDialogButtons, MessageDialogIcon, MessageDialogResult,
        };

        let _lock = env_lock().lock();
        reset_cached_app_paths();
        let user_data = tempdir().expect("IRC warning user data");
        let (_guard, paths) = exact_loader_test_paths(user_data.path(), None);
        persist_config_value(&paths, "Startup", "HideMsgIRCDangerous", "0")
            .expect("enable IRC warning");
        persist_config_value(&paths, "IRC", "Server2", "irc.configured.test")
            .expect("seed configured IRC server");
        let mut app = new_menu_app_with_paths(640, 480, &paths);
        install_classic_test_assets(&mut app);
        let cancelled = clonk_frontend::startup_netdlg::NetDlgChatLogin {
            server: "irc.cancelled.test".into(),
            nick: "SavedNick".into(),
            password: "transient-secret".into(),
            real_name: "Saved Name".into(),
            channel: "#saved".into(),
        };

        app.request_startup_irc_connection(cancelled.clone())
            .expect("open IRC warning");
        let warning = app.message_dialogs.last_mut().expect("IRC warning dialog");
        assert_eq!(warning.state.caption(), "Chat - Disclaimer");
        assert!(warning.state.message().contains("irc.cancelled.test"));
        assert_eq!(warning.state.buttons(), MessageDialogButtons::OK_CANCEL);
        assert_eq!(warning.state.icon(), MessageDialogIcon::NOTIFY);
        assert_eq!(warning.state.focused_button(), Some(MessageDialogButton::Ok));
        assert!(matches!(
            &warning.continuation,
            MessageDialogContinuation::StartupIrcConnectWarning { login }
                if login == &cancelled
        ));
        assert_eq!(warning.state.handle_hotkey('d'), None);
        app.persist_top_message_dialog_checkbox_changes();
        app.finish_message_dialog(MessageDialogResult::Cancel)
            .expect("cancel IRC warning");
        assert!(app.startup_irc_client.is_none());

        let persisted = Config::load(paths.config_file()).expect("reload persisted IRC config");
        assert_eq!(persisted.get_in(Some("IRC"), "Nick"), Some("SavedNick"));
        assert_eq!(
            persisted.get_in(Some("IRC"), "RealName"),
            Some("Saved Name")
        );
        assert_eq!(persisted.get_in(Some("IRC"), "Channel"), Some("#saved"));
        assert_eq!(persisted.get_in(Some("IRC"), "Password"), None);
        assert_eq!(
            persisted.get_in(Some("IRC"), "Server2"),
            Some("irc.configured.test"),
            "Connect persists form fields without replacing configured Server2"
        );
        assert_eq!(
            persisted.get_in(Some("Startup"), "HideMsgIRCDangerous"),
            Some("1"),
            "the don't-show choice persists even when the connection is cancelled"
        );

        persist_config_value(&paths, "Startup", "HideMsgIRCDangerous", "0")
            .expect("show warning again");
        let (address, server) = spawn_loopback_irc_server();
        let accepted = clonk_frontend::startup_netdlg::NetDlgChatLogin {
            server: address,
            nick: "AcceptedNick".into(),
            password: "another-secret".into(),
            real_name: "Accepted Name".into(),
            channel: "#accepted".into(),
        };
        app.request_startup_irc_connection(accepted)
            .expect("reopen IRC warning");
        assert!(app.startup_irc_client.is_none());
        app.finish_message_dialog(MessageDialogResult::Ok)
            .expect("accept IRC warning");
        let client = app.startup_irc_client.as_ref().expect("IRC client started");
        assert!(matches!(
            client.recv_event_timeout(Duration::from_secs(2)),
            Ok(clonk_network::IrcClientEvent::Connected)
        ));
        drop(app);
        server.join().expect("join loopback IRC server");
        reset_cached_app_paths();
    }

    #[test]
    fn hidden_startup_irc_warning_connects_immediately() {
        let _lock = env_lock().lock();
        reset_cached_app_paths();
        let user_data = tempdir().expect("hidden IRC warning user data");
        let (_guard, paths) = exact_loader_test_paths(user_data.path(), None);
        let (address, server) = spawn_loopback_irc_server();
        persist_config_value(&paths, "Startup", "HideMsgIRCDangerous", "1")
            .expect("hide IRC warning");
        persist_config_value(&paths, "Network", "MasterServerSignUp", "0")
            .expect("disable test masterserver query");
        persist_config_value(&paths, "IRC", "Server2", &address)
            .expect("seed loopback IRC server");
        persist_config_value(&paths, "IRC", "Nick", "HiddenNick")
            .expect("seed IRC nick");
        persist_config_value(&paths, "IRC", "RealName", "Hidden Name")
            .expect("seed IRC real name");
        persist_config_value(&paths, "IRC", "Channel", "#hidden")
            .expect("seed IRC channel");
        let mut app = new_menu_app_with_paths(640, 480, &paths);
        install_classic_test_assets(&mut app);
        app.open_network_game_dialog();
        let mut login = app
            .startup_network_dialog
            .as_ref()
            .expect("network dialog")
            .chat_login();
        assert_eq!(login.server, address);
        assert_eq!(login.nick, "HiddenNick");
        assert_eq!(login.real_name, "Hidden Name");
        assert_eq!(login.channel, "#hidden");
        login.password = "not-persisted".into();
        let dialog_count = app.message_dialogs.len();

        app.request_startup_irc_connection(login)
            .expect("connect without warning");
        assert_eq!(app.message_dialogs.len(), dialog_count);
        let client = app.startup_irc_client.as_ref().expect("IRC client started");
        assert!(matches!(
            client.recv_event_timeout(Duration::from_secs(2)),
            Ok(clonk_network::IrcClientEvent::Connected)
        ));
        let persisted = Config::load(paths.config_file()).expect("reload hidden-warning config");
        assert_eq!(persisted.get_in(Some("IRC"), "Nick"), Some("HiddenNick"));
        assert_eq!(persisted.get_in(Some("IRC"), "Password"), None);
        drop(app);
        server.join().expect("join loopback IRC server");
        reset_cached_app_paths();
    }

    fn enter_unported_startup_subscreen(app: &mut GameApp, subscreen: ClassicStartupSubscreen) {
        match subscreen {
            ClassicStartupSubscreen::Options(target) => {
                app.open_options_menu();
                let sheets = [
                    clonk_frontend::startup_options_dlg::OptionsSheet::Graphics,
                    clonk_frontend::startup_options_dlg::OptionsSheet::Sound,
                    clonk_frontend::startup_options_dlg::OptionsSheet::Keyboard,
                    clonk_frontend::startup_options_dlg::OptionsSheet::Gamepad,
                    clonk_frontend::startup_options_dlg::OptionsSheet::Network,
                ];
                for sheet in sheets {
                    app.handle_key(VirtualKeyCode::Down, ElementState::Pressed)
                        .unwrap_or_else(|error| panic!("open Options {sheet:?}: {error}"));
                    app.handle_key(VirtualKeyCode::Down, ElementState::Released)
                        .expect("release options sheet key");
                    if sheet == target {
                        break;
                    }
                }
            }
        }
    }

    #[test]
    fn startup_irc_frontend_switches_and_renders_without_a_fail_closed_boundary() {
        let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("bind loopback IRC");
        let address = listener.local_addr().expect("loopback IRC address");
        let server = thread::spawn(move || {
            use std::io::Read as _;

            let (mut stream, _) = listener.accept().expect("accept loopback IRC client");
            let mut buffer = [0_u8; 512];
            while stream.read(&mut buffer).is_ok_and(|read| read != 0) {}
        });
        let handle = clonk_network::IrcClientHandle::connect_with_timeout(
            clonk_network::IrcConnectConfig::new(
                address.to_string(),
                b"Clonker".to_vec(),
                b"Clonker".to_vec(),
            ),
            Duration::from_secs(2),
        )
        .expect("start loopback IRC client");
        assert!(matches!(
            handle.recv_event_timeout(Duration::from_secs(2)),
            Ok(clonk_network::IrcClientEvent::Connected)
        ));

        let mut app = new_real_classic_menu_app(640, 480);
        app.startup_irc_server = address.to_string();
        app.startup_irc_client = Some(handle);
        app.open_network_game_dialog();
        let browser_status = app.status_text.clone();
        activate_startup_network_chat(&mut app);
        assert!(app.network.is_none());
        assert_eq!(app.status_text, browser_status);
        assert_eq!(
            app.startup_network_dialog.as_ref().unwrap().mode(),
            clonk_frontend::startup_netdlg::NetDlgMode::Chat
        );
        assert_eq!(
            app.startup_network_dialog
                .as_ref()
                .unwrap()
                .chat_connection_state(),
            clonk_frontend::startup_netdlg::NetDlgChatConnectionState::Connected
        );

        let mut frame = vec![0xa5; 640 * 480 * 4];
        app.render(&mut frame)
            .expect("the classic startup Chat sheet renders");
        assert!(frame.iter().any(|byte| *byte != 0xa5));

        let metrics = clonk_frontend::startup_netdlg::NetDlgFontMetrics {
            caption_back_extent: 51,
            text_ip_extent: 18,
            text_line_height: 22,
            caption_line_height: 25,
            title_line_height: 34,
        };
        let button = clonk_frontend::startup_netdlg::net_dlg_layout(640, 480, &metrics).btn_game_list;
        let point = PhysicalPosition::new(
            f64::from(button.x + button.w / 2),
            f64::from(button.y + button.h / 2),
        );
        app.handle_cursor_moved(point).expect("hover Games");
        app.handle_mouse_button(ElementState::Pressed)
            .expect("press Games");
        app.handle_mouse_button(ElementState::Released)
            .expect("return to the game list");
        assert_eq!(
            app.startup_network_dialog.as_ref().unwrap().mode(),
            clonk_frontend::startup_netdlg::NetDlgMode::GameList
        );

        app.show_main_menu();
        app.open_network_game_dialog();
        activate_startup_network_chat(&mut app);
        assert!(app.startup_irc_client.is_some());
        assert_eq!(
            app.startup_network_dialog
                .as_ref()
                .unwrap()
                .chat_connection_state(),
            clonk_frontend::startup_netdlg::NetDlgChatConnectionState::Connected,
            "the process-global IRC client survives startup-screen replacement"
        );
        drop(app);
        server.join().expect("join loopback IRC server");
    }

    #[test]
    fn startup_irc_command_projection_covers_the_frontend_command_language() {
        use clonk_frontend::startup_netdlg::NetDlgChatCommand as Frontend;
        use clonk_network::IrcCommand as Backend;

        let cases = [
            (
                Frontend::Quit {
                    reason: "bye".into(),
                },
                Backend::Quit {
                    reason: b"bye".to_vec(),
                },
            ),
            (
                Frontend::Join {
                    channel: "#clonk".into(),
                },
                Backend::Join {
                    channel: b"#clonk".to_vec(),
                },
            ),
            (
                Frontend::Part {
                    channel: "#clonk".into(),
                },
                Backend::Part {
                    channel: b"#clonk".to_vec(),
                },
            ),
            (
                Frontend::Message {
                    target: "#clonk".into(),
                    text: "\u{00c3}\u{00a9}".into(),
                },
                Backend::Message {
                    target: b"#clonk".to_vec(),
                    text: vec![0xc3, 0xa9],
                },
            ),
            (
                Frontend::Notice {
                    target: "Clonker".into(),
                    text: "notice".into(),
                },
                Backend::Notice {
                    target: b"Clonker".to_vec(),
                    text: b"notice".to_vec(),
                },
            ),
            (
                Frontend::Action {
                    target: "#clonk".into(),
                    text: "waves".into(),
                },
                Backend::Action {
                    target: b"#clonk".to_vec(),
                    text: b"waves".to_vec(),
                },
            ),
            (
                Frontend::Raw("WHOIS Clonker".into()),
                Backend::Raw(b"WHOIS Clonker".to_vec()),
            ),
            (
                Frontend::ChangeNick {
                    nick: "Clonker_".into(),
                },
                Backend::ChangeNick {
                    nick: b"Clonker_".to_vec(),
                },
            ),
        ];
        for (frontend, backend) in cases {
            assert_eq!(project_startup_irc_command(frontend), Some(backend));
        }
        assert_eq!(
            project_startup_irc_command(Frontend::OpenQuery {
                nick: "Clonker".into(),
            }),
            None,
            "query tabs are a frontend-only operation"
        );
        assert_eq!(
            project_startup_irc_command(Frontend::Raw("snowman \u{2603}".into())),
            None,
            "unrepresentable presentation text must not reach the byte transport"
        );
    }

    #[test]
    fn standalone_irc_entry_points_share_the_singleton_dialog_and_alt_c_toggles_it() {
        let mut lobby_app = new_real_classic_menu_app(640, 480);
        install_test_classic_host_lobby(&mut lobby_app);
        lobby_app
            .process_classic_lobby_actions(vec![ClassicLobbyAction::Chat(
                LobbyChatRequest::OpenExternalDialog,
            )])
            .expect("the lobby IRC button opens the standalone dialog");
        assert!(lobby_app.classic_host_lobby.is_some());
        assert!(lobby_app.external_irc_dialog_visible);
        let dialog = lobby_app
            .external_irc_dialog
            .as_ref()
            .expect("the standalone network/chat controller exists");
        assert_eq!(
            dialog.mode(),
            clonk_frontend::startup_netdlg::NetDlgMode::Chat
        );
        assert_eq!(
            dialog.chat_bounds_override(),
            Some(clonk_frontend::startup_netdlg::NetDlgController::standalone_chat_bounds(640, 480))
        );
        let first_dialog_ptr = std::ptr::from_ref(dialog);
        lobby_app
            .process_classic_lobby_actions(vec![ClassicLobbyAction::Chat(
                LobbyChatRequest::OpenExternalDialog,
            )])
            .expect("a repeated lobby request raises the same dialog");
        assert!(lobby_app.external_irc_dialog_visible);
        assert_eq!(
            lobby_app
                .external_irc_dialog
                .as_ref()
                .map(std::ptr::from_ref),
            Some(first_dialog_ptr),
            "raising the singleton must preserve its UI-local controller state"
        );
        lobby_app.hide_external_irc_dialog();
        assert!(!lobby_app.external_irc_dialog_visible);
        assert!(lobby_app.external_irc_dialog.is_none());

        for modifiers in [
            ModifiersState::ALT,
            ModifiersState::ALT | ModifiersState::LOGO,
        ] {
            let mut runtime_app = new_classic_running_sandbox_app();
            runtime_app
                .bindings
                .rebind(ControlBindingId::Left, VirtualKeyCode::C);
            runtime_app
                .handle_modifiers_changed(modifiers)
                .expect("set the exact legacy IRC chord");
            runtime_app.menu_title_drag = Some(MenuTitleDrag::Ingame {
                player: runtime_app.local_owner,
                start_pointer: GuiPoint::new(20.0, 20.0),
                start_location: (40, 50),
            });
            runtime_app
                .handle_key(VirtualKeyCode::C, ElementState::Pressed)
                .expect("runtime Alt+C opens the standalone IRC dialog");
            assert!(runtime_app.external_irc_dialog_visible);
            assert!(
                runtime_app.menu_title_drag.is_none(),
                "activating C4ChatDlg releases an obscured menu-title drag"
            );
            runtime_app
                .handle_cursor_moved(PhysicalPosition::new(300.0, 200.0))
                .expect("standalone dialog owns motion after activation");
            runtime_app
                .handle_mouse_button(ElementState::Released)
                .expect("standalone dialog owns the pending pointer release");
            assert!(runtime_app.external_irc_dialog_visible);

            runtime_app
                .engine
                .player_mut(runtime_app.local_owner)
                .expect("local sandbox player")
                .control
                .pressed_coms = 1 << clonk_engine::COM_LEFT;
            runtime_app
                .handle_key(VirtualKeyCode::C, ElementState::Released)
                .expect("runtime IRC chord release must be consumed");
            assert_ne!(
                runtime_app
                    .engine
                    .player(runtime_app.local_owner)
                    .expect("local sandbox player")
                    .control
                    .pressed_coms
                    & (1 << clonk_engine::COM_LEFT),
                0,
                "runtime IRC release must not leak to modifier-blind player control"
            );
            runtime_app
                .handle_key(VirtualKeyCode::C, ElementState::Pressed)
                .expect("a second runtime Alt+C closes only the IRC UI");
            assert!(!runtime_app.external_irc_dialog_visible);
        }

        let mut ignored_runtime = new_running_sandbox_app();
        for modifiers in [
            ModifiersState::empty(),
            ModifiersState::CTRL,
            ModifiersState::SHIFT,
            ModifiersState::LOGO,
            ModifiersState::ALT | ModifiersState::CTRL,
            ModifiersState::ALT | ModifiersState::SHIFT,
            ModifiersState::ALT | ModifiersState::CTRL | ModifiersState::SHIFT,
        ] {
            ignored_runtime
                .handle_modifiers_changed(modifiers)
                .expect("set non-IRC modifiers");
            assert!(!ignored_runtime
                .handle_runtime_irc_toggle_key(VirtualKeyCode::C, ElementState::Pressed)
                .expect("non-IRC chord is unhandled"));
            assert!(!ignored_runtime.external_irc_dialog_visible);
        }
    }

