    #[test]
    fn l056_about_scrollbar_sounds_and_repeat_run_through_production_paths() {
        let mut app = new_real_classic_menu_app(320, 240);
        enter_about_licenses(&mut app);
        app.ui_sound_log.clear();

        let layout = clonk_frontend::startup_about_dlg::about_layout(320, 240);
        let text = layout.licenses.text;
        let bar = clonk_frontend::classic_gui::IntRect {
            x: text.x + text.w - 5 - 16,
            y: text.y + 8,
            w: 16,
            h: text.h - 16,
        };
        let track = PhysicalPosition::new(
            f64::from(bar.x + 8),
            f64::from(bar.y + bar.h / 2),
        );
        app.handle_cursor_moved(track).expect("hover license track");
        app.handle_mouse_button(ElementState::Pressed)
            .expect("start license track drag");
        assert_eq!(app.ui_sound_log, vec!["Command"]);
        assert!(app
            .startup_about_dialog
            .as_ref()
            .is_some_and(|dialog| dialog.license_scroll_offset() > 0));
        app.handle_mouse_button(ElementState::Released)
            .expect("release license track drag");

        app.ui_sound_log.clear();
        let bottom_arrow = PhysicalPosition::new(
            f64::from(bar.x + 8),
            f64::from(bar.y + bar.h - 1),
        );
        app.handle_cursor_moved(bottom_arrow)
            .expect("hover license bottom arrow");
        app.handle_mouse_button(ElementState::Pressed)
            .expect("hold license bottom arrow");
        assert_eq!(app.ui_sound_log, vec!["ArrowHit"]);
        let before_frame = app
            .startup_about_dialog
            .as_ref()
            .unwrap()
            .license_scroll_offset();
        let mut frame = vec![0_u8; 320 * 240 * 4];
        app.render(&mut frame)
            .expect("present one held-arrow frame");
        let after_frame = app
            .startup_about_dialog
            .as_ref()
            .unwrap()
            .license_scroll_offset();
        assert!(after_frame > before_frame);

        app.handle_mouse_button(ElementState::Released)
            .expect("release license bottom arrow");
        assert_eq!(app.ui_sound_log, vec!["ArrowHit", "ArrowHit"]);
        app.render(&mut frame)
            .expect("present after arrow release");
        assert_eq!(
            app.startup_about_dialog
                .as_ref()
                .unwrap()
                .license_scroll_offset(),
            after_frame
        );
    }

    #[test]
    fn modal_and_definition_overlays_never_replace_the_base_frame_cache() {
        let mut app = new_real_classic_menu_app(640, 480);
        let mut base = vec![0_u8; 640 * 480 * 4];
        app.render(&mut base).expect("cache main-menu base");
        let base_cache = app.menu_frame_cache.as_ref().unwrap().frame.clone();
        let base_version = app.menu_render_version;

        app.push_message_dialog(
            clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                "Message",
                "Caption",
                clonk_frontend::message_dialog::MessageDialogIcon::NOTIFY,
            ),
            MessageDialogContinuation::None,
        )
        .expect("open message overlay");
        app.menu_render_version = base_version;
        let mut modal = vec![0_u8; 640 * 480 * 4];
        assert!(app.render(&mut modal).expect("render message overlay"));
        assert_ne!(modal, base);
        assert_eq!(app.menu_frame_cache.as_ref().unwrap().frame, base_cache);
        app.finish_message_dialog(clonk_frontend::message_dialog::MessageDialogResult::Ok)
            .expect("close message overlay");
        app.menu_render_version = base_version;
        let mut closed = vec![0x77; 640 * 480 * 4];
        assert!(!app.render(&mut closed).expect("replay base after modal"));
        assert_eq!(closed, base);

        app.open_definition_selector(FrontendScenario::fallback())
            .expect("open definition selector");
        app.menu_render_version = base_version;
        let mut selector = vec![0_u8; 640 * 480 * 4];
        assert!(app
            .render(&mut selector)
            .expect("render definition selector"));
        assert_ne!(selector, base);
        assert_eq!(app.menu_frame_cache.as_ref().unwrap().frame, base_cache);
        app.process_definition_selector_actions(vec![
            clonk_frontend::definition_sel::DefinitionSelAction::Cancelled,
        ])
        .expect("close definition selector");
        app.menu_render_version = base_version;
        let mut closed = vec![0x88; 640 * 480 * 4];
        assert!(!app.render(&mut closed).expect("replay base after selector"));
        assert_eq!(closed, base);
    }

    #[test]
    fn retained_gpu_gamma_mode_matches_native_device_switch_matrix() {
        for shader in [false, true] {
            for use_shader_gamma in [false, true] {
                for disable_gamma in [false, true] {
                    let config = clonk_frontend::AdvancedRendererConfig {
                        shader,
                        use_shader_gamma,
                        disable_gamma,
                        ..clonk_frontend::AdvancedRendererConfig::DEFAULT
                    };
                    let expected = if disable_gamma {
                        GpuGammaMode::Disabled
                    } else if shader && use_shader_gamma {
                        GpuGammaMode::Fragment
                    } else {
                        GpuGammaMode::Monitor
                    };
                    assert_eq!(retained_gpu_gamma_mode(config), expected);
                }
            }
        }
    }

    #[test]
    fn cached_menu_requests_the_deferred_monitor_gamma_post_pass() {
        let mut app = new_real_classic_menu_app(320, 240);
        let configured_gamma =
            clonk_graphics::GammaRamp::from_control_points([0x101010, 0x707070, 0xe0e0e0]);
        app.loader_gamma = Some(configured_gamma.clone());
        app.graphics
            .set_advanced_renderer_config(clonk_frontend::AdvancedRendererConfig {
                shader: false,
                use_shader_gamma: true,
                disable_gamma: false,
                ..clonk_frontend::AdvancedRendererConfig::DEFAULT
            });
        app.main_menu_state.menu.set_gamma_ramp(None);
        app.menu_frame_cache = None;

        let mut cold = vec![0_u8; 320 * 240 * 4];
        assert!(app
            .render_for_presentation_with_monitor_defer(&mut cold, false, false, false, true,)
            .expect("render raw cached menu base"));
        let cached = app
            .menu_frame_cache
            .as_ref()
            .expect("cold render caches the raw logical frame")
            .frame
            .clone();
        assert_eq!(cold, cached);

        let mut deferred_hit = vec![0x55; cold.len()];
        assert!(app
            .render_for_presentation_with_monitor_defer(
                &mut deferred_hit,
                false,
                false,
                false,
                true,
            )
            .expect("replay raw cache for a physical post-pass"));
        assert_eq!(deferred_hit, cached);

        let mut direct_hit = vec![0x77; cold.len()];
        assert!(
            !app.render_for_presentation_with_monitor_defer(
                &mut direct_hit,
                false,
                false,
                false,
                false,
            )
            .expect("direct replay applies its own monitor gamma")
        );
        let mut expected = cached;
        configured_gamma.apply_to_rgba_bytes(&mut expected);
        assert_eq!(direct_hit, expected);
    }

    #[test]
    fn production_gamepad_batch_invalidates_cache_once_when_switching_options_sheet() {
        let mut app = new_real_classic_menu_app(640, 480);
        let mut frame = vec![0_u8; 640 * 480 * 4];
        app.render(&mut frame).expect("cache supported main menu");
        let main_version = app.menu_render_version;
        app.process_gamepad_event_batch([GamepadEvent::Direction {
            slot: GamepadSlot::new(0),
            button: ControlButton::Down,
            state: ElementState::Pressed,
        }])
        .expect("supported main-menu gamepad navigation");
        assert_eq!(app.menu_render_version, main_version.wrapping_add(1));
        assert!(app.render(&mut frame).expect("redraw changed main menu"));

        app.open_options_menu();
        app.render(&mut frame)
            .expect("cache supported Program sheet");
        let options_version = app.menu_render_version;
        app.process_gamepad_event_batch([GamepadEvent::Direction {
            slot: GamepadSlot::new(0),
            button: ControlButton::Down,
            state: ElementState::Pressed,
        }])
        .expect("D-pad enters Graphics sheet");
        assert_eq!(app.menu_render_version, options_version.wrapping_add(1));
        let mut sentinel = vec![0xa9; 640 * 480 * 4];
        assert!(app.render(&mut sentinel).expect("render Graphics sheet"));
        assert!(sentinel.iter().any(|byte| *byte != 0xa9));
    }

    #[test]
    fn l033_graphical_debug_mode_reads_native_config_and_obeys_allow_debug() {
        let install = tempdir().expect("install root");
        let user_data = tempdir().expect("user data");
        let custom = tempdir().expect("custom config root");
        fs::create_dir_all(install.path().join("planet")).expect("planet directory");
        fs::write(install.path().join("planet/System.c4g"), b"stub")
            .expect("system group stub");
        let config_file = custom.path().join("debug.config");
        let _guard = EnvGuard::set(&[
            ("LC_INSTALL_ROOT", Some(install.path())),
            ("LC_USER_DATA_DIR", Some(user_data.path())),
            ("LC_CONFIG_FILE", None),
        ]);
        let paths = AppPaths::discover_with_config_file(Some(&config_file))
            .expect("discover explicit debug config");
        let mut engine = Engine::new();

        fs::write(&config_file, b"[General]\n").expect("write missing debug flag");
        arm_configured_graphical_engine_debug_mode(&mut engine, Some(&paths));
        assert!(!engine.debug_mode(), "missing DebugMode defaults off");

        fs::write(&config_file, b"[General]\nDebugMode=true\n").expect("enable debug mode");
        arm_configured_graphical_engine_debug_mode(&mut engine, Some(&paths));
        assert!(
            engine.debug_mode(),
            "DebugMode=true arms a graphical game"
        );

        engine.set_allow_debug(false);
        arm_configured_graphical_engine_debug_mode(&mut engine, Some(&paths));
        assert!(
            !engine.debug_mode(),
            "Parameters.AllowDebug=false is authoritative"
        );

        engine.set_allow_debug(true);
        fs::write(&config_file, b"[General]\nDebugMode= true\n")
            .expect("write malformed debug flag");
        arm_configured_graphical_engine_debug_mode(&mut engine, Some(&paths));
        assert!(
            !engine.debug_mode(),
            "native Boolean grammar does not skip whitespace after '='"
        );
    }

    #[test]
    fn l033_replay_script_injection_obeys_native_config() {
        assert!(!configured_allow_scripting_in_replays(b"[General]\n"));
        assert!(!configured_allow_scripting_in_replays(
            b"[General]\nAllowScriptingInReplays= true\n"
        ));
        assert!(configured_allow_scripting_in_replays(
            b"[General]\nAllowScriptingInReplays=true\n"
        ));

        let _lock = env_lock().lock();
        let fixture = tempdir().expect("replay scripting configuration");
        let (_guard, paths) = exact_loader_test_paths(fixture.path(), None);
        fs::write(
            paths.config_file(),
            b"[General]\nAllowScriptingInReplays=false\n",
        )
        .expect("disable replay scripting");

        let mut app = new_state_only_running_sandbox_app();
        app.app_paths = Some(paths.clone());
        app.synchronize_advanced_options_runtime();
        app.control_playback = Some(
            ControlRecordPlayback::from_bytes(&[0, clonk_engine::RCT_END])
                .expect("open replay marker"),
        );
        app.engine.set_debug_mode(true);
        let initial_gravity = app.engine.physics().gravity;

        app.process_running_chat_text("/script SetGravity(77)");
        assert_eq!(
            app.engine.physics().gravity,
            initial_gravity,
            "replay scripting defaults to the configured denial"
        );
        app.apply_ready_controls(
            1,
            vec![NetworkControl::EmMoveObject(
                clonk_engine::EmMoveObjectControlData {
                    action: clonk_engine::EMMO_SCRIPT,
                    objects: vec![999_999],
                    script: LegacyCString::from_bytes(b"SetGravity(78)".to_vec())
                        .expect("editor script is NUL-free"),
                    by_client: -1,
                    ..Default::default()
                },
            )],
        )
        .expect("deny replay editor script without aborting the batch");
        assert_eq!(app.engine.physics().gravity, initial_gravity);

        fs::write(
            paths.config_file(),
            b"[General]\nAllowScriptingInReplays=true\n",
        )
        .expect("enable replay scripting");
        app.synchronize_advanced_options_runtime();
        app.process_running_chat_text("/script SetGravity(88)");
        assert_eq!(
            app.engine.physics().gravity,
            88,
            "the native config flag admits a non-host replay script"
        );
        app.apply_ready_controls(
            2,
            vec![NetworkControl::EmMoveObject(
                clonk_engine::EmMoveObjectControlData {
                    action: clonk_engine::EMMO_SCRIPT,
                    objects: vec![999_999],
                    script: LegacyCString::from_bytes(b"SetGravity(99)".to_vec())
                        .expect("editor script is NUL-free"),
                    by_client: -1,
                    ..Default::default()
                },
            )],
        )
        .expect("execute allowed replay editor script");
        assert_eq!(app.engine.physics().gravity, 99);
    }

