    #[test]
    fn scale_three_clipped_main_menu_commits_native_captions_after_bilinear_base() {
        // C4FontLoader builds CStdFont with Application.GetScale(), while
        // StdGL filters ordinary image textures when scale != 1
        // (C4Fonts.cpp:158-173; StdFont.cpp:319-352,841-842; StdGL.cpp:527-532).
        let install_root = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(Path::parent)
            .and_then(Path::parent)
            .expect("repository root");
        let user_data = tempdir().expect("user data");
        let _guard = EnvGuard::set(&[
            ("LC_INSTALL_ROOT", Some(install_root)),
            ("LC_USER_DATA_DIR", Some(user_data.path())),
        ]);
        let paths = AppPaths::discover().expect("discover app paths");
        let mut app = GameApp::new(
            640,
            480,
            AudioOptions::default(),
            Some(&paths),
            RuntimeConfig {
                player_owner: 1,
                player_name: "Player".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("initialise app");
        wait_for_menu(&mut app);
        app.configure_native_startup_fonts(3.0, false);
        assert!(app.can_defer_native_main_menu_text(3.0));

        let mut presenter = clonk_scaling::FramePresenter::new(3.0, 1920, 1438);
        let mut output = vec![0_u8; 1920 * 1438 * 4];
        let refreshed = presenter
            .present(&mut output, |frame| {
                app.render_for_presentation(frame, true, false, false)
            })
            .expect("render filtered base");
        assert!(refreshed);
        let filtered_base = output.clone();
        app.render_native_main_menu_text(&mut output, 1920, 1438)
            .expect("render native main-menu captions");
        assert_ne!(output, filtered_base, "physical caption pass must draw");

        let button = clonk_frontend::main_menu_layout(640, 480).buttons[0];
        let changed_in_caption = (button.y * 3..(button.y + button.h) * 3).any(|y| {
            (button.x * 3..(button.x + button.w) * 3).any(|x| {
                let index = (y as usize * 1920 + x as usize) * 4;
                output[index..index + 4] != filtered_base[index..index + 4]
            })
        });
        assert!(
            changed_in_caption,
            "Start Game changed in physical button bounds"
        );
        assert_eq!(
            &output[..4],
            &filtered_base[..4],
            "background remains filtered"
        );

        let with_native_text = output.clone();
        let refreshed = presenter
            .present(&mut output, |frame| {
                app.render_for_presentation(frame, true, false, false)
            })
            .expect("replay cached base");
        assert!(
            !refreshed,
            "cached menu must not request another alpha overlay"
        );
        assert_eq!(output, with_native_text);
    }

    #[test]
    fn scale_three_open_startup_dialog_keeps_native_text_in_z_order() {
        let mut app = new_real_classic_menu_app(640, 480);
        app.graphics.set_runtime_sprite_filtering(3.0, false);
        app.configure_native_startup_fonts(3.0, false);
        for label in ["LOWER", "H"] {
            app.push_message_dialog(
                clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                    label,
                    label,
                    clonk_frontend::message_dialog::MessageDialogIcon::NOTIFY,
                ),
                MessageDialogContinuation::None,
            )
            .expect("push ordered startup dialog");
        }

        let (chrome, rendered, plan) = render_ordered_test_frame(&mut app, 3.0, 1920, 1440);
        assert!(
            plan.batches
                .first()
                .is_some_and(|batch| !batch.text.is_empty()
                    && batch
                        .text
                        .iter()
                        .all(|command| command.text != "LOWER" && command.text != "H")),
            "main-menu captions remain in the native base batch while dialogs are open"
        );
        let command_batch = |needle: &str| {
            plan.batches
                .iter()
                .enumerate()
                .find_map(|(index, batch)| {
                    batch
                        .text
                        .iter()
                        .find(|command| command.text == needle)
                        .map(|command| (index, command))
                })
                .unwrap_or_else(|| panic!("captured startup dialog text `{needle}`"))
        };
        let (lower_batch, _) = command_batch("LOWER");
        let (upper_batch, upper) = command_batch("H");
        assert!(
            lower_batch > 0 && upper_batch > lower_batch,
            "stacked dialogs must alternate chrome/text in ownership order: lower={lower_batch}, upper={upper_batch}"
        );
        assert!(
            plan.batches[upper_batch].logical_layer.is_some(),
            "the upper dialog chrome is composited after lower native text"
        );
        assert_one_pixel_native_edge(&chrome, &rendered, 1920, 1440, upper, 3.0);
    }

    #[test]
    fn direct_runtime_repairs_urls_truncated_by_the_old_rust_parser() {
        // C++ defaults both fields to the complete HTTPS URL
        // (C4Config.h:35-38; C4Config.cpp:545-550). The old Rust parser
        // treated `//` as a comment and persisted only the scheme.
        let dir = tempdir().expect("config directory");
        let path = dir.path().join("legacyclonk.config");
        fs::write(
            &path,
            "[Network]\nServerAddress = https:\nAlternateServerAddress = http:\n",
        )
        .expect("seed truncated config");

        assert!(repair_rust_truncated_masterserver_urls(&path).expect("repair config"));

        let config = Config::load(path).expect("load repaired config");
        assert_eq!(
            config.get_in(Some("Network"), "ServerAddress"),
            Some(OFFICIAL_LEAGUE_SERVER)
        );
        assert_eq!(
            config.get_in(Some("Network"), "AlternateServerAddress"),
            Some(OFFICIAL_LEAGUE_SERVER)
        );
    }

    #[test]
    fn search_settings_recover_only_rust_truncated_masterserver_urls_before_query() {
        // C++ defaults both addresses to the complete official HTTPS URL, while
        // malformed non-default values remain inputs to ParseOldStyle
        // (C4Config.h:35-38; C4Config.cpp:253-259;
        // C4HTTPClient.cpp:105-118). Only bare schemes can be persisted damage
        // from the old Rust parser treating `//` as an inline comment.
        let install_root = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(Path::parent)
            .and_then(Path::parent)
            .expect("repository root");
        let user_data = tempdir().expect("user data");
        let _guard = EnvGuard::set(&[
            ("LC_INSTALL_ROOT", Some(install_root)),
            ("LC_USER_DATA_DIR", Some(user_data.path())),
        ]);
        let paths = AppPaths::discover().expect("discover app paths");
        paths.ensure_user_dirs().expect("create config directory");

        for (key, use_alternate, persisted, expected) in [
            (
                "ServerAddress",
                false,
                "https:",
                clonk_network::DEFAULT_MASTER_SERVER_URL,
            ),
            (
                "AlternateServerAddress",
                true,
                "http:",
                clonk_network::DEFAULT_MASTER_SERVER_URL,
            ),
            ("ServerAddress", false, "https://", "https://"),
        ] {
            let mut config = Config::new();
            config.set_in(Some("Network"), "MasterServerSignUp", "1");
            config.set_in(
                Some("Network"),
                "UseAlternateServer",
                i32::from(use_alternate).to_string(),
            );
            config.set_in(Some("Network"), key, persisted);
            config
                .save(paths.config_file())
                .expect("persist masterserver setting");

            let settings = load_network_search_settings(Some(&paths));
            assert_eq!(settings.use_alternate_server, use_alternate);
            assert_eq!(settings.master_server_url, expected);
            let mut search = clonk_network::NetworkGameSearch::new(settings);
            assert!(matches!(
                &search.refresh()[1],
                clonk_network::SearchCommand::QueryReferences {
                    endpoint: clonk_network::ReferenceEndpoint::Url(url),
                    source: clonk_network::ReferenceQuerySource::Masterserver,
                    ..
                } if url == expected
            ));
        }
    }

