    #[test]
    fn menu_backdrop_restore_matches_full_recomposition() {
        clonk_logging::init();

        let mut app = new_real_classic_menu_app(320, 200);
        let len = 320 * 200 * 4;
        let mut first = vec![0u8; len];
        app.render(&mut first).expect("cold render");

        // A recomposition that restores the cached static backdrop...
        app.mark_menu_dirty();
        let mut restored = vec![0u8; len];
        app.render(&mut restored).expect("backdrop-restored render");

        // ...must match one composed from scratch.
        app.mark_menu_dirty();
        app.menu_backdrop_cache = StartupBackdropCache::default();
        let mut recomposed = vec![0u8; len];
        app.render(&mut recomposed).expect("full recomposition");

        assert_eq!(
            restored, recomposed,
            "backdrop restore must be pixel-identical to a full recomposition"
        );
        assert_eq!(
            first, restored,
            "unchanged menu state must keep rendering identical frames"
        );
    }

    #[test]
    fn menu_resize_renders_at_new_dimensions() {
        clonk_logging::init();

        let mut app = new_real_classic_menu_app(320, 200);
        let mut frame = vec![0u8; 320 * 200 * 4];
        app.render(&mut frame).expect("render");
        app.resize(400, 300).expect("resize");
        let mut larger = vec![0u8; 400 * 300 * 4];
        app.render(&mut larger).expect("render after resize");
        let cache = app.menu_frame_cache.as_ref().expect("cache after resize");
        assert_eq!(
            (cache.width, cache.height),
            (400, 300),
            "cache must track the resized surface"
        );
    }

    #[test]
    fn boot_loading_resize_reflows_main_menu_to_final_fullscreen_size() {
        // This is the macOS startup sequence from the reported Scale=300
        // capture: the initial logical framebuffer is 1152x644, then deferred
        // fullscreen supplies 1152x723 before boot leaves Loading.
        let mut app = new_real_classic_menu_app(1152, 644);
        app.mode = AppMode::Loading;
        app.resize(1152, 723)
            .expect("apply deferred fullscreen resize during boot loading");
        assert_eq!(app.mode, AppMode::Loading);
        app.mode = AppMode::Menu;
        app.show_main_menu();
        assert_eq!(app.startup_view, StartupView::MainMenu);

        app.graphics.set_runtime_sprite_filtering(3.0, false);
        app.configure_native_startup_fonts(3.0, false);
        let mut logical_frame = vec![0_u8; 1152 * 723 * 4];
        app.render_ordered_native_base(&mut logical_frame)
            .expect("capture the production Main presentation after boot");
        let commands = app
            .pending_native_presentation
            .as_ref()
            .expect("ordered Main presentation plan")
            .batches
            .iter()
            .flat_map(|batch| batch.text.iter())
            .collect::<Vec<_>>();

        let start = commands
            .iter()
            .find(|command| command.text.ends_with("</c>tart Game"))
            .expect("captured first main-menu button label");
        assert_eq!(
            (start.role, start.align, start.x, start.y),
            (
                clonk_graphics::clonk_font::ClonkFontRole::GuiTitle,
                clonk_graphics::clonk_font::TextAlign::Center,
                944,
                203
            ),
            "the whole retained button column must use final fullscreen geometry"
        );

        let participants = commands
            .iter()
            .find(|command| command.text == app.main_menu_state.participants_label)
            .expect("captured Players footer label");
        assert_eq!(
            (
                participants.role,
                participants.align,
                participants.x,
                participants.y
            ),
            (
                clonk_graphics::clonk_font::ClonkFontRole::GuiTitle,
                clonk_graphics::clonk_font::TextAlign::Right,
                1101,
                640
            )
        );

        let trademark = commands
            .iter()
            .find(|command| command.text.starts_with("LegacyClonk is a fan project"))
            .expect("captured trademark footer label");
        assert_eq!(
            (
                trademark.role,
                trademark.align,
                trademark.x,
                trademark.y
            ),
            (
                clonk_graphics::clonk_font::ClonkFontRole::GuiMini,
                clonk_graphics::clonk_font::TextAlign::Right,
                1129,
                695
            )
        );

        // CStdGL installs a 3456x2169 viewport into the 2168-row framebuffer,
        // producing the one-row top crop seen in the reference capture.
        let projection = clonk_graphics::ClipperProjection::new(
            3.0,
            (1152, 723),
            2168,
            Rect::new(0, 0, 1152, 723),
        );
        assert_eq!(projection.physical_clip(), Rect::new(0, -1, 3456, 2169));
        assert_eq!(
            projection.logical_to_physical(participants.x.into(), participants.y.into()),
            (3303.0, 1919.0)
        );
        assert_eq!(
            projection.logical_to_physical(trademark.x.into(), trademark.y.into()),
            (3387.0, 2084.0)
        );
    }

    fn new_running_sandbox_app() -> GameApp {
        // Most state/input tests need the shipped CLNK definition but not the
        // much heavier shipped frontend bundle. Pixel/resource contracts use
        // the explicit classic constructor below.
        let paths = cached_app_paths().expect("discover sandbox crew definition");
        new_running_sandbox_app_with_definitions(SandboxDefinitionLoad::InstallCrew(
            paths.as_ref(),
        ))
    }

    fn finish_abort_dialog(
        app: &mut GameApp,
        result: clonk_frontend::message_dialog::MessageDialogResult,
    ) {
        assert!(app.message_dialogs.last().is_some_and(|dialog| matches!(
            dialog.continuation,
            MessageDialogContinuation::AbortGame { .. }
        )));
        app.finish_message_dialog(result)
            .expect("finish C4AbortGameDialog");
    }

    fn confirm_abort_dialog(app: &mut GameApp) {
        assert!(app.show_abort_dialog(app.local_owner));
        finish_abort_dialog(
            app,
            clonk_frontend::message_dialog::MessageDialogResult::Yes,
        );
    }

