    #[test]
    fn client_join_data_replaces_authoritative_control_registries() {
        // HandleJoinData deep-copies Game.Parameters. Game.Clients and
        // Game.PlayerInfos are references into that snapshot, so stale local
        // entries are replaced and the raw LastPlayerID counter is retained
        // (src/C4Network2.cpp:1574-1620; src/C4Game.cpp:64-70;
        // src/C4PlayerInfo.cpp:649-665).
        let mut app = new_state_only_menu_app(320, 200);
        app.control_clients.register(99, true, false);
        app.network_client_activity.mark_activated(99, 123);
        app.control_player_infos
            .apply(clonk_engine::PlayerInfoControlData {
                client_id: 99,
                players: vec![clonk_engine::ControlPlayerInfoEntry {
                    id: 3,
                    ..Default::default()
                }],
                ..Default::default()
            });
        let (manager, event_tx) = NetworkManager::test_stub_for_client_id(7);
        app.network = Some(manager);

        let host_config = clonk_network::HostConfig::default();
        let mut snapshot = host_config
            .initial_join_snapshot
            .expect("default host publishes JoinData");
        snapshot.parameters.clients = clonk_network::JoinClientRegistrySnapshot {
            clients: vec![
                clonk_engine::ClientCoreControlData {
                    client_id: 0,
                    activated: true,
                    name: clonk_engine::LegacyCString::from_bytes(b"Host".to_vec())
                        .expect("valid host name"),
                    lobby_ready: true,
                    ..Default::default()
                },
                clonk_engine::ClientCoreControlData {
                    client_id: 7,
                    name: clonk_engine::LegacyCString::from_bytes(b"Joining client".to_vec())
                        .expect("valid client name"),
                    nick: clonk_engine::LegacyCString::from_bytes(b"Joiner".to_vec())
                        .expect("valid client nick"),
                    ..Default::default()
                },
            ],
            local_client_id: Some(7),
        };
        snapshot.parameters.player_infos = clonk_network::PlayerInfoListSnapshot {
            last_player_id: 40,
            clients: vec![clonk_network::ClientPlayerInfosSnapshot {
                client_id: 0,
                flags: 0,
                players: vec![clonk_engine::ControlPlayerInfoEntry {
                    id: 12,
                    ..Default::default()
                }],
            }],
        };
        let join_data = clonk_network::JoinDataEnvelope {
            client_id: 7,
            start_control_tick: 23,
            status: host_config.initial_status,
            dynamic: snapshot.dynamic,
            parameters: snapshot.parameters,
        };
        event_tx
            .send(NetworkEvent::JoinData(join_data.clone()))
            .expect("queue JoinData");

        app.process_network_events().expect("apply JoinData");

        assert_eq!(app.pending_network_join_data, Some(join_data));
        assert!(!app.control_clients.contains(99));
        assert_eq!(
            app.network_client_activity.last_frame,
            BTreeMap::from([(0, 0), (7, 0)])
        );
        let host = app.control_clients.state(0).expect("host core restored");
        assert!(host.activated);
        assert!(host.lobby_ready);
        let local = app.control_clients.state(7).expect("local core restored");
        assert_eq!(local.name.as_bytes(), b"Joining client");
        assert_eq!(local.nick.as_bytes(), b"Joiner");
        assert!(app.control_player_infos.get(3).is_none());
        assert!(app.control_player_infos.get(12).is_some());
        let admitted = app
            .control_player_infos
            .admit_request(
                clonk_engine::PlayerInfoUpdateRequest {
                    client_id: 7,
                    flags: clonk_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS,
                    players: vec![clonk_engine::ControlPlayerInfoEntry::default()],
                },
                4,
            )
            .expect("one player slot remains");
        assert_eq!(admitted.players[0].id, 41);
    }

    #[test]
    fn client_join_data_replaces_the_lobby_participant_snapshot() {
        // Assigning Game.Parameters.Clients removes absent clients and copies
        // every authoritative C4ClientCore field before DoLobby renders the
        // participant list (src/C4Network2.cpp:1595-1602;
        // src/C4Client.cpp:284-290,321-350).
        let mut app = new_state_only_menu_app(320, 200);
        let (manager, event_tx) = NetworkManager::test_stub_for_client_id(7);
        app.network = Some(manager);
        let mut lobby = NetworkLobbyState::new(7, "stale local".to_string(), false);
        lobby.register_peer(99, "stale peer".to_string(), ParticipantKind::Player);
        app.network_lobby = Some(lobby);

        let host_config = clonk_network::HostConfig::default();
        let mut snapshot = host_config
            .initial_join_snapshot
            .expect("default host publishes JoinData");
        snapshot.parameters.title = clonk_engine::LegacyCString::from_bytes(b"Caf\xe9 Arena".to_vec())
            .expect("valid legacy scenario title");
        snapshot.parameters.clients = clonk_network::JoinClientRegistrySnapshot {
            clients: vec![
                clonk_engine::ClientCoreControlData {
                    client_id: 0,
                    activated: true,
                    name: clonk_engine::LegacyCString::from_bytes(b"Exact Andr\xe9".to_vec())
                        .expect("valid host name"),
                    lobby_ready: true,
                    ..Default::default()
                },
                clonk_engine::ClientCoreControlData {
                    client_id: 7,
                    name: clonk_engine::LegacyCString::from_bytes(b"Exact local".to_vec())
                        .expect("valid local name"),
                    ..Default::default()
                },
                clonk_engine::ClientCoreControlData {
                    client_id: 9,
                    observer: true,
                    name: clonk_engine::LegacyCString::from_bytes(b"Exact observer".to_vec())
                        .expect("valid observer name"),
                    lobby_ready: false,
                    ..Default::default()
                },
            ],
            local_client_id: Some(7),
        };
        let join_data = clonk_network::JoinDataEnvelope {
            client_id: 7,
            start_control_tick: snapshot.dynamic_tick,
            status: host_config.initial_status,
            dynamic: snapshot.dynamic,
            parameters: snapshot.parameters,
        };
        event_tx
            .send(NetworkEvent::JoinData(join_data))
            .expect("queue JoinData");

        app.process_network_events().expect("apply JoinData");

        let participants = &app
            .network_lobby
            .as_ref()
            .expect("client remains in lobby")
            .participants;
        assert_eq!(participants.keys().copied().collect::<Vec<_>>(), [0, 7, 9]);
        assert_eq!(participants[&0].name, "Exact Andr\u{e9}");
        assert!(participants[&0].ready);
        assert_eq!(participants[&7].name, "Exact local");
        assert!(!participants[&7].ready);
        assert_eq!(participants[&9].name, "Exact observer");
        assert_eq!(participants[&9].kind, ParticipantKind::Observer);
        assert!(!participants[&9].ready);
        assert_eq!(
            app.network_lobby
                .as_ref()
                .expect("client remains in lobby")
                .scenario_label(),
            "Caf\u{e9} Arena"
        );
        assert_eq!(app.scenario_label, "Caf\u{e9} Arena");
        assert_eq!(
            app.control_clients
                .state(0)
                .expect("raw host core remains registered")
                .name
                .as_bytes(),
            b"Exact Andr\xe9"
        );
        assert_eq!(
            app.pending_network_join_data
                .as_ref()
                .expect("raw JoinData remains pending")
                .parameters
                .title
                .as_bytes(),
            b"Caf\xe9 Arena"
        );
    }

    #[test]
    fn lobby_ready_gate_waits_for_registered_non_player_resource() {
        // MainDlg::UpdateResourceProgress keeps Ready disabled while any
        // registered non-player C4Network2Res is incomplete
        // (src/C4GameLobby.cpp:779-802).
        let mut resources = AdmissionResourceStore::default();
        let scenario = clonk_engine::NetworkResourceCore {
            resource_type: clonk_network::HostResourceType::Scenario as u8,
            id: 41,
            loadable: true,
            ..Default::default()
        };

        resources.register_lobby_resource(&scenario);
        assert!(!resources.lobby_ready_available());

        resources.mark_complete(scenario.id, PathBuf::from("Scenario.c4s"));
        assert!(resources.lobby_ready_available());
    }

    #[test]
    fn lobby_ready_gate_ignores_incomplete_player_resource() {
        // MainDlg::UpdateResourceProgress explicitly excludes NRT_Player from
        // the resource-completeness gate (src/C4GameLobby.cpp:781-790).
        let mut resources = AdmissionResourceStore::default();
        resources.register_lobby_resource(&clonk_engine::NetworkResourceCore {
            resource_type: clonk_network::HostResourceType::Player as u8,
            id: 42,
            loadable: true,
            ..Default::default()
        });

        assert!(resources.lobby_ready_available());
    }

    #[test]
    fn synchronized_player_derivation_registers_the_latest_core_before_event_drain() {
        // C4Player::Save looks the resource up by its stable mutable filename,
        // so every later save derives from the newest official resource. The
        // mutable path and its ownership remain the derived resource's file
        // (src/C4Player.cpp:452-461; src/C4Network2Res.cpp:718-823).
        let mut resources = AdmissionResourceStore::default();
        let root = clonk_engine::NetworkResourceCore {
            resource_type: clonk_network::HostResourceType::Player as u8,
            id: 40,
            loadable: true,
            ..Default::default()
        };
        let first = clonk_engine::NetworkResourceCore {
            id: 41,
            derived_id: root.id,
            ..root.clone()
        };
        let second = clonk_engine::NetworkResourceCore {
            id: 42,
            derived_id: first.id,
            ..root.clone()
        };
        resources.register_lobby_resource(&root);
        resources.mark_complete_with_locality(root.id, PathBuf::from("Alice.c4p"), true);
        resources.register_finished_derivation(
            &first,
            PathBuf::from("Alice.c4p"),
            clonk_network::ResourceFileOwnership::Persistent,
        );
        resources.register_finished_derivation(
            &second,
            PathBuf::from("Alice.c4p"),
            clonk_network::ResourceFileOwnership::Persistent,
        );

        assert_eq!(resources.derivation_target(root.id), Some(second.id));
        assert_eq!(
            resources.status(second.id),
            Some(&AdmissionResourceState::Complete {
                path: PathBuf::from("Alice.c4p"),
                removed: false,
                local: true,
            })
        );

        let remote = clonk_engine::NetworkResourceCore {
            id: 50,
            ..root
        };
        resources.register_lobby_resource(&remote);
        resources.mark_complete_with_locality(
            remote.id,
            PathBuf::from("Network/Bob.c4p"),
            false,
        );
        let remote_derived = clonk_engine::NetworkResourceCore {
            id: 51,
            derived_id: remote.id,
            ..remote.clone()
        };
        resources.register_finished_derivation(
            &remote_derived,
            PathBuf::from("Network/Bob.c4p"),
            clonk_network::ResourceFileOwnership::Temporary,
        );
        assert_eq!(resources.derivation_target(remote.id), Some(remote_derived.id));
        assert_eq!(
            resources.status(remote_derived.id),
            Some(&AdmissionResourceState::Complete {
                path: PathBuf::from("Network/Bob.c4p"),
                removed: false,
                local: false,
            })
        );
    }

    #[test]
    fn lobby_preload_gate_uses_one_shared_eligibility_edge_and_success_is_one_shot() {
        let mut automatic = LobbyPreloadState::new(true);
        assert!(!automatic.synchronize(false, true));
        assert!(!automatic.synchronize(true, false));
        assert!(automatic.synchronize(true, true));
        assert!(!automatic.synchronize(true, true));
        automatic.record_result(false);
        assert!(automatic.eligible, "failure remains eligible but does not spin");
        assert!(!automatic.synchronize(true, true));
        assert!(!automatic.synchronize(false, true));
        assert!(automatic.synchronize(true, true));

        let mut manual = LobbyPreloadState::new(false);
        assert!(!manual.synchronize(true, true));
        assert!(manual.manual_button_present);
        assert!(manual.eligible);
        manual.record_result(true);
        assert!(manual.spent);
        assert!(!manual.eligible);
        assert!(!manual.manual_button_present);
        assert!(!manual.synchronize(true, true));
        manual.reset_for_context();
        assert!(!manual.spent);
        assert!(manual.manual_button_present);
        assert!(!manual.synchronize(true, true));
        assert!(manual.eligible);
    }

