    #[test]
    fn repeated_or_irrelevant_unready_does_not_abort_manual_countdown() {
        // HandleReadyCheck invokes the lobby callback only for an actual
        // state change. OnClientReadyStateChange returns at the first relevant
        // unready client and aborts only when that exact client changed
        // (pristine 9ffa0a5d src/C4GameLobby.cpp:872-885;
        // src/C4Network2.cpp:1721-1729).
        let mut app = new_state_only_menu_app(320, 200);
        let scenario = FrontendScenario::fallback();
        app.scenario_catalog
            .insert(scenario.identifier.clone(), scenario.clone());
        let mut lobby = NetworkLobbyState::new(0, "Host".to_string(), true);
        lobby.select_scenario(&scenario.identifier, &scenario.title);
        lobby.participants.get_mut(&0).unwrap().ready = true;
        lobby.register_peer(7, "Unready player".to_string(), ParticipantKind::Player);
        lobby.register_peer(9, "Empty client".to_string(), ParticipantKind::Observer);
        lobby.participants.get_mut(&9).unwrap().ready = true;
        app.network_lobby = Some(lobby);
        app.network_mode = Some(NetworkMode::Host(HostSettings {
            bind_addr: SocketAddr::from(([127, 0, 0, 1], 0)),
            player_name: "Host".to_string(),
            prepared: None,
        }));
        app.control_player_infos
            .apply(clonk_engine::PlayerInfoControlData {
                client_id: 7,
                players: vec![clonk_engine::ControlPlayerInfoEntry {
                    id: 1,
                    ..Default::default()
                }],
                ..Default::default()
            });
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.process_lobby_action(LobbyAction::StartGame)
            .expect("manual start ignores readiness");
        assert_eq!(
            commands.take_submitted_lobby_countdowns(),
            vec![clonk_network::LobbyCountdownPacket::new(5)]
        );

        for packet in [
            clonk_network::ReadyCheckPacket {
                client_id: 7,
                data: clonk_network::ReadyCheckData::NotReady,
            },
            clonk_network::ReadyCheckPacket {
                client_id: 7,
                data: clonk_network::ReadyCheckData::Ready,
            },
            clonk_network::ReadyCheckPacket {
                client_id: 9,
                data: clonk_network::ReadyCheckData::NotReady,
            },
        ] {
            event_tx
                .send(NetworkEvent::ReadyCheck(packet))
                .expect("queue ready state");
            app.process_network_events().expect("apply ready state");
            assert!(commands.take_submitted_lobby_countdowns().is_empty());
            assert!(app.host_lobby_countdown.is_some());
            assert_eq!(app.network_lobby.as_ref().unwrap().countdown, Some(5));
        }
    }

    #[test]
    fn player_info_add_or_remove_alone_does_not_trigger_ready_autostart() {
        // C4Network2 invokes OnClientReadyStateChange only from an actual
        // ReadyCheck state transition; changing C4ClientPlayerInfos merely
        // changes which clients a later ready transition will consider
        // (pristine 9ffa0a5d src/C4Network2.cpp:1721-1729;
        // src/C4GameLobby.cpp:868-893).
        let mut app = new_state_only_menu_app(320, 200);
        let scenario = FrontendScenario::fallback();
        app.scenario_catalog
            .insert(scenario.identifier.clone(), scenario.clone());
        let mut lobby = NetworkLobbyState::new(0, "Host".to_string(), true);
        lobby.select_scenario(&scenario.identifier, &scenario.title);
        lobby.participants.get_mut(&0).unwrap().ready = true;
        lobby.register_peer(7, "Remote".to_string(), ParticipantKind::Player);
        lobby.participants.get_mut(&7).unwrap().ready = true;
        app.network_lobby = Some(lobby);
        app.network_mode = Some(NetworkMode::Host(HostSettings {
            bind_addr: SocketAddr::from(([127, 0, 0, 1], 0)),
            player_name: "Host".to_string(),
            prepared: None,
        }));
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        event_tx
            .send(NetworkEvent::DirectControl(NetworkControl::PlayerInfo(
                clonk_engine::PlayerInfoControlData {
                    client_id: 7,
                    players: vec![clonk_engine::ControlPlayerInfoEntry {
                        id: 1,
                        ..Default::default()
                    }],
                    ..Default::default()
                },
            )))
            .expect("queue PlayerInfo addition");

        app.process_network_events()
            .expect("apply PlayerInfo addition");

        assert_eq!(app.control_player_infos.client_info_ids(7), vec![1]);
        assert!(commands.take_submitted_lobby_countdowns().is_empty());
        assert!(app.host_lobby_countdown.is_none());

        app.network_lobby
            .as_mut()
            .unwrap()
            .participants
            .get_mut(&7)
            .unwrap()
            .ready = false;
        event_tx
            .send(NetworkEvent::DirectControl(NetworkControl::PlayerInfo(
                clonk_engine::PlayerInfoControlData {
                    client_id: 7,
                    players: Vec::new(),
                    ..Default::default()
                },
            )))
            .expect("queue PlayerInfo removal");

        app.process_network_events()
            .expect("apply PlayerInfo removal");

        assert!(app.control_player_infos.client_info_ids(7).is_empty());
        assert!(commands.take_submitted_lobby_countdowns().is_empty());
        assert!(app.host_lobby_countdown.is_none());
    }

    #[test]
    fn activate_new_player_lists_cpp_eligible_files_in_source_order_and_closes_when_full() {
        // ActivateNewPlayer preserves DirectoryIterator order, skips directory
        // groups and files already used by a joined player, and refuses to
        // open once Game.Parameters.MaxPlayers is reached
        // (pristine 9ffa0a5d src/C4MainMenu.cpp:59-121;
        // src/C4PlayerList.cpp:433-451).
        let directory = tempdir().expect("create player directory");
        let write_packed_player = |filename: &str, name: &str| {
            let path = directory.path().join(filename);
            let mut group = clonk_resources::MutableGroup::new(filename);
            group
                .add_file_with_metadata(
                    "Player.txt",
                    format!("[Player]\nName={name}\n[Preferences]\nColorDw=255\n").into_bytes(),
                    1,
                    false,
                )
                .expect("add player core");
            fs::write(&path, group.pack().expect("pack player")).expect("write packed player");
            path
        };
        let zulu = write_packed_player("Zulu.c4p", "Zulu");
        let active = write_packed_player("Active.c4p", "Active");
        let alpha = write_packed_player("Alpha.c4p", "Alpha");
        let folder = directory.path().join("Folder.c4p");
        fs::create_dir_all(&folder).expect("create directory player group");
        fs::write(
            folder.join("Player.txt"),
            "[Player]\nName=Folder\n[Preferences]\nColorDw=255\n",
        )
        .expect("write directory player core");

        let mut config = Config::new();
        config.set_in(
            Some("General"),
            "PlayerPath",
            directory.path().to_string_lossy(),
        );
        config.set_in(Some("General"), "Participants", active.to_string_lossy());
        let mut players = startup_player_files::discover_player_files_in(directory.path(), &config)
            .expect("discover player files");
        players.sort_by_key(|player| match player.player_file.name.as_str() {
            "Zulu" => 0,
            "Active" => 1,
            "Folder" => 2,
            "Alpha" => 3,
            _ => 4,
        });

        let mut app = new_running_sandbox_app();
        app.startup_player_files = players;
        app.apply_ingame_menu_action(MenuAction::ActivateNewPlayer)
            .expect("open new-player menu");

        let menu = app.ingame_menu.as_ref().expect("new-player menu opens");
        assert_eq!(
            menu.items()
                .iter()
                .map(|item| item.caption.as_str())
                .collect::<Vec<_>>(),
            ["Join player: Zulu", "Join player: Alpha"]
        );
        assert_eq!(
            menu.items()
                .iter()
                .map(|item| item.action.clone())
                .collect::<Vec<_>>(),
            [
                MenuAction::JoinPlayer(zulu.to_string_lossy().into_owned()),
                MenuAction::JoinPlayer(alpha.to_string_lossy().into_owned()),
            ]
        );

        app.snapshot.players = (0..12)
            .map(|id| clonk_engine::PlayerState {
                id,
                ..Default::default()
            })
            .collect();
        app.ingame_menu.clear();
        app.apply_ingame_menu_action(MenuAction::ActivateNewPlayer)
            .expect("full-game activation is ignored");
        assert!(
            app.ingame_menu.is_none(),
            "a full game keeps the submenu closed"
        );
    }

    #[test]
    fn main_menu_player_join_uses_active_network_max_players() {
        // ActivateMain compares the live Game.Players count with the host's
        // synchronized Game.Parameters.MaxPlayers before adding New Player;
        // it never substitutes the scenario default after JoinData
        // (pristine 9ffa0a5d src/C4MainMenu.cpp:643-686).
        let mut app = new_state_only_running_sandbox_app();
        app.network_max_players = 1;
        app.snapshot.players = vec![clonk_engine::PlayerState {
            id: app.local_owner,
            ..Default::default()
        }];

        let conditions = app.main_menu_conditions();
        let menu = IngameMenuState::main_menu(&conditions).expect("main menu has entries");

        assert_eq!(conditions.max_players, 1);
        assert!(!menu
            .items()
            .iter()
            .any(|item| item.action == MenuAction::ActivateNewPlayer));
    }

    #[test]
    fn offline_runtime_join_player_local_no_network() {
        // JoinPlayer:<file> selects CtrlJoinLocalNoNetwork when networking is
        // disabled. That path loads one local AddPlayers record, applies it as
        // CID_PlrInfo, and lets LocalJoinUnjoinedPlayersInQueue issue the
        // filename-backed join for the local control client
        // (src/C4MainMenu.cpp:761-771; src/C4PlayerList.cpp:320-330;
        // src/C4PlayerInfo.cpp:693-733).
        let player_path = Path::new(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../clonk-engine/tests/fixtures/embedded_player.c4p"
        ));
        let player_file = PlayerFile::load_from_path(player_path).expect("load player fixture");
        let mut app = new_synthetic_running_sandbox_app();
        app.startup_player_files.push(StartupPlayerFile {
            path: player_path.to_path_buf(),
            file_name: player_path
                .file_name()
                .expect("fixture has a basename")
                .to_string_lossy()
                .into_owned(),
            player_file: player_file.clone(),
            render_model: clonk_frontend::startup_plrsel::PlrSelPlayer {
                name: player_file.name.clone(),
                activated: false,
                big_icon: None,
                portrait: None,
                color_dw: player_file.normalized_preferred_color(),
                score: player_file.score,
                rounds: player_file.rounds,
                rounds_won: player_file.rounds_won,
                rounds_lost: player_file.rounds_lost,
                total_playing_time: player_file.total_playing_time,
                comment: String::new(),
            },
        });
        assert!(app.network.is_none());
        assert!(app.network_mode.is_none());
        let before_players = app.engine.snapshot().players.len();
        let before_info_ids = app.control_player_infos.client_info_ids(0);
        app.status_text = "offline join sentinel".to_string();
        let recording_directory = tempdir().expect("create recording directory");
        let recording_path = recording_directory.path().join("001-OfflineRuntime.c4s");
        install_test_recording_template(&mut app, recording_path.clone());
        app.start_recording(true)
            .expect("start offline runtime recording");
        let recorded_frame = u32::try_from(app.engine.frame()).expect("fixture frame fits u32");

        app.apply_ingame_menu_action(MenuAction::JoinPlayer(
            player_path.to_string_lossy().into_owned(),
        ))
        .expect("offline runtime player joins");

        let joined_info_ids = app
            .control_player_infos
            .client_info_ids(0)
            .into_iter()
            .filter(|info_id| !before_info_ids.contains(info_id))
            .collect::<Vec<_>>();
        let [joined_info_id] = joined_info_ids.as_slice() else {
            panic!("expected one new local player info, got {joined_info_ids:?}");
        };
        let info = app
            .control_player_infos
            .get(*joined_info_id)
            .expect("offline AddPlayers info is retained");
        assert_eq!(
            info.filename.as_bytes(),
            clonk_script::c4_string_bytes(player_path.to_string_lossy().as_ref())
        );
        assert_eq!(info.name.as_bytes(), clonk_script::c4_string_bytes(&player_file.name));
        assert_eq!(
            (info.color, info.original_color),
            (
                player_file.normalized_preferred_color(),
                player_file.normalized_preferred_color(),
            )
        );
        assert_eq!(info.resource, None);
        assert_eq!(
            info.flags
                & (clonk_engine::PLAYER_INFO_FLAG_HAS_RESOURCE
                    | clonk_engine::PLAYER_INFO_FLAG_JOINED),
            clonk_engine::PLAYER_INFO_FLAG_JOINED
        );

        let snapshot = app.engine.snapshot();
        assert_eq!(snapshot.players.len(), before_players + 1);
        let joined = snapshot
            .players
            .iter()
            .find(|player| player.player_info_id == *joined_info_id)
            .expect("PlayerInfo execution joins the runtime player");
        assert_eq!(
            app.engine
                .player(joined.id)
                .expect("joined player remains live")
                .at_client(),
            clonk_engine::PlayerAtClient::HOST
        );
        assert!(snapshot.hud.local_players.contains(&joined.id));
        assert!(app.local_controls.assignment(joined.id).is_some());
        assert!(app
            .physical_viewports
            .iter()
            .any(|viewport| viewport.displayed_player == joined.id));
        assert_eq!(app.status_text, "offline join sentinel");
        app.apply_ingame_menu_action(MenuAction::ActivateNewPlayer)
            .expect("reopen runtime player menu");
        assert!(app
            .ingame_menu
            .as_ref()
            .expect("other runtime player rows keep the menu open")
            .items()
            .iter()
            .all(|item| {
                item.action
                    != MenuAction::JoinPlayer(player_path.to_string_lossy().into_owned())
            }));

        assert!(app.finish_recording().is_none());
        let recording = Group::open(&recording_path).expect("open offline runtime recording");
        let mut playback = ControlRecordPlayback::from_bytes(
            &recording
                .read_file("CtrlRec.c4b")
                .expect("read offline runtime control stream"),
        )
        .expect("decode offline runtime control stream");
        let recorded_controls = playback.take_controls(recorded_frame);
        assert!(recorded_controls.iter().any(|packet| {
            matches!(
                packet,
                clonk_engine::ControlPacket::PlayerInfo(info)
                    if info.players.iter().any(|player| player.id == *joined_info_id)
            )
        }));
        assert!(recorded_controls.iter().any(|packet| {
            matches!(
                packet,
                clonk_engine::ControlPacket::JoinPlayer(join)
                    if join.info_id == *joined_info_id
                        && matches!(
                            &join.source,
                            clonk_engine::JoinPlayerSource::Embedded(data) if !data.is_empty()
                        )
            )
        }));

        let malformed_directory = tempdir().expect("create malformed player directory");
        let malformed = malformed_directory.path().join("Malformed.c4p");
        fs::write(&malformed, b"not a packed player group").expect("write malformed player");
        let before_failure_players = app.engine.snapshot().players;
        let before_failure_infos = app.control_player_infos.retained_rows_snapshot();
        let error = app
            .apply_ingame_menu_action(MenuAction::JoinPlayer(
                malformed.to_string_lossy().into_owned(),
            ))
            .expect_err("malformed offline player returns a typed boundary");
        let detail = match error {
            EngineError::ClassicMenuParityBoundary { detail } => detail,
            other => panic!("offline failure returned the wrong error: {other}"),
        };
        assert!(detail.contains("classic offline in-game player join failed"));
        assert!(detail.contains("failed to load"));
        assert!(detail.contains(&malformed.to_string_lossy().into_owned()));
        assert_eq!(app.status_text, "offline join sentinel");
        assert_eq!(app.engine.snapshot().players, before_failure_players);
        assert_eq!(
            app.control_player_infos.retained_rows_snapshot(),
            before_failure_infos
        );
    }

    #[test]
    fn team_selection_execute_queues_the_only_non_full_team() {
        // C4Player::Execute asks GetForcedTeamSelection while in
        // PS_TeamSelection, closes C4MN_TeamSelection, and queues
        // DoTeamSelection for the sole joinable team. Full alternatives do
        // not prevent the forced choice (C4Player.cpp:159-173;
        // C4Teams.cpp:876-914).
        let mut app = new_running_sandbox_app();
        let occupant = app.local_owner;
        app.engine.set_teams(vec![
            clonk_engine::TeamInfo::new(1, "Full", 0x00f4_0000).with_max_players(1),
            clonk_engine::TeamInfo::new(2, "Open", 0x0000_c800),
        ]);
        app.engine
            .player_mut(occupant)
            .expect("sandbox player remains")
            .set_team(Some(1));
        let chooser = app
            .engine
            .join_player_for_team_selection(JoinPlayerConfig {
                name: "Chooser".to_string(),
                player_info_id: 0,
                score: 0,
                rounds: 0,
                rounds_won: 0,
                rounds_lost: 0,
                total_playing_time: 0,
                team: None,
                color_dw: 0x0000_c800,
                pref_color: 0,
                pref_position: 0,
                crew: Vec::new(),
                control_style: false,
                auto_context_menu: false,
                startup_player_count: 2,
            })
            .expect("chooser waits for team selection");
        app.local_controls.initialize(LocalControlInit {
            owner: chooser,
            preferred_set: 1,
            prefers_mouse: false,
            gamepads_enabled: true,
            replay: false,
            disable_mouse: false,
        });
        app.engine.set_local_players([occupant, chooser]);
        app.open_initial_team_selection(chooser);
        assert!(app.ingame_menu.is_some(), "selection menu starts open");
        let (manager, events, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        let tick = app.local_control_submission_tick();
        events
            .send(NetworkEvent::ReadyTick {
                tick,
                controls: Vec::new(),
            })
            .expect("complete control tick is ready");

        app.update().expect("team-selection execute succeeds");

        assert_eq!(
            app.engine.player(chooser).map(clonk_engine::Player::status),
            Some(PlayerStatus::TeamSelectionPending)
        );
        assert!(
            app.ingame_menu.is_none(),
            "forced selection closes the menu"
        );
        assert_eq!(
            commands.take_submitted_init_scenario_players(),
            vec![(
                tick,
                clonk_engine::InitScenarioPlayerControlData {
                    team: 2,
                    player: chooser,
                    by_client: 0,
                },
            )]
        );
    }

    #[test]
    fn synchronized_team_selection_and_runtime_switch_refresh_live_parameters() {
        let mut app = new_state_only_synthetic_crew_running_sandbox_app();
        app.engine.set_team_colors(true);
        app.engine.set_teams(vec![
            clonk_engine::TeamInfo::new(1, "Red", 0x00f4_0000),
            clonk_engine::TeamInfo::new(2, "Green", 0x0000_c800),
        ]);
        let chooser = app
            .engine
            .join_player_for_team_selection(JoinPlayerConfig {
                name: "Chooser".to_string(),
                player_info_id: 41,
                score: 0,
                rounds: 0,
                rounds_won: 0,
                rounds_lost: 0,
                total_playing_time: 0,
                team: None,
                color_dw: 0x0012_3456,
                pref_color: 0,
                pref_position: 0,
                crew: Vec::new(),
                control_style: false,
                auto_context_menu: false,
                startup_player_count: 2,
            })
            .expect("chooser waits for team selection");
        app.control_player_infos
            .apply(clonk_engine::PlayerInfoControlData {
                client_id: 0,
                players: vec![clonk_engine::ControlPlayerInfoEntry {
                    id: 41,
                    color: 0x0012_3456,
                    original_color: 0x0012_3456,
                    ..Default::default()
                }],
                ..Default::default()
            });
        let (host_snapshot, reference) = default_exact_host_reference();
        app.control_clients
            .replace_snapshot(host_snapshot.parameters.clients.clients.clone());
        app.host_join_snapshot = Some(host_snapshot);
        app.advertised_game_reference = Some(reference);
        let (manager, _events) = NetworkManager::test_stub_for_client_id(0);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(HostSettings {
            bind_addr: SocketAddr::from(([127, 0, 0, 1], 0)),
            player_name: "Host".to_string(),
            prepared: None,
        }));

        app.execute_init_scenario_player_control(chooser, 2)
            .expect("synchronized team choice executes");

        let info = app
            .control_player_infos
            .get(41)
            .expect("PlayerInfo retained");
        assert_eq!(
            (info.team, info.color, info.original_color),
            (2, 0x0000_c800, 0x0012_3456)
        );
        assert_eq!(
            app.engine
                .teams()
                .iter()
                .find(|team| team.id == 2)
                .expect("green team")
                .player_ids,
            vec![41]
        );
        let parameters = &app.host_join_snapshot.as_ref().unwrap().parameters;
        assert_eq!(parameters.player_infos.clients[0].players[0].team, 2);
        assert_eq!(parameters.teams.teams[1].player_ids, vec![41]);

        app.engine
            .set_player_team(chooser, Some(1))
            .expect("script-style runtime team switch");
        app.handle_script_player_info_updates()
            .expect("post-script parameter refresh");

        assert_eq!(app.control_player_infos.get(41).unwrap().team, 1);
        let parameters = &app.host_join_snapshot.as_ref().unwrap().parameters;
        assert_eq!(parameters.player_infos.clients[0].players[0].team, 1);
        assert_eq!(parameters.teams.teams[0].player_ids, vec![41]);
        assert!(parameters.teams.teams[1].player_ids.is_empty());
    }

    #[test]
    fn l135_team_selection_entries_cache_icon_specs_and_player_info_occupancy() {
        let mut app = new_running_sandbox_app();
        let owner = app.local_owner;
        let mut definition =
            Definition::from_script("TICO", "Team icon", "").expect("team icon definition");
        definition.set_picture(Some(clonk_engine::DefinitionPicture {
            x: 0,
            y: 0,
            width: 1,
            height: 1,
        }));
        definition.set_sprite_image(Some(clonk_engine::DefinitionSpriteImage {
            width: 1,
            height: 1,
            pixels: Arc::from([0xff, 0xff, 0xff, 0xff]),
            color_mask: Some(Arc::from([0xff_u8])),
        }));
        app.engine
            .register_definition(definition)
            .expect("register team icon definition");
        app.engine.set_teams(vec![
            clonk_engine::TeamInfo::new(1, "Declared", 0x0011_2233)
                .with_player_ids(vec![999])
                .with_icon_spec("TICO"),
            clonk_engine::TeamInfo::new(2, "Missing", 0x0044_5566).with_icon_spec("MISS"),
        ]);

        let entries = app.team_selection_entries();
        assert_eq!(
            (
                entries[0].icon_spec.as_deref(),
                entries[0].color,
                entries[0].has_participants,
            ),
            (Some("TICO"), 0x0011_2233, true),
            "C4Team::GetPlayerCount includes retained, not-yet-joined PlayerInfo IDs"
        );
        assert_eq!(
            (
                entries[1].icon_spec.as_deref(),
                entries[1].color,
                entries[1].has_participants,
            ),
            (Some("MISS"), 0x0044_5566, false)
        );

        app.engine
            .set_player_status(owner, PlayerStatus::TeamSelection)
            .expect("open initial team selection for the local player");
        app.open_initial_team_selection(owner);
        let team_icons = &app
            .ingame_menu_gfx
            .as_ref()
            .expect("team menu graphics cache")
            .team_icons;
        assert_eq!(
            team_icons.get(&1).map(ImageData::pixels),
            Some([0x11, 0x22, 0x33, 0xff].as_slice())
        );
        assert!(
            !team_icons.contains_key(&2),
            "an unresolved IconSpec must remain eligible for the renderer fallback"
        );
    }

