    #[test]
    fn league_signup_persists_account_but_not_session_password() {
        let _lock = env_lock().lock();
        let user_data = tempdir().expect("isolated league configuration");
        let (_guard, paths) = exact_loader_test_paths(user_data.path(), None);
        let account = LegacyCString::from_bytes(b"Andr\xe9".to_vec()).unwrap();

        persist_league_account_preference(&paths, &account).expect("persist native league account");
        let config = fs::read(paths.config_file()).expect("read native league configuration");
        assert_eq!(
            clonk_app::configured_native_value(&config, "Network", "LeagueNick")
                .expect("persisted LeagueNick")
                .as_bytes(),
            b"Andr\xe9"
        );
        assert!(
            clonk_app::configured_native_value(&config, "Network", "LeaguePassword").is_none(),
            "C++ keeps the entered password in process memory only"
        );

        // C4Config never compiles LeaguePassword. Even a stale hand-written
        // key cannot become an auto-login credential after process startup.
        persist_native_config_values(
            &paths,
            "Network",
            &[
                (
                    "LeaguePassword",
                    clonk_app::NativeConfigValue::CppEscapedString(b"secret"),
                ),
                ("LeagueAutoLogin", clonk_app::NativeConfigValue::RawAscii("1")),
            ],
        )
        .expect("seed ignored disk password");
        let mut app = new_menu_app_with_paths(320, 200, &paths);
        assert!(load_league_auth_settings(Some(&paths)).password.is_empty());
        assert!(app.league_login_prompt_required());

        app.league_auth_session = Some(clonk_network::LeagueAuthRequestHead {
            account,
            password: LegacyCString::from_bytes(b"session secret".to_vec()).unwrap(),
            ..Default::default()
        });
        assert!(!app.league_login_prompt_required());
        persist_native_config_values(
            &paths,
            "Network",
            &[("LeagueAutoLogin", clonk_app::NativeConfigValue::RawAscii("0"))],
        )
        .expect("disable league auto-login");
        assert!(app.league_login_prompt_required());
    }

    #[test]
    fn league_signup_edit_interactions_match_classic_edit_behavior() {
        use clonk_frontend::league_signup::{
            LeagueSignupAction, LeagueSignupConfig, LeagueSignupControl,
            LeagueSignupEditClipboardShortcut, LeagueSignupEditContextCommand,
            LeagueSignupEditKey, LeagueSignupField, LeagueSignupKeyModifiers, LeagueSignupMode,
            LeagueSignupStrings,
        };

        let app = new_classic_running_sandbox_app();
        let font = &app.assets.clonk_fonts.as_deref().expect("classic fonts").text;
        let mut login = clonk_frontend::league_signup::LeagueSignupController::new(
            LeagueSignupConfig::new("Player", "league.example", LeagueSignupMode::Login)
                .with_preferences("account", "secret"),
            LeagueSignupStrings::default(),
        );
        let layout = login.layout(1280, 720, font);

        login.set_account(&"wide".repeat(80));
        login.set_focus(LeagueSignupControl::Account);
        login.handle_edit_key_with_layout(
            LeagueSignupEditKey::End,
            LeagueSignupKeyModifiers::default(),
            &layout,
            font,
        );
        assert!(login.field_horizontal_scroll(LeagueSignupField::Account) > 0);

        login.set_account("alpha beta");
        login.set_focus(LeagueSignupControl::Password);
        let beta_x = layout.account.edit.x
            + 4
            + font.measure("alpha be", false).0;
        let edit_y = layout.account.edit.y + layout.account.edit.h / 2;
        login.handle_pointer_double_click(
            GuiPoint::new(beta_x as f32, edit_y as f32),
            &layout,
            font,
        );
        let (start, end) = login
            .field_selection(LeagueSignupField::Account)
            .expect("double-click word selection");
        assert_eq!(&login.account()[start..end], "beta");
        assert_eq!(
            login.focused_control(),
            Some(LeagueSignupControl::Password),
            "LeftDouble does not synthesize Control's LeftDown focus transfer"
        );

        let left = GuiPoint::new((layout.account.edit.x + 5) as f32, edit_y as f32);
        let right = GuiPoint::new(
            (layout.account.edit.x + layout.account.edit.w - 5) as f32,
            edit_y as f32,
        );
        login.handle_pointer_down(left, &layout, font);
        login.handle_pointer_up(right, &layout, font);
        assert!(login.field_selection(LeagueSignupField::Account).is_some());

        login.set_focus(LeagueSignupControl::Password);
        login.handle_clipboard_shortcut(
            LeagueSignupEditClipboardShortcut::SelectAll,
            None,
            &layout,
            font,
        );
        assert!(matches!(
            login
                .handle_clipboard_shortcut(
                    LeagueSignupEditClipboardShortcut::Copy,
                    None,
                    &layout,
                    font,
                )
                .as_slice(),
            [LeagueSignupAction::ClipboardTransfer { text, cut: false, .. }]
                if text == "secret"
        ));
        assert!(matches!(
            login
                .handle_clipboard_shortcut(
                    LeagueSignupEditClipboardShortcut::Cut,
                    None,
                    &layout,
                    font,
                )
                .as_slice(),
            [LeagueSignupAction::ClipboardTransfer { cut: true, .. }]
        ));
        assert!(matches!(
            login
                .confirm_clipboard_cut(LeagueSignupField::Password, &layout, font)
                .as_slice(),
            [LeagueSignupAction::TextChanged { .. }]
        ));
        assert!(login.password().is_empty());

        login.set_focus(LeagueSignupControl::Account);
        login.handle_clipboard_shortcut(
            LeagueSignupEditClipboardShortcut::SelectAll,
            None,
            &layout,
            font,
        );
        login.handle_clipboard_shortcut(
            LeagueSignupEditClipboardShortcut::Paste,
            Some("raw|paste"),
            &layout,
            font,
        );
        assert_eq!(login.account(), "raw\u{a6}paste");
        login.set_focus(LeagueSignupControl::Password);
        login.handle_pointer_middle_down(left, Some("|primary"), &layout, font);
        assert!(login.account().contains("|primary"));
        assert_eq!(
            login.focused_control(),
            Some(LeagueSignupControl::Password),
            "native MiddleDown edits without transferring focus"
        );

        login.set_focus(LeagueSignupControl::Account);
        login.handle_clipboard_shortcut(
            LeagueSignupEditClipboardShortcut::SelectAll,
            None,
            &layout,
            font,
        );
        let context = login.request_context_menu_at(left, true, &layout);
        assert!(matches!(
            context.as_slice(),
            [LeagueSignupAction::OpenEditContextMenu(request)]
                if request.field == LeagueSignupField::Account
                    && request.items.iter().any(|item| item.command == LeagueSignupEditContextCommand::Cut)
                    && request.items.iter().any(|item| item.command == LeagueSignupEditContextCommand::Paste)
        ));

        login.set_account("account");
        login.set_password("old");
        login.set_focus(LeagueSignupControl::Password);
        let pasted = login.handle_clipboard_shortcut(
            LeagueSignupEditClipboardShortcut::Paste,
            Some("new-password\nignored"),
            &layout,
            font,
        );
        assert!(pasted
            .iter()
            .any(|action| matches!(action, LeagueSignupAction::Submitted(_))));

        let mut movable = clonk_frontend::league_signup::LeagueSignupController::new(
            LeagueSignupConfig::new("Player", "league.example", LeagueSignupMode::Login),
            LeagueSignupStrings::default(),
        );
        let movable_layout = movable.layout(1280, 720, font);
        let caption_point = GuiPoint::new(
            (movable_layout.caption.x + 10) as f32,
            (movable_layout.caption.y + 10) as f32,
        );
        let moved_point = GuiPoint::new(caption_point.x + 17.0, caption_point.y - 9.0);
        movable.handle_pointer_down(caption_point, &movable_layout, font);
        movable.handle_pointer_move(moved_point, &movable_layout, font);
        movable.handle_pointer_up(moved_point, &movable_layout, font);
        assert_eq!(movable.dialog_offset(), (17, -9));
        movable.reset_location();
        assert_eq!(movable.dialog_offset(), (0, 0));

        let mut registration = clonk_frontend::league_signup::LeagueSignupController::new(
            LeagueSignupConfig::new(
                "Player",
                "league.example",
                LeagueSignupMode::Registration,
            ),
            LeagueSignupStrings::default(),
        );
        registration.set_password_enabled(true);
        registration.set_focus(LeagueSignupControl::Password);
        registration.set_password_enabled(false);
        assert_eq!(registration.focused_control(), None);
        assert!(matches!(
            registration.handle_key_down(KeyCode::Tab, false).as_slice(),
            [LeagueSignupAction::FocusChanged(LeagueSignupControl::Close)]
        ));

        let collapsed = registration.layout(1280, 720, font);
        let checkbox = collapsed.password_checkbox.as_ref().expect("checkbox");
        let checkbox_point = GuiPoint::new(
            (checkbox.square.x + checkbox.square.w / 2) as f32,
            (checkbox.square.y + checkbox.square.h / 2) as f32,
        );
        let ok_point = GuiPoint::new(
            (collapsed.ok_button.x + 2) as f32,
            (collapsed.ok_button.y + 2) as f32,
        );
        registration.handle_pointer_down(ok_point, &collapsed, font);
        assert!(matches!(
            registration
                .handle_pointer_up(checkbox_point, &collapsed, font)
                .as_slice(),
            [LeagueSignupAction::PasswordEnabledChanged(true)]
        ));
        assert_eq!(
            registration.take_sound_events(),
            vec![
                clonk_frontend::league_signup::LeagueSignupSound::ArrowHit,
                clonk_frontend::league_signup::LeagueSignupSound::ArrowHit,
                clonk_frontend::league_signup::LeagueSignupSound::ArrowHit,
            ],
            "pressed-button release and checkbox toggle each keep their native sound"
        );

        for key in [
            VirtualKeyCode::Return,
            VirtualKeyCode::NumpadEnter,
            VirtualKeyCode::Escape,
            VirtualKeyCode::Space,
        ] {
            assert!(league_signup_dialog_key_code(key, ModifiersState::CTRL).is_none());
            assert!(league_signup_dialog_key_code(key, ModifiersState::SHIFT).is_none());
        }
        assert_eq!(
            league_signup_dialog_key_code(VirtualKeyCode::Tab, ModifiersState::SHIFT),
            Some(KeyCode::Tab)
        );
        assert!(
            league_signup_dialog_key_code(VirtualKeyCode::Tab, ModifiersState::CTRL).is_none()
        );

        let first_press = Instant::now();
        let mut last_press = None;
        assert!(!classic_press_is_double_click(
            &mut last_press,
            first_press
        ));
        assert!(classic_press_is_double_click(
            &mut last_press,
            first_press + Duration::from_millis(399)
        ));
        assert!(last_press.is_none(), "native clears the double-click timer");
        assert!(!classic_press_is_double_click(
            &mut last_press,
            first_press + Duration::from_millis(800)
        ));
    }

    #[test]
    fn league_signup_headless_login_registration_and_abort_match_cpp_auth_flow() {
        use clonk_frontend::league_signup::{
            LeagueSignupControl, LeagueSignupField, LeagueSignupMode,
        };

        let mut app = new_classic_running_sandbox_app();
        // Keep the already-loaded exact GUI bundle while making credentials,
        // auto-login and the registration Nick preference deterministic.
        app.app_paths = None;
        app.network_is_league = true;
        let pending_player = || clonk_engine::ControlPlayerInfoEntry {
            name: LegacyCString::from_bytes(b"Exact Player".to_vec()).unwrap(),
            forced_name: LegacyCString::from_bytes(b"Forced Player".to_vec()).unwrap(),
            ..Default::default()
        };
        let pending_request = || clonk_network::PlayerInfoUpdateRequest {
            client_id: 7,
            flags: clonk_engine::CLIENT_PLAYER_INFO_FLAG_INITIAL,
            players: vec![pending_player()],
        };
        let continuation = |request| LeaguePlayerAuthContinuation::InitialClient {
            request,
            index: 0,
            server_name: "league.example".to_string(),
        };

        // Empty LeaguePassword returns to the event loop with the login form
        // installed. Since no observer is servicing the command channel yet,
        // reaching this assertion also proves no Auth request was submitted.
        let (manager, _event_tx, commands) =
            NetworkManager::test_stub_with_league_commands_for_client_id(7);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11_112)),
            "Client",
        )));
        app.league_auth_session = Some(clonk_network::LeagueAuthRequestHead::default());
        assert_eq!(
            app.continue_league_player_auth(continuation(pending_request()))
                .expect("open missing-password login"),
            LeaguePlayerAuthStatus::Pending
        );
        let login = &app
            .league_signup_dialog
            .as_ref()
            .expect("login dialog")
            .controller;
        assert_eq!(login.mode(), LeagueSignupMode::Login);
        assert_eq!(login.focused_control(), Some(LeagueSignupControl::Password));
        assert!(login.field_visible(LeagueSignupField::Account));
        assert!(login.field_visible(LeagueSignupField::Password));
        assert!(!login.field_visible(LeagueSignupField::PasswordConfirmation));

        let invalid = app
            .league_signup_dialog
            .as_mut()
            .expect("login dialog")
            .controller
            .submit();
        app.process_league_signup_actions(vec![invalid])
            .expect("show validation modal");
        let validation = app.message_dialogs.last().expect("validation modal");
        assert_eq!(validation.state.caption(), "Invalid Entry");
        assert_eq!(
            validation.state.icon(),
            clonk_frontend::message_dialog::MessageDialogIcon::ERROR
        );
        assert_eq!(
            app.league_signup_dialog
                .as_ref()
                .expect("login remains open")
                .controller
                .focused_control(),
            Some(LeagueSignupControl::Account)
        );
        app.finish_message_dialog_at(
            app.message_dialogs.len() - 1,
            clonk_frontend::message_dialog::MessageDialogResult::Ok,
        )
        .expect("dismiss validation modal");

        let observer = thread::spawn(move || {
            commands.complete_initial_league_client_join(
                Vec::new(),
                vec![clonk_network::decode_league_auth_response(
                    b"[Response]\r\nStatus=Success\r\nAUID=login-token\r\n",
                )],
            )
        });
        let submission = {
            let login = &mut app
                .league_signup_dialog
                .as_mut()
                .expect("login dialog")
                .controller;
            login.set_account("account");
            login.set_password("password");
            login.submit()
        };
        app.process_league_signup_actions(vec![submission])
            .expect("submit login form");
        poll_league_auth_until(&mut app, "login completion", |app| {
            app.pending_league_player_auth.is_none()
        });
        let (order, auth_heads, _, requests) = observer.join().expect("login observer");
        assert_eq!(order, vec!["auth", "player-info"]);
        assert_eq!(auth_heads.len(), 1);
        assert_eq!(auth_heads[0].account.as_bytes(), b"account");
        assert_eq!(auth_heads[0].password.as_bytes(), b"password");
        assert!(auth_heads[0].new_account.is_empty());
        assert!(auth_heads[0].new_password.is_empty());
        assert_eq!(requests[0].players[0].auth_id.as_bytes(), b"login-token");

        // A server refusal is not a failed player join. Native shows the
        // league error first, clears only the process password when that
        // modal closes, and retries the same player with an empty login edit.
        let failed_auth = clonk_network::LeagueAuthRequestHead {
            account: LegacyCString::from_bytes(b"account".to_vec()).unwrap(),
            password: LegacyCString::from_bytes(b"outdated".to_vec()).unwrap(),
            ..Default::default()
        };
        let (manager, _event_tx, commands) =
            NetworkManager::test_stub_with_league_commands_for_client_id(7);
        app.network = Some(manager);
        app.league_auth_session = Some(failed_auth.clone());
        let observer = thread::spawn(move || {
            commands.complete_initial_league_client_join(
                Vec::new(),
                vec![
                    clonk_network::decode_league_auth_response(
                        b"[Response]\r\nStatus=Failure\r\nMessage=Invalid password\r\n",
                    ),
                    clonk_network::decode_league_auth_response(
                        b"[Response]\r\nStatus=Success\r\nAUID=retry-token\r\n",
                    ),
                ],
            )
        });
        assert_eq!(
            app.continue_league_player_auth(continuation(pending_request()))
                .expect("show failed-auth message"),
            LeaguePlayerAuthStatus::Pending
        );
        poll_league_auth_until(&mut app, "failed-auth message", |app| {
            matches!(
                app.message_dialogs.last().map(|dialog| &dialog.continuation),
                Some(MessageDialogContinuation::LeaguePlayerAuthError)
            )
        });
        assert!(app.league_signup_dialog.is_none());
        let failure = app.message_dialogs.last().expect("failed-auth message");
        assert_eq!(failure.state.caption(), "League Login Failed");
        assert_eq!(failure.state.message(), "League server reply: Invalid password");
        assert_eq!(
            app.league_auth_session
                .as_ref()
                .expect("credentials remain while message is modal")
                .password
                .as_bytes(),
            b"outdated"
        );
        app.finish_message_dialog_at(
            app.message_dialogs.len() - 1,
            clonk_frontend::message_dialog::MessageDialogResult::Ok,
        )
        .expect("dismiss failed-auth message");
        let retry = &app
            .league_signup_dialog
            .as_ref()
            .expect("login retry")
            .controller;
        assert_eq!(retry.mode(), LeagueSignupMode::Login);
        assert_eq!(retry.account(), "account");
        assert!(retry.password().is_empty());
        assert!(app
            .league_auth_session
            .as_ref()
            .expect("session credentials")
            .password
            .is_empty());
        let retry_submission = {
            let retry = &mut app
                .league_signup_dialog
                .as_mut()
                .expect("login retry")
                .controller;
            retry.set_password("replacement");
            retry.submit()
        };
        app.process_league_signup_actions(vec![retry_submission])
            .expect("submit login retry");
        poll_league_auth_until(&mut app, "login retry completion", |app| {
            app.pending_league_player_auth.is_none()
        });
        let (order, auth_heads, _, requests) = observer.join().expect("retry observer");
        assert_eq!(order, vec!["auth", "auth", "player-info"]);
        assert_eq!(auth_heads[0], failed_auth);
        assert_eq!(auth_heads[1].password.as_bytes(), b"replacement");
        assert_eq!(requests[0].players[0].auth_id.as_bytes(), b"retry-token");

        // Abort always closes without validation. Native shows its Notify
        // modal before returning failure to the outer swap-remove loop; only
        // after that modal closes is the empty initial PlayerInfo submitted.
        let (manager, _event_tx, commands) =
            NetworkManager::test_stub_with_league_commands_for_client_id(7);
        app.network = Some(manager);
        app.league_auth_session = Some(clonk_network::LeagueAuthRequestHead::default());
        assert_eq!(
            app.continue_league_player_auth(continuation(pending_request()))
                .expect("open cancellable login"),
            LeaguePlayerAuthStatus::Pending
        );
        let abort = app
            .league_signup_dialog
            .as_mut()
            .expect("cancellable login")
            .controller
            .abort();
        app.process_league_signup_actions(vec![abort])
            .expect("abort login form");
        assert!(app.league_signup_dialog.is_none());
        assert_eq!(
            app.message_dialogs.last().map(|dialog| dialog.state.icon()),
            Some(clonk_frontend::message_dialog::MessageDialogIcon::NOTIFY)
        );
        let observer = thread::spawn(move || {
            commands.complete_initial_league_client_join(Vec::new(), Vec::new())
        });
        app.finish_message_dialog_at(
            app.message_dialogs.len() - 1,
            clonk_frontend::message_dialog::MessageDialogResult::Ok,
        )
        .expect("dismiss cancellation notice");
        let (order, auth_heads, _, requests) = observer.join().expect("abort observer");
        assert_eq!(order, vec!["player-info"]);
        assert!(auth_heads.is_empty());
        assert!(requests[0].players.is_empty());

        // A Register response, not an empty stored account, selects the
        // registration form. With its optional password unchecked, native
        // sends the old login password as NewPassword.
        let old_auth = clonk_network::LeagueAuthRequestHead {
            account: LegacyCString::from_bytes(b"old-account".to_vec()).unwrap(),
            password: LegacyCString::from_bytes(b"old-password".to_vec()).unwrap(),
            ..Default::default()
        };
        let (manager, _event_tx, commands) =
            NetworkManager::test_stub_with_league_commands_for_client_id(7);
        app.network = Some(manager);
        app.league_auth_session = Some(old_auth.clone());
        let observer = thread::spawn(move || {
            commands.complete_initial_league_client_join(
                Vec::new(),
                vec![
                    clonk_network::decode_league_auth_response(
                        b"[Response]\r\nStatus=Register\r\nAccount=master-account\r\n",
                    ),
                    clonk_network::decode_league_auth_response(
                        b"[Response]\r\nStatus=Success\r\nAUID=\r\nAccount=retry-master\r\n",
                    ),
                    clonk_network::decode_league_auth_response(
                        b"[Response]\r\nStatus=Success\r\nAUID=registered-token\r\n",
                    ),
                ],
            )
        });
        assert_eq!(
            app.continue_league_player_auth(continuation(pending_request()))
                .expect("receive Register response"),
            LeaguePlayerAuthStatus::Pending
        );
        poll_league_auth_until(&mut app, "registration form", |app| {
            app.league_signup_dialog.as_ref().is_some_and(|dialog| {
                dialog.controller.mode() == LeagueSignupMode::Registration
            })
        });
        let registration = &app
            .league_signup_dialog
            .as_ref()
            .expect("registration dialog")
            .controller;
        assert_eq!(registration.mode(), LeagueSignupMode::Registration);
        assert_eq!(registration.account(), "Forced Player");
        assert_eq!(
            registration.focused_control(),
            Some(LeagueSignupControl::Account)
        );
        assert!(!registration.password_enabled());
        assert!(!registration.field_visible(LeagueSignupField::Password));
        let submission = {
            let registration = &mut app
                .league_signup_dialog
                .as_mut()
                .expect("registration dialog")
                .controller;
            registration.set_account("New User");
            registration.submit()
        };
        app.process_league_signup_actions(vec![submission])
            .expect("submit registration form");
        poll_league_auth_until(&mut app, "registration failure", |app| {
            matches!(
                app.message_dialogs.last().map(|dialog| &dialog.continuation),
                Some(MessageDialogContinuation::LeaguePlayerAuthError)
            )
        });
        assert!(app.league_signup_dialog.is_none());
        let failure = app
            .message_dialogs
            .last()
            .expect("missing-AUID registration failure");
        assert_eq!(failure.state.caption(), "League Login Failed");
        assert_eq!(
            failure.state.message(),
            "League server reply: League server reply without authentication-id!"
        );
        app.finish_message_dialog_at(
            app.message_dialogs.len() - 1,
            clonk_frontend::message_dialog::MessageDialogResult::Ok,
        )
        .expect("dismiss registration failure");
        assert!(app
            .league_auth_session
            .as_ref()
            .expect("session credentials")
            .password
            .is_empty());
        let retry_submission = {
            let registration = &mut app
                .league_signup_dialog
                .as_mut()
                .expect("registration retry")
                .controller;
            assert_eq!(registration.mode(), LeagueSignupMode::Registration);
            assert_eq!(registration.account(), "Forced Player");
            assert!(!registration.password_enabled());
            registration.set_account("Retry User");
            registration.submit()
        };
        app.process_league_signup_actions(vec![retry_submission])
            .expect("submit registration retry");
        poll_league_auth_until(&mut app, "registration retry completion", |app| {
            app.pending_league_player_auth.is_none()
        });
        let (order, auth_heads, _, requests) = observer.join().expect("registration observer");
        assert_eq!(order, vec!["auth", "auth", "auth", "player-info"]);
        assert_eq!(auth_heads[0], old_auth);
        assert_eq!(auth_heads[1].account.as_bytes(), b"master-account");
        assert_eq!(auth_heads[1].password.as_bytes(), b"old-password");
        assert_eq!(auth_heads[1].new_account.as_bytes(), b"New User");
        assert_eq!(auth_heads[1].new_password.as_bytes(), b"old-password");
        assert_eq!(auth_heads[2].account.as_bytes(), b"retry-master");
        assert_eq!(auth_heads[2].password.as_bytes(), b"old-password");
        assert_eq!(auth_heads[2].new_account.as_bytes(), b"Retry User");
        assert_eq!(auth_heads[2].new_password.as_bytes(), b"old-password");
        assert_eq!(
            requests[0].players[0].auth_id.as_bytes(),
            b"registered-token"
        );

        // C4Network2Players::JoinLocalPlayer routes later lobby additions
        // through the same modal before its CIF_AddPlayers request. Resuming
        // must not republish the already-materialized player resource.
        let local_add = || LeaguePlayerAuthContinuation::RuntimePlayer {
            request: clonk_network::PlayerInfoUpdateRequest {
                client_id: 7,
                flags: clonk_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS,
                players: vec![pending_player()],
            },
            index: 0,
            server_name: "league.example".to_string(),
            host: false,
            alternate_resource_id: 41,
            alternate_color: 0x0012_3456,
        };
        let (manager, _event_tx, commands) =
            NetworkManager::test_stub_with_league_commands_for_client_id(7);
        app.network = Some(manager);
        app.league_auth_session = Some(clonk_network::LeagueAuthRequestHead::default());
        assert_eq!(
            app.continue_league_player_auth(local_add())
                .expect("open local-add login"),
            LeaguePlayerAuthStatus::Pending
        );
        assert_eq!(
            app.league_signup_dialog
                .as_ref()
                .expect("local-add login")
                .controller
                .mode(),
            LeagueSignupMode::Login
        );
        let observer = thread::spawn(move || {
            commands.complete_initial_league_client_join(
                Vec::new(),
                vec![clonk_network::decode_league_auth_response(
                    b"[Response]\r\nStatus=Success\r\nAUID=local-token\r\n",
                )],
            )
        });
        let submission = {
            let login = &mut app
                .league_signup_dialog
                .as_mut()
                .expect("local-add login")
                .controller;
            login.set_account("account");
            login.set_password("password");
            login.submit()
        };
        app.process_league_signup_actions(vec![submission])
            .expect("submit local-add login");
        poll_league_auth_until(&mut app, "local-add completion", |app| {
            app.pending_league_player_auth.is_none()
        });
        let (order, _, _, requests) = observer.join().expect("local-add observer");
        assert_eq!(order, vec!["auth", "player-info"]);
        assert_eq!(requests.len(), 1);
        assert_eq!(
            requests[0].flags,
            clonk_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS
        );
        assert_eq!(requests[0].players[0].auth_id.as_bytes(), b"local-token");

        let (manager, _event_tx, mut commands) =
            NetworkManager::test_stub_with_league_commands_for_client_id(7);
        app.network = Some(manager);
        app.league_auth_session = Some(clonk_network::LeagueAuthRequestHead::default());
        assert_eq!(
            app.continue_league_player_auth(local_add())
                .expect("open cancellable local-add login"),
            LeaguePlayerAuthStatus::Pending
        );
        let abort = app
            .league_signup_dialog
            .as_mut()
            .expect("cancellable local-add login")
            .controller
            .abort();
        app.process_league_signup_actions(vec![abort])
            .expect("abort local-add login");
        app.finish_message_dialog_at(
            app.message_dialogs.len() - 1,
            clonk_frontend::message_dialog::MessageDialogResult::Ok,
        )
        .expect("dismiss local-add cancellation notice");
        assert!(
            commands.take_player_info_updates().is_empty(),
            "a cancelled local add must not submit an empty PlayerInfo packet"
        );

        // The staged host owns its manager inside the continuation while the
        // modal returns to the event loop. Accepted players are handed back to
        // startup without rerunning Auth during host finalization.
        let (manager, _event_tx, commands) =
            NetworkManager::test_stub_with_league_commands_for_client_id(0);
        app.network = None;
        app.network_mode = None;
        app.league_auth_session = Some(clonk_network::LeagueAuthRequestHead::default());
        let host_continuation = LeaguePlayerAuthContinuation::StartupHost {
            mode: NetworkMode::Host(HostSettings {
                bind_addr: SocketAddr::from(([127, 0, 0, 1], 0)),
                player_name: "Host".to_string(),
                prepared: None,
            }),
            manager,
            selected_scenario: None,
            purpose: StartupNetworkPurpose::StagedHost,
            players: vec![pending_player()],
            index: 0,
            server_name: "league.example".to_string(),
        };
        assert_eq!(
            app.continue_league_player_auth(host_continuation)
                .expect("open staged-host login"),
            LeaguePlayerAuthStatus::Pending
        );
        let observer = thread::spawn(move || {
            commands.complete_league_player_auths(vec![clonk_network::decode_league_auth_response(
                b"[Response]\r\nStatus=Success\r\nAUID=host-token\r\n",
            )])
        });
        let submission = {
            let login = &mut app
                .league_signup_dialog
                .as_mut()
                .expect("staged-host login")
                .controller;
            login.set_account("host-account");
            login.set_password("host-password");
            login.submit()
        };
        app.process_league_signup_actions(vec![submission])
            .expect("submit staged-host login");
        poll_league_auth_until(&mut app, "staged-host completion", |app| {
            app.startup_network_connection.is_some()
        });
        let (auth_heads, auth_players) = observer.join().expect("staged-host observer");
        assert_eq!(auth_heads.len(), 1);
        assert_eq!(auth_players.len(), 1);
        assert_eq!(auth_heads[0].account.as_bytes(), b"host-account");
        assert_eq!(auth_players[0].name.as_bytes(), b"Exact Player");
        assert_eq!(
            app.startup_network_connection
                .as_ref()
                .and_then(|connection| connection.authenticated_league_players.as_ref())
                .expect("authenticated staged-host players")[0]
                .auth_id
                .as_bytes(),
            b"host-token"
        );
        assert!(app.startup_network_connection.is_some());
    }

    #[test]
    fn startup_network_client_enters_and_acknowledges_lobby_when_boot_completes() {
        // A command-line direct join completes network initialization before
        // C4Game::Init enters C4Network2::DoLobby. DoLobby then marks the lobby
        // running so the initial GS_Lobby can be acknowledged
        // (src/C4Game.cpp:366-409; src/C4Network2.cpp:445-461,2017-2052).
        let _lock = env_lock().lock();
        let user_data = tempdir().expect("isolated client startup user data");
        let (_guard, paths) = exact_loader_test_paths(user_data.path(), None);
        let mut app = new_menu_app_with_paths(320, 200, &paths);
        let (manager, event_tx, mut commands) =
            NetworkManager::test_stub_with_commands_for_client_id(7);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11_112)),
            "Observer",
        )));
        app.network_lobby = Some(NetworkLobbyState::new(7, "Observer".to_string(), false));
        let host_config = clonk_network::HostConfig::default();
        let mut snapshot = host_config
            .initial_join_snapshot
            .expect("default host publishes JoinData");
        snapshot
            .parameters
            .clients
            .clients
            .push(clonk_engine::ClientCoreControlData {
                client_id: 7,
                observer: true,
                name: clonk_engine::LegacyCString::from_bytes(b"Observer".to_vec())
                    .expect("valid client name"),
                ..Default::default()
            });
        snapshot.parameters.clients.local_client_id = Some(7);
        event_tx
            .send(NetworkEvent::JoinData(clonk_network::JoinDataEnvelope {
                client_id: 7,
                start_control_tick: 23,
                status: host_config.initial_status,
                dynamic: snapshot.dynamic,
                parameters: snapshot.parameters,
            }))
            .expect("receive JoinData while startup assets still load");
        app.process_network_events()
            .expect("retain pre-lobby JoinData");
        assert!(commands.take_status_acknowledgements().is_empty());

        app.mode = AppMode::Loading;
        let (boot_tx, boot_rx) = mpsc::channel();
        app.boot_loading = Some(BootLoadingState::new(boot_rx));
        boot_tx
            .send(BootLoadingEvent::Finished(None))
            .expect("finish command-line client boot");

        app.poll_boot_loading();

        assert_eq!(app.startup_view, StartupView::NetworkLobby);
        assert!(app.network.is_some());
        assert!(app.network_lobby.is_some());
        assert_eq!(
            commands.take_framed_status_acknowledgements(),
            vec![(
                clonk_network::NetworkStatus {
                    target_tick: 23,
                    ..host_config.initial_status
                },
                0,
            )]
        );
    }

    #[test]
    fn client_lobby_acknowledges_join_status_at_the_initialized_control_tick_once() {
        // DoLobby marks GS_Lobby reached only after the lobby is running, then
        // rewrites the reference status target to the initialized ControlTick
        // and sends one PID_StatusAck after initial PlayerInfo submission
        // (src/C4Network2.cpp:445-461,2041-2058;
        // src/C4Network2Players.cpp:124-136).
        let mut app = new_menu_app(320, 200);
        let (manager, event_tx, mut commands) =
            NetworkManager::test_stub_with_commands_for_client_id(7);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11_112)),
            "Observer",
        )));
        app.network_lobby = Some(NetworkLobbyState::new(7, "Observer".to_string(), false));
        app.startup_view = StartupView::NetworkLobby;
        app.selected_player_file = None;
        for _ in 0..3 {
            app.engine.tick().expect("advance C++ frame counter");
        }

        let host_config = clonk_network::HostConfig::default();
        let mut reference_status = host_config.initial_status;
        reference_status.target_tick = -1;
        let mut snapshot = host_config
            .initial_join_snapshot
            .expect("default host publishes JoinData");
        snapshot
            .parameters
            .clients
            .clients
            .push(clonk_engine::ClientCoreControlData {
                client_id: 7,
                name: clonk_engine::LegacyCString::from_bytes(b"Observer".to_vec())
                    .expect("valid client name"),
                ..Default::default()
            });
        snapshot.parameters.clients.local_client_id = Some(7);
        let join_data = clonk_network::JoinDataEnvelope {
            client_id: 7,
            start_control_tick: 23,
            status: reference_status,
            dynamic: snapshot.dynamic,
            parameters: snapshot.parameters,
        };
        event_tx
            .send(NetworkEvent::JoinData(join_data))
            .expect("queue JoinData");

        app.process_network_events().expect("enter network lobby");

        assert_eq!(
            app.network_control_clock
                .map(NetworkControlClock::current_tick),
            Some(23),
            "PID_StatusAck uses Game.Control.ControlTick"
        );
        assert_eq!(
            app.engine.frame(),
            3,
            "the distinct Game.FrameCounter is reserved for ClientActReq"
        );

        assert_eq!(
            commands.take_framed_status_acknowledgements(),
            vec![(
                clonk_network::NetworkStatus {
                    target_tick: 23,
                    ..reference_status
                },
                3,
            )]
        );
        app.process_network_events()
            .expect("poll empty event queue");
        assert!(commands.take_status_acknowledgements().is_empty());
    }

    #[test]
    fn l021_client_go_combines_scenario_once_and_defers_100_until_final_init() {
        // RetrieveScenario waits for Parameters.Scenario and ResDynamic, merges
        // them into Combined<client>.c4s, then waits for ordinary GameRes files.
        // It does not acknowledge GO until InitGame reaches FinalInit
        // (pristine 9ffa0a5d src/C4Network2.cpp:619-671;
        // src/C4Game.cpp:2526-2556,455-482).
        let directory = tempdir().expect("network resource directory");
        let scenario_path = directory.path().join("Scenario.c4s");
        let dynamic_path = directory.path().join("Dynamic.c4s");
        let game_resource_path = directory.path().join("Objects.c4d");
        let material_resource_path = directory.path().join("HostMaterials.c4g");
        let local_material_fallback_path = directory.path().join("Material.c4g");
        let mut scenario_group = clonk_resources::MutableGroup::new("Scenario.c4s");
        scenario_group
            .add_file(
                "Scenario.txt",
                b"[Head]\nTitle=Client start\nNetworkGame=1\nNoInitialize=1\n\n[Definitions]\nDefinition1=MissingLocal.c4d\n"
                    .to_vec(),
            )
            .expect("add scenario core");
        fs::write(
            &scenario_path,
            scenario_group.pack().expect("pack scenario"),
        )
        .expect("write scenario resource");
        let mut dynamic_group = clonk_resources::MutableGroup::new("Dynamic.c4s");
        dynamic_group
            .add_file("Dynamic.txt", b"merged".to_vec())
            .expect("add dynamic marker");
        fs::write(&dynamic_path, dynamic_group.pack().expect("pack dynamic"))
            .expect("write dynamic resource");
        let mut game_resource = clonk_resources::MutableGroup::new("Objects.c4d");
        let mut host_definition = clonk_resources::MutableGroup::new("Host.c4d");
        host_definition
            .add_file(
                "DefCore.txt",
                b"[DefCore]\nid=HOST\nName=Host\nCategory=1\n".to_vec(),
            )
            .expect("add host definition core");
        host_definition
            .add_file(
                "Graphics.png",
                include_bytes!("../../../../content/Material.c4g/Snow.png").to_vec(),
            )
            .expect("add host definition graphics");
        game_resource
            .add_child("Host.c4d", host_definition)
            .expect("add host definition");
        fs::write(
            &game_resource_path,
            game_resource.pack().expect("pack game resource"),
        )
        .expect("write game resource");
        let mut host_materials = clonk_resources::MutableGroup::new("HostMaterials.c4g");
        host_materials
            .add_file(
                "TexMap.txt",
                b"OverloadMaterials\nOverloadTextures\n1=NetworkOnly-HostTexture\n".to_vec(),
            )
            .expect("add host texture map");
        host_materials
            .add_file(
                "NetworkOnly.c4m",
                b"[Material]\nName=NetworkOnly\nColorX=11,12,13,14,15,16,17,18,19\nDensity=50\nTextureOverlay=HostTexture\n"
                    .to_vec(),
            )
            .expect("add host material");
        host_materials
            .add_file(
                "HostTexture.png",
                include_bytes!("../../../../content/Material.c4g/Snow.png").to_vec(),
            )
            .expect("add host texture");
        fs::write(
            &material_resource_path,
            host_materials.pack().expect("pack host materials"),
        )
        .expect("write host material resource");
        let mut local_material_fallback = clonk_resources::MutableGroup::new("Material.c4g");
        local_material_fallback
            .add_file("TexMap.txt", b"1=NetworkOnly-FallbackTexture\n".to_vec())
            .expect("add fallback texture map");
        local_material_fallback
            .add_file(
                "NetworkOnly.c4m",
                b"[Material]\nName=NetworkOnly\nColorX=201,202,203\nDensity=100\nTextureOverlay=FallbackTexture\n"
                    .to_vec(),
            )
            .expect("add conflicting fallback material");
        local_material_fallback
            .add_file(
                "FallbackOnly.c4m",
                b"[Material]\nName=FallbackOnly\nDensity=100\n".to_vec(),
            )
            .expect("add fallback-only material");
        local_material_fallback
            .add_file(
                "FallbackTexture.png",
                include_bytes!("../../../../content/Material.c4g/Snow.png").to_vec(),
            )
            .expect("add fallback texture");
        fs::write(
            &local_material_fallback_path,
            local_material_fallback
                .pack()
                .expect("pack fallback materials"),
        )
        .expect("write local material fallback");

        let mut app = new_menu_app(320, 200);
        app.loader_screen = Some(
            LoaderScreen::new(
                LoaderSelection::startup("Loader.png").expect("synthetic loader selection"),
                ImageData::new(1, 1, vec![0, 0, 0, 0xff]),
                app.assets
                    .loader_resources()
                    .expect("synthetic loader resources"),
                LoaderState::initial("Client start"),
            )
            .expect("synthetic client loader"),
        );
        let (manager, event_tx, mut commands) =
            NetworkManager::test_stub_with_commands_for_client_id(7);
        app.network = Some(manager);
        let mut settings =
            ClientSettings::new(SocketAddr::from(([127, 0, 0, 1], 11_112)), "Observer");
        settings.resource_directory = directory.path().to_path_buf();
        app.network_mode = Some(NetworkMode::Client(settings));
        let resource = |id, name: &[u8]| clonk_engine::NetworkResourceCore {
            id,
            loadable: true,
            filename: clonk_engine::LegacyCString::from_bytes(name.to_vec())
                .expect("fixture filename is NUL-free"),
            ..Default::default()
        };
        let host_config = clonk_network::HostConfig::default();
        let mut snapshot = host_config
            .initial_join_snapshot
            .expect("default host publishes JoinData");
        let network_random_seed = 7_i32;
        snapshot.parameters.random_seed = network_random_seed;
        snapshot.parameters.control_rate = 2;
        snapshot.parameters.scenario = resource(70, b"Scenario.c4s");
        snapshot.dynamic = resource(71, b"Dynamic.c4s");
        let mut definitions = resource(72, b"Objects.c4d");
        definitions.resource_type = clonk_network::HostResourceType::Definitions as u8;
        let mut materials = resource(73, b"HostMaterials.c4g");
        materials.resource_type = clonk_network::HostResourceType::Material as u8;
        snapshot.parameters.game_resources = vec![definitions, materials];
        let mut reference_status = host_config.initial_status;
        reference_status.target_tick = -1;
        let join_data = clonk_network::JoinDataEnvelope {
            client_id: 7,
            start_control_tick: 23,
            status: reference_status,
            dynamic: snapshot.dynamic.clone(),
            parameters: snapshot.parameters,
        };
        let go = clonk_network::NetworkStatus {
            state: clonk_network::NETWORK_STATE_GO,
            control_mode: 2,
            target_tick: 23,
        };
        event_tx
            .send(NetworkEvent::JoinData(join_data.clone()))
            .expect("queue JoinData");
        event_tx
            .send(NetworkEvent::StatusRequested(go))
            .expect("queue GO request");
        app.process_network_events().expect("apply start request");
        assert_eq!(
            app.blocking_resource_wait
                .as_ref()
                .map(|wait| (wait.scope, wait.resource_id)),
            Some((BlockingResourceScope::ClientStart, 70))
        );
        assert_eq!(
            app.message_dialogs
                .iter()
                .find(|dialog| matches!(
                    dialog.continuation,
                    MessageDialogContinuation::BlockingResourceWait { .. }
                ))
                .and_then(|dialog| dialog.state.progress()),
            Some(0)
        );

        let combined_path = directory.path().join("Combined7.c4s");
        assert!(!combined_path.exists());
        event_tx
            .send(NetworkEvent::ResourceComplete {
                resource_id: 70,
                core: join_data.parameters.scenario.clone(),
                path: scenario_path,
                local: false,
            })
            .expect("complete scenario");
        app.process_network_events().expect("wait for dynamic");
        assert!(!combined_path.exists());
        assert_eq!(
            app.blocking_resource_wait
                .as_ref()
                .map(|wait| wait.resource_id),
            Some(71)
        );
        assert_eq!(commands.take_player_info_updates().len(), 1);
        let (removed_tx, removed_rx) = mpsc::channel();
        let removal_observer = thread::spawn(move || {
            let (resource_id, completion) = commands.receive_resource_removal();
            completion.send(Ok(())).expect("complete dynamic removal");
            removed_tx
                .send(resource_id)
                .expect("report removed dynamic");
            commands
        });
        event_tx
            .send(NetworkEvent::ResourceComplete {
                resource_id: 71,
                core: join_data.dynamic.clone(),
                path: dynamic_path.clone(),
                local: false,
            })
            .expect("complete dynamic");
        app.process_network_events().expect("compose resources");
        assert_eq!(
            removed_rx
                .recv_timeout(Duration::from_secs(1))
                .expect("client did not retire its merged dynamic resource"),
            71
        );
        let mut commands = removal_observer.join().expect("removal observer exits");
        assert_eq!(
            app.blocking_resource_wait
                .as_ref()
                .map(|wait| wait.resource_id),
            Some(72)
        );

        let combined = Group::open(&combined_path).expect("open combined scenario");
        assert_eq!(combined.read_file("Dynamic.txt").unwrap(), b"merged");
        assert!(commands.take_status_acknowledgements().is_empty());

        event_tx
            .send(NetworkEvent::ResourceComplete {
                resource_id: 71,
                core: join_data.dynamic,
                path: dynamic_path,
                local: false,
            })
            .expect("repeat dynamic completion");
        event_tx
            .send(NetworkEvent::StatusRequested(go))
            .expect("repeat GO request");
        app.process_network_events().expect("ignore duplicate work");
        let combined_files = fs::read_dir(directory.path())
            .expect("read resource directory")
            .filter_map(Result::ok)
            .filter(|entry| entry.file_name().to_string_lossy().starts_with("Combined7"))
            .count();
        assert_eq!(combined_files, 1);

        event_tx
            .send(NetworkEvent::ResourceComplete {
                resource_id: 72,
                core: join_data.parameters.game_resources[0].clone(),
                path: game_resource_path,
                local: false,
            })
            .expect("complete ordinary game resource");
        event_tx
            .send(NetworkEvent::ResourceComplete {
                resource_id: 73,
                core: join_data.parameters.game_resources[1].clone(),
                path: material_resource_path,
                local: false,
            })
            .expect("complete authoritative material resource");
        app.process_network_events()
            .expect("begin client InitGame after all resources complete");
        assert!(app.blocking_resource_wait.is_none());
        assert!(!app.message_dialogs.iter().any(|dialog| matches!(
            dialog.continuation,
            MessageDialogContinuation::BlockingResourceWait { .. }
        )));
        assert!(matches!(app.mode, AppMode::Loading));
        app.poll_loading().expect("finish client InitGame phase");
        assert!(matches!(app.mode, AppMode::Loading));
        assert!(
            app.loader_screen
                .as_ref()
                .expect("client loader retained through GO wait")
                .state()
                .progress()
                < 100
        );
        assert!(app.network_start_wait.is_none());
        let client_wait = app
            .message_dialogs
            .iter()
            .find(|dialog| {
                matches!(
                    dialog.continuation,
                    MessageDialogContinuation::NetworkClientStartWait
                )
            })
            .expect("FinalInit presents the client start-wait message");
        assert_eq!(client_wait.state.message(), "Waiting for start...");
        assert_eq!(client_wait.state.caption(), "Network");
        assert_eq!(
            client_wait.state.buttons(),
            clonk_frontend::message_dialog::MessageDialogButtons::CANCEL
        );
        assert_eq!(client_wait.state.focused_button(), None);
        assert!(app.engine.snapshot().players.is_empty());
        assert!(app.engine.definition_ids().any(|id| id == "HOST"));
        // InitClient copies JoinData's start tick and control rate before
        // InitGame, so the engine-side SyncCheck clock must agree with the
        // network gate immediately after loading (src/C4Network2.cpp:1607-1609;
        // src/C4GameControl.cpp:61-68).
        assert_eq!(
            (
                app.engine.sync_check(7).control_tick,
                app.engine.control_rate
            ),
            (23, 2)
        );
        // C4Game opens the combined scenario's Material.c4g first and then the
        // host-ordered NRT_Material files. A client never re-resolves those
        // external files from its local installation, even when the last host
        // file requests both overload chains to continue (pristine 9ffa0a5d
        // src/C4Game.cpp:882-952; src/C4GameParameters.cpp:73-80,255-270).
        assert_eq!(
            app.material_render_info.get("networkonly"),
            Some(&clonk_frontend::MaterialRenderInfo::new(
                [11, 12, 13, 14, 15, 16, 17, 18, 19],
                [0; 6],
                Some("HostTexture".to_string()),
                0,
                50,
            )
            .with_placement(70)),
        );
        assert!(app.material_texture_images.contains_key("hosttexture"));
        assert!(!app.material_render_info.contains_key("fallbackonly"));
        assert!(!app.material_texture_images.contains_key("fallbacktexture"));
        assert_eq!(
            app.engine.random_seed(),
            u64::from(network_random_seed as u32),
            "JoinData remains authoritative over offline seed selection",
        );
        // C4Game::InitGameSecondPart fixes the synchronized RNG from
        // Parameters.RandomSeed before the landscape/weather initialization
        // draws (pristine 9ffa0a5d src/C4Game.cpp:2617-2632;
        // src/C4GameParameters.h:132). This fixture uses the stock C4SVal
        // ranges: Gravity, Season, YearSpeed, Climate, then Wind.
        let mut expected_rng =
            clonk_engine::LcgRng::seed_from_u64(u64::from(network_random_seed as u32));
        for range in [1, 101, 1, 21] {
            expected_rng.random(range);
        }
        let expected_wind = expected_rng.random(141) - 70;
        assert_eq!(
            app.engine.environment().wind,
            expected_wind,
            "client InitGame must use JoinData Parameters.RandomSeed before Weather.Init"
        );
        assert_eq!(
            commands.take_framed_status_acknowledgements(),
            vec![(go, 0)]
        );

        let host_commit = clonk_network::NetworkStatus {
            control_mode: 9,
            ..go
        };
        event_tx
            .send(NetworkEvent::StatusCommitted(host_commit))
            .expect("commit matching state and target");
        app.process_network_events()
            .expect("complete client Network.FinalInit");
        assert!(matches!(app.mode, AppMode::Running));
        assert_eq!(
            app.loader_screen
                .as_ref()
                .expect("client loader retained after final init")
                .state()
                .progress(),
            100
        );
        assert!(app.loading_state.is_none());
        assert!(app.network_control_running);
        assert!(app.message_dialogs.iter().all(|dialog| !matches!(
            dialog.continuation,
            MessageDialogContinuation::NetworkClientStartWait
        )));
    }

    #[test]
    fn client_rejects_a_combined_scenario_without_network_game_flag() {
        // After RetrieveScenario and RetrieveFiles, C4Game aborts before
        // InitScriptEngine when the combined C4S Head.NetworkGame flag is false
        // (pristine 9ffa0a5d src/C4Game.cpp:2526-2564).
        let directory = tempdir().expect("scenario directory");
        let scenario_path = directory.path().join("Combined7.c4s");
        let definition_path = scenario_path.join("Defs.c4d");
        fs::create_dir_all(&definition_path).expect("create definition");
        fs::write(
            scenario_path.join("Scenario.txt"),
            "[Head]\nTitle=Offline payload\nNetworkGame=false\n\n[Definitions]\nDefinition1=Defs.c4d\n",
        )
        .expect("write scenario core");
        fs::write(
            definition_path.join("DefCore.txt"),
            "[DefCore]\nid=TEST\nName=Test\nCategory=1\n",
        )
        .expect("write definition core");
        write_test_definition_graphics(&definition_path);
        let scenario =
            Scenario::load_from_path_with(&scenario_path, &InstallDefinitionResolver::new(None))
                .expect("offline-marked scenario parses");

        assert_eq!(
            validate_client_network_scenario(&scenario),
            Err("retrieved scenario is not marked as a network game".to_string())
        );
    }

    #[test]
    fn host_player_info_request_queues_authoritative_direct_broadcast() {
        // HandlePlayerInfoUpdRequest assigns IDs, then sends one host-authored
        // C4ControlPlayerInfo with CDT_Direct and executes that host-authored
        // control synchronously (src/C4Network2Players.cpp:160-239;
        // src/C4Control.cpp:1264-1282).
        let mut app = new_state_only_menu_app(320, 200);
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        event_tx
            .send(NetworkEvent::PlayerInfoUpdateRequest {
                origin: 9,
                request: clonk_network::PlayerInfoUpdateRequest {
                    client_id: 3,
                    flags: clonk_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS,
                    players: vec![clonk_engine::ControlPlayerInfoEntry {
                        id: 0,
                        ..Default::default()
                    }],
                },
                by_host: false,
            })
            .expect("queue PlayerInfo update request");

        app.process_network_events()
            .expect("process PlayerInfo update request");

        let broadcasts = commands.take_broadcast_player_infos();
        let [info] = broadcasts.as_slice() else {
            panic!("expected one authoritative PlayerInfo broadcast");
        };
        assert_eq!((info.client_id, info.by_client), (3, 0));
        let [player] = info.players.as_slice() else {
            panic!("expected one admitted player");
        };
        assert_eq!(player.id, 1);
        assert!(app.control_player_infos.get(1).is_some());
    }

    #[test]
    fn later_admission_reuses_shifted_initial_hosts_persisted_alternate_color() {
        // `ResolvePlayerAttributeConflicts` revisits every retained packet on
        // each admission. The synchronized row omits AlternateColorDw, but
        // the host's original C4PlayerInfo keeps it for the whole session
        // (src/C4PlayerInfo.cpp:82-90,177-230;
        // src/C4PlayerInfoConflicts.cpp:249-296).
        let legacy = |bytes: &[u8]| {
            clonk_engine::LegacyCString::from_bytes(bytes.to_vec()).expect("NUL-free fixture")
        };
        let resource = |id| clonk_engine::NetworkResourceCore {
            id,
            ..Default::default()
        };
        let mut app = new_state_only_menu_app(320, 200);
        app.network_max_players = 8;
        app.control_player_infos.replace_snapshot(
            2,
            [clonk_engine::PlayerInfoControlData {
                client_id: 0,
                flags: clonk_engine::CLIENT_PLAYER_INFO_FLAG_INITIAL,
                players: vec![
                    clonk_engine::ControlPlayerInfoEntry {
                        id: 1,
                        name: legacy(b"Blocker"),
                        flags: clonk_engine::PLAYER_INFO_FLAG_HAS_RESOURCE,
                        color: 0x00f4_0000,
                        original_color: 0x00f4_0000,
                        resource: Some(resource(11)),
                        ..Default::default()
                    },
                    clonk_engine::ControlPlayerInfoEntry {
                        id: 2,
                        name: legacy(b"Shifted host"),
                        flags: clonk_engine::PLAYER_INFO_FLAG_HAS_RESOURCE,
                        color: 0x0000_00e8,
                        original_color: 0x00f4_0000,
                        resource: Some(resource(22)),
                        ..Default::default()
                    },
                ],
                ..Default::default()
            }],
        );
        app.host_local_alternate_colors_by_resource = HashMap::from([(11, 0), (22, 0x0000_00e8)]);
        app.host_local_player_info_ids = HashSet::from([1, 2]);
        let aliased_remote = clonk_engine::ControlPlayerInfoEntry {
            id: 99,
            resource: Some(resource(22)),
            ..Default::default()
        };
        assert_eq!(
            host_runtime_alternate_color(
                &app.host_local_alternate_colors_by_resource,
                &app.host_local_player_info_ids,
                &aliased_remote,
            ),
            Some(0),
            "a remote row sharing the resource ID still has native's wire default"
        );
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        event_tx
            .send(NetworkEvent::PlayerInfoUpdateRequest {
                origin: 3,
                request: clonk_network::PlayerInfoUpdateRequest {
                    client_id: 3,
                    flags: clonk_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS,
                    players: vec![clonk_engine::ControlPlayerInfoEntry {
                        name: legacy(b"Later remote"),
                        color: 0x0000_c800,
                        original_color: 0x0000_c800,
                        ..Default::default()
                    }],
                },
                by_host: false,
            })
            .expect("queue later PlayerInfo request");

        app.process_network_events()
            .expect("persisted host alternate resolves the revisited packet");

        let broadcasts = commands.take_broadcast_player_infos();
        let [admitted] = broadcasts.as_slice() else {
            panic!("expected one admitted packet, got {broadcasts:?}");
        };
        assert_eq!(admitted.client_id, 3);
        assert_eq!(admitted.players[0].id, 3);
        assert_eq!(
            app.control_player_infos
                .get(2)
                .expect("shifted initial host remains retained")
                .color,
            0x0000_00e8
        );
    }

    #[test]
    fn league_lobby_checks_only_new_ids_removes_failures_and_consumes_successful_auid() {
        // HandlePlayerInfoUpdRequest resets gains after normalization, checks
        // only IDs absent from the retained list, removes rejected rows without
        // skipping the shifted successor, and clears a successful AUID before
        // SendUpdatedPlayers/CID_PlrInfo
        // (src/C4Network2Players.cpp:160-239).
        let legacy = |bytes: &[u8]| {
            clonk_engine::LegacyCString::from_bytes(bytes.to_vec()).expect("NUL-free fixture")
        };
        let mut app = new_menu_app(320, 200);
        app.network_is_league = true;
        app.network_league_name = b"Cup".to_vec();
        app.network_mode = Some(NetworkMode::Host(host_network_settings()));
        app.network_lobby = Some(NetworkLobbyState::new(0, "Host".to_string(), true));
        app.control_player_infos.replace_snapshot(
            1,
            [clonk_engine::PlayerInfoControlData {
                client_id: 3,
                players: vec![clonk_engine::ControlPlayerInfoEntry {
                    id: 1,
                    name: legacy(b"Existing"),
                    color: 0x0011_2233,
                    original_color: 0x0011_2233,
                    league_projected_gain: 6,
                    ..Default::default()
                }],
                ..Default::default()
            }],
        );
        let (manager, event_tx, commands) =
            NetworkManager::test_stub_with_league_commands_for_client_id(0);
        app.network = Some(manager);
        let responses = vec![
            clonk_network::decode_league_join_response(
                b"[Response]\r\nStatus=Failure\r\nMessage=Rejected\r\n",
            ),
            clonk_network::decode_league_join_response(
                b"[Response]\r\nStatus=Success\r\nAccount=Alice\r\nLeague=Cup\r\nScore=42\r\nRank=7\r\nRankSymbol=9\r\nProgressData=level3\r\nClanTag=TAG\r\n",
            ),
        ];
        let observer = thread::spawn(move || {
            commands.complete_host_league_player_checks(responses, 2)
        });
        event_tx
            .send(NetworkEvent::PlayerInfoUpdateRequest {
                origin: 3,
                request: clonk_network::PlayerInfoUpdateRequest {
                    client_id: 3,
                    flags: clonk_engine::CLIENT_PLAYER_INFO_FLAG_INITIAL,
                    players: vec![
                        clonk_engine::ControlPlayerInfoEntry {
                            id: 1,
                            name: legacy(b"Existing"),
                            color: 0x0011_2233,
                            original_color: 0x0011_2233,
                            league_projected_gain: 8,
                            ..Default::default()
                        },
                        clonk_engine::ControlPlayerInfoEntry {
                            name: legacy(b"Rejected"),
                            auth_id: legacy(b"reject-token"),
                            color: 0x0044_5566,
                            original_color: 0x0044_5566,
                            league_projected_gain: 9,
                            ..Default::default()
                        },
                        clonk_engine::ControlPlayerInfoEntry {
                            name: legacy(b"Accepted"),
                            auth_id: legacy(b"accept-token"),
                            color: 0x0077_8899,
                            original_color: 0x0077_8899,
                            league_projected_gain: 10,
                            ..Default::default()
                        },
                    ],
                },
                by_host: false,
            })
            .expect("queue league PlayerInfo request");

        app.process_network_events()
            .expect("process league PlayerInfo request");
        let (checked, broadcasts) = observer.join().expect("league check observer");

        let refusal = app
            .message_dialogs
            .last()
            .expect("league check refusal is shown");
        assert_eq!(
            refusal.state.message(),
            "League server has refused the join of player Rejected: Rejected"
        );
        assert_eq!(refusal.state.caption(), "Error");
        assert_eq!(
            refusal.state.icon(),
            clonk_frontend::message_dialog::MessageDialogIcon::ERROR
        );

        assert_eq!(
            checked
                .iter()
                .map(|player| (player.id, player.auth_id.as_bytes()))
                .collect::<Vec<_>>(),
            vec![(2, b"reject-token".as_slice()), (3, b"accept-token".as_slice())]
        );
        let [gain_reset, admitted, ..] = broadcasts.as_slice() else {
            panic!("expected gain reset before admitted PlayerInfo");
        };
        assert_eq!(gain_reset.client_id, 3);
        assert_eq!(gain_reset.players[0].league_projected_gain, -1);
        assert_eq!(
            admitted
                .players
                .iter()
                .map(|player| player.id)
                .collect::<Vec<_>>(),
            vec![1, 3]
        );
        assert!(admitted.players[0].auth_id.is_empty());
        assert_eq!(admitted.players[0].league_projected_gain, -1);
        let accepted = &admitted.players[1];
        assert!(accepted.auth_id.is_empty());
        assert_eq!(accepted.league_account.as_bytes(), b"Alice");
        assert_eq!(accepted.clan_tag.as_bytes(), b"TAG");
        assert_eq!(
            (
                accepted.league_score,
                accepted.league_rank,
                accepted.league_rank_symbol,
                accepted.league_progress_data.as_bytes(),
                accepted.league_projected_gain,
            ),
            (42, 7, 9, b"level3".as_slice(), -1)
        );
    }

    #[test]
    fn league_player_info_request_after_lobby_resets_stored_gains_but_is_not_admitted() {
        // The league branch returns when network state is no longer GS_Lobby.
        // ID allocation/normalization and the internal gain reset precede that
        // return, but neither auth checks nor direct broadcasts occur
        // (src/C4Network2Players.cpp:160-239).
        let mut app = new_state_only_running_sandbox_app();
        app.network_is_league = true;
        app.network_league_name = b"Cup".to_vec();
        app.network_mode = Some(NetworkMode::Host(host_network_settings()));
        app.control_player_infos.replace_snapshot(
            1,
            [clonk_engine::PlayerInfoControlData {
                client_id: 2,
                players: vec![clonk_engine::ControlPlayerInfoEntry {
                    id: 1,
                    league_projected_gain: 5,
                    ..Default::default()
                }],
                ..Default::default()
            }],
        );
        let (manager, event_tx, mut commands) =
            NetworkManager::test_stub_with_league_commands_for_client_id(0);
        app.network = Some(manager);
        event_tx
            .send(NetworkEvent::PlayerInfoUpdateRequest {
                origin: 3,
                request: clonk_network::PlayerInfoUpdateRequest {
                    client_id: 3,
                    flags: clonk_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS,
                    players: vec![clonk_engine::ControlPlayerInfoEntry {
                        auth_id: clonk_engine::LegacyCString::from_bytes(b"unchecked".to_vec())
                            .unwrap(),
                        ..Default::default()
                    }],
                },
                by_host: false,
            })
            .expect("queue post-lobby PlayerInfo request");

        app.process_network_events()
            .expect("reject post-lobby league request");

        assert_eq!(
            app.control_player_infos
                .get(1)
                .expect("retained player")
                .league_projected_gain,
            -1
        );
        assert!(app.control_player_infos.get(2).is_none());
        assert!(commands.take_broadcast_player_infos().is_empty());
    }

    #[test]
    fn host_player_info_conflict_update_precedes_admission_and_converges_join_data() {
        // ResolvePlayerAttributeConflicts may change an older, lower-priority
        // packet while admitting a higher-priority player. SendUpdatedPlayers
        // submits those retained packets before the new packet's CID_PlrInfo;
        // each direct control updates the live JoinData projection in the same
        // order (src/C4Network2Players.cpp:203-239;
        // src/C4PlayerInfoConflicts.cpp:193-344).
        let same_name =
            clonk_engine::LegacyCString::from_bytes(b"Same".to_vec()).expect("valid player name");
        let mut app = new_state_only_running_sandbox_app();
        app.control_player_infos.replace_snapshot(
            1,
            [clonk_engine::PlayerInfoControlData {
                client_id: 2,
                players: vec![clonk_engine::ControlPlayerInfoEntry {
                    id: 1,
                    name: same_name.clone(),
                    color: 0x00f4_0000,
                    original_color: 0x00f4_0000,
                    ..Default::default()
                }],
                ..Default::default()
            }],
        );
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(host_network_settings()));
        app.host_join_snapshot = clonk_network::HostConfig::default().initial_join_snapshot;
        event_tx
            .send(NetworkEvent::PlayerInfoUpdateRequest {
                origin: 3,
                request: clonk_network::PlayerInfoUpdateRequest {
                    client_id: 3,
                    flags: clonk_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS,
                    players: vec![clonk_engine::ControlPlayerInfoEntry {
                        name: same_name,
                        color: 0x0000_00f4,
                        original_color: 0x0000_00f4,
                        league_score: 10,
                        ..Default::default()
                    }],
                },
                by_host: false,
            })
            .expect("queue conflicting PlayerInfo update request");

        app.process_network_events()
            .expect("resolve conflicting PlayerInfo request");

        let (broadcasts, published) = commands.take_team_control_updates();
        let [updated_existing, admitted] = broadcasts.as_slice() else {
            panic!("expected existing update followed by admitted PlayerInfo");
        };
        assert_eq!((updated_existing.client_id, admitted.client_id), (2, 3));
        assert_eq!(
            updated_existing.players[0].forced_name.as_bytes(),
            b"Same (2)"
        );
        assert!(admitted.players[0].forced_name.is_empty());
        assert_eq!(admitted.players[0].id, 2);
        assert!(app.control_player_infos.get(2).is_some());

        for info in broadcasts.clone() {
            event_tx
                .send(NetworkEvent::PreexecutedPlayerInfoEcho {
                    join_players_on_echo: Vec::new(),
                    original: info.clone(),
                    info,
                })
                .expect("queue authoritative direct PlayerInfo");
        }
        app.process_network_events()
            .expect("apply ordered authoritative PlayerInfo controls");

        assert_eq!(
            app.control_player_infos
                .get(1)
                .expect("existing player remains retained")
                .forced_name
                .as_bytes(),
            b"Same (2)"
        );
        assert_eq!(
            app.control_player_infos
                .get(2)
                .expect("new player control is applied")
                .name
                .as_bytes(),
            b"Same"
        );
        assert_eq!(published.len(), 2);
        let latest = published.last().expect("final JoinData is published");
        assert_eq!(latest.parameters.player_infos.last_player_id, 2);
        let existing = latest
            .parameters
            .player_infos
            .clients
            .iter()
            .find(|client| client.client_id == 2)
            .expect("existing client row is published");
        assert_eq!(existing.players[0].forced_name.as_bytes(), b"Same (2)");
        let admitted = latest
            .parameters
            .player_infos
            .clients
            .iter()
            .find(|client| client.client_id == 3)
            .expect("admitted client row is published");
        assert_eq!(admitted.players[0].id, 2);
        assert_eq!(published.last(), app.host_join_snapshot.as_ref());
    }

    #[test]
    fn updated_existing_echo_cannot_issue_new_admission_before_its_echo() {
        let same_name =
            clonk_engine::LegacyCString::from_bytes(b"Same".to_vec()).expect("valid player name");
        let resource = clonk_engine::NetworkResourceCore {
            resource_type: clonk_network::HostResourceType::Player as u8,
            id: 17,
            loadable: true,
            filename: clonk_engine::LegacyCString::from_bytes(b"New.c4p".to_vec()).unwrap(),
            ..Default::default()
        };
        let mut app = new_state_only_running_sandbox_app();
        app.control_clients.register(3, true, false);
        app.control_player_infos.replace_snapshot(
            1,
            [clonk_engine::PlayerInfoControlData {
                client_id: 3,
                players: vec![clonk_engine::ControlPlayerInfoEntry {
                    id: 1,
                    name: same_name.clone(),
                    color: 0x00f4_0000,
                    original_color: 0x00f4_0000,
                    ..Default::default()
                }],
                ..Default::default()
            }],
        );
        app.admission_resources.register_lobby_resource(&resource);
        app.admission_resources
            .mark_complete(resource.id, PathBuf::from("New.c4p"));
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(host_network_settings()));
        event_tx
            .send(NetworkEvent::PlayerInfoUpdateRequest {
                origin: 3,
                request: clonk_network::PlayerInfoUpdateRequest {
                    client_id: 3,
                    flags: clonk_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS,
                    players: vec![clonk_engine::ControlPlayerInfoEntry {
                        name: same_name,
                        color: 0x0000_00f4,
                        original_color: 0x0000_00f4,
                        league_score: 10,
                        resource: Some(resource),
                        ..Default::default()
                    }],
                },
                by_host: false,
            })
            .expect("queue same-client conflict admission");

        app.process_network_events()
            .expect("preexecute same-client conflict admission");
        let controls = commands.take_preexecuted_player_infos();
        let [(updated_existing, updated_ids), (admitted, admitted_ids)] = controls.as_slice() else {
            panic!("expected non-joining update echo before joining admission echo");
        };
        assert!(updated_ids.is_empty());
        assert_eq!(
            admitted_ids.iter().map(|player| player.id).collect::<Vec<_>>(),
            vec![1, 2]
        );

        event_tx
            .send(NetworkEvent::PreexecutedPlayerInfoEcho {
                original: updated_existing.clone(),
                info: updated_existing.clone(),
                join_players_on_echo: updated_ids.clone(),
            })
            .expect("queue updated-existing echo");
        app.process_network_events()
            .expect("merge updated-existing echo");
        assert!(commands.take_submitted_join_players().is_empty());

        event_tx
            .send(NetworkEvent::PreexecutedPlayerInfoEcho {
                original: admitted.clone(),
                info: admitted.clone(),
                join_players_on_echo: admitted_ids.clone(),
            })
            .expect("queue admitted echo");
        app.process_network_events().expect("merge admitted echo");
        let joins = commands.take_submitted_join_players();
        assert_eq!(joins.len(), 1);
        assert_eq!(joins[0].1.info_id, admitted.players[0].id);
    }

    #[test]
    fn same_client_add_echo_normalizes_and_issues_only_its_direct_snapshot() {
        let mut app = new_state_only_running_sandbox_app();
        app.control_clients.register(3, true, false);
        app.control_player_infos.replace_snapshot(0, []);
        let resources = [
            clonk_engine::NetworkResourceCore {
                resource_type: clonk_network::HostResourceType::Player as u8,
                id: 17,
                loadable: true,
                filename: clonk_engine::LegacyCString::from_bytes(b"First.c4p".to_vec()).unwrap(),
                ..Default::default()
            },
            clonk_engine::NetworkResourceCore {
                resource_type: clonk_network::HostResourceType::Player as u8,
                id: 18,
                loadable: true,
                filename: clonk_engine::LegacyCString::from_bytes(b"Second.c4p".to_vec()).unwrap(),
                ..Default::default()
            },
        ];
        for resource in &resources {
            app.admission_resources.register_lobby_resource(resource);
            app.admission_resources.mark_complete(
                resource.id,
                PathBuf::from(resource.filename.to_string_lossy().into_owned()),
            );
        }
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(host_network_settings()));
        for (index, (name, color)) in [
            (b"First".as_slice(), 0x00f4_0000),
            (b"Second".as_slice(), 0x0000_00f4),
        ]
        .into_iter()
        .enumerate()
        {
            event_tx
                .send(NetworkEvent::PlayerInfoUpdateRequest {
                    origin: 3,
                    request: clonk_network::PlayerInfoUpdateRequest {
                        client_id: 3,
                        flags: clonk_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS,
                        players: vec![clonk_engine::ControlPlayerInfoEntry {
                            name: clonk_engine::LegacyCString::from_bytes(name.to_vec()).unwrap(),
                            color,
                            original_color: color,
                            resource: Some(resources[index].clone()),
                            ..Default::default()
                        }],
                    },
                    by_host: false,
                })
                .expect("queue same-client admission");
        }

        app.process_network_events()
            .expect("preexecute both same-client admissions");
        let controls = commands.take_preexecuted_player_infos();
        assert_eq!(controls.len(), 2);
        assert_eq!(
            controls[0]
                .1
                .iter()
                .map(|player| player.id)
                .collect::<Vec<_>>(),
            vec![1]
        );
        assert_eq!(
            controls[1]
                .1
                .iter()
                .map(|player| player.id)
                .collect::<Vec<_>>(),
            vec![1, 2]
        );
        app.control_clients.register(3, false, false);

        let mut first_echo = controls[0].0.clone();
        first_echo.players[0].flags |= clonk_engine::PLAYER_INFO_FLAG_HAS_RESOURCE;
        event_tx
            .send(NetworkEvent::PreexecutedPlayerInfoEcho {
                original: controls[0].0.clone(),
                info: first_echo,
                join_players_on_echo: controls[0].1.clone(),
            })
            .expect("queue first admission echo");
        app.process_network_events()
            .expect("merge first admission echo");
        let first_joins = commands.take_submitted_join_players();
        assert_eq!(
            first_joins
                .iter()
                .map(|(_, join)| join.info_id)
                .collect::<Vec<_>>(),
            vec![1]
        );
        assert_ne!(
            app.control_player_infos.get(1).unwrap().flags
                & clonk_engine::PLAYER_INFO_FLAG_HAS_RESOURCE,
            0,
            "A Add normalization must survive the later B Add echo"
        );

        event_tx
            .send(NetworkEvent::PreexecutedPlayerInfoEcho {
                original: controls[1].0.clone(),
                info: controls[1].0.clone(),
                join_players_on_echo: controls[1].1.clone(),
            })
            .expect("queue second admission echo");
        app.process_network_events()
            .expect("merge second admission echo");
        let second_joins = commands.take_submitted_join_players();
        assert_eq!(
            second_joins
                .iter()
                .map(|(_, join)| join.info_id)
                .collect::<Vec<_>>(),
            vec![2]
        );
        assert_ne!(
            app.control_player_infos.get(1).unwrap().flags
                & clonk_engine::PLAYER_INFO_FLAG_HAS_RESOURCE,
            0
        );
    }

    #[test]
    fn stale_add_echo_joins_its_snapshot_without_normalizing_later_replacement() {
        let mut app = new_state_only_running_sandbox_app();
        app.control_clients.register(3, true, false);
        app.control_player_infos.replace_snapshot(0, []);
        let resource = |id, filename: &[u8]| clonk_engine::NetworkResourceCore {
            resource_type: clonk_network::HostResourceType::Player as u8,
            id,
            loadable: true,
            filename: clonk_engine::LegacyCString::from_bytes(filename.to_vec()).unwrap(),
            ..Default::default()
        };
        let first_resource = resource(17, b"First.c4p");
        let replacement_resource = resource(18, b"Replacement.c4p");
        for core in [&first_resource, &replacement_resource] {
            app.admission_resources.register_lobby_resource(core);
            app.admission_resources.mark_complete(
                core.id,
                PathBuf::from(core.filename.to_string_lossy().into_owned()),
            );
        }
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(host_network_settings()));
        for request in [
            clonk_network::PlayerInfoUpdateRequest {
                client_id: 3,
                flags: clonk_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS,
                players: vec![clonk_engine::ControlPlayerInfoEntry {
                    name: clonk_engine::LegacyCString::from_bytes(b"First".to_vec()).unwrap(),
                    color: 0x00f4_0000,
                    original_color: 0x00f4_0000,
                    resource: Some(first_resource.clone()),
                    ..Default::default()
                }],
            },
            clonk_network::PlayerInfoUpdateRequest {
                client_id: 3,
                flags: 0,
                players: vec![clonk_engine::ControlPlayerInfoEntry {
                    id: 1,
                    name: clonk_engine::LegacyCString::from_bytes(b"Replacement".to_vec()).unwrap(),
                    color: 0x0000_00f4,
                    original_color: 0x0000_00f4,
                    resource: Some(replacement_resource.clone()),
                    ..Default::default()
                }],
            },
        ] {
            event_tx
                .send(NetworkEvent::PlayerInfoUpdateRequest {
                    origin: 3,
                    request,
                    by_host: false,
                })
                .expect("queue add/replacement admission");
        }

        app.process_network_events()
            .expect("preexecute add before replacement");
        let controls = commands.take_preexecuted_player_infos();
        assert_eq!(controls.len(), 2);
        assert_eq!(controls[0].1[0].resource.as_ref(), Some(&first_resource));
        assert_eq!(
            controls[1].1[0].resource.as_ref(),
            Some(&replacement_resource)
        );
        assert_eq!(
            app.control_player_infos.get(1).unwrap().resource.as_ref(),
            Some(&replacement_resource)
        );

        event_tx
            .send(NetworkEvent::PreexecutedPlayerInfoEcho {
                original: controls[0].0.clone(),
                info: controls[0].0.clone(),
                join_players_on_echo: controls[0].1.clone(),
            })
            .expect("queue stale add echo");
        app.process_network_events().expect("merge stale add echo");
        let first_joins = commands.take_submitted_join_players();
        assert_eq!(first_joins.len(), 1);
        assert_eq!(
            first_joins[0].1.source,
            clonk_engine::JoinPlayerSource::Resource(first_resource)
        );
        assert_eq!(
            app.control_player_infos.get(1).unwrap().resource.as_ref(),
            Some(&replacement_resource),
            "a stale add echo must not overwrite the later replacement row"
        );

        event_tx
            .send(NetworkEvent::PreexecutedPlayerInfoEcho {
                original: controls[1].0.clone(),
                info: controls[1].0.clone(),
                join_players_on_echo: controls[1].1.clone(),
            })
            .expect("queue latest replacement echo");
        app.process_network_events()
            .expect("merge latest replacement echo");
        assert!(commands.take_submitted_join_players().is_empty());
    }

    #[test]
    fn delayed_admission_joins_parent_before_other_client_rebalance_follow_up() {
        let resource = |id, filename: &[u8]| clonk_engine::NetworkResourceCore {
            resource_type: clonk_network::HostResourceType::Player as u8,
            id,
            loadable: true,
            filename: clonk_engine::LegacyCString::from_bytes(filename.to_vec()).unwrap(),
            ..Default::default()
        };
        let parent_resource = resource(17, b"Parent.c4p");
        let other_resource = resource(18, b"Other.c4p");
        let fixed = clonk_engine::PLAYER_INFO_FLAG_ATTRIBUTES_FIXED;
        let mut other_unjoined = set_control_test_player(10, 1, fixed);
        other_unjoined.color = 0x00f4_0000;
        other_unjoined.original_color = 0x00f4_0000;
        other_unjoined.resource = Some(other_resource.clone());
        let mut joined_twenty = set_control_test_player(
            20,
            1,
            fixed | clonk_engine::PLAYER_INFO_FLAG_JOINED,
        );
        joined_twenty.color = 0x0000_c800;
        joined_twenty.original_color = 0x0000_c800;
        let mut joined_thirty = set_control_test_player(
            30,
            1,
            fixed | clonk_engine::PLAYER_INFO_FLAG_JOINED,
        );
        joined_thirty.color = 0x0000_00f4;
        joined_thirty.original_color = 0x0000_00f4;

        let mut app = new_state_only_running_sandbox_app();
        app.control_clients.register(3, true, false);
        app.control_clients.register(4, true, false);
        app.control_player_infos.replace_snapshot(
            30,
            [clonk_engine::PlayerInfoControlData {
                client_id: 4,
                players: vec![other_unjoined, joined_twenty, joined_thirty],
                ..Default::default()
            }],
        );
        let mut metadata = set_control_test_metadata(
            false,
            vec![
                set_control_test_team(1, vec![10, 20, 30], 0),
                set_control_test_team(2, Vec::new(), 0),
            ],
        );
        metadata.team_distribution = clonk_engine::InitialNetworkTeamDistribution::Random;
        app.engine
            .set_teams(runtime_teams_from_initial_metadata(&metadata));
        app.network_team_assignment = Some(NetworkTeamAssignmentState::from_prepared_host(
            metadata,
        ));
        for core in [&parent_resource, &other_resource] {
            app.admission_resources.register_lobby_resource(core);
            app.admission_resources.mark_complete(
                core.id,
                PathBuf::from(core.filename.to_string_lossy().into_owned()),
            );
        }
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(host_network_settings()));
        event_tx
            .send(NetworkEvent::PlayerInfoUpdateRequest {
                origin: 3,
                request: clonk_network::PlayerInfoUpdateRequest {
                    client_id: 3,
                    flags: clonk_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS,
                    players: vec![clonk_engine::ControlPlayerInfoEntry {
                        name: clonk_engine::LegacyCString::from_bytes(b"Parent".to_vec()).unwrap(),
                        flags: fixed,
                        color: 0x00f4_f400,
                        original_color: 0x00f4_f400,
                        resource: Some(parent_resource),
                        ..Default::default()
                    }],
                },
                by_host: false,
            })
            .expect("queue delayed parent admission");

        app.process_network_events()
            .expect("preexecute admission and random-team follow-up");
        let controls = commands.take_preexecuted_player_infos();
        assert_eq!(
            controls
                .iter()
                .map(|(info, _)| info.client_id)
                .collect::<Vec<_>>(),
            vec![3, 4]
        );
        assert_eq!(
            controls
                .iter()
                .map(|(_, players)| players.iter().map(|player| player.id).collect::<Vec<_>>())
                .collect::<Vec<_>>(),
            vec![vec![31], vec![10]]
        );
        for (info, join_players_on_echo) in controls {
            event_tx
                .send(NetworkEvent::PreexecutedPlayerInfoEcho {
                    original: info.clone(),
                    info,
                    join_players_on_echo,
                })
                .expect("queue normalized preexecuted echo");
        }

        app.process_network_events()
            .expect("issue joins in direct-control order");
        assert_eq!(
            commands
                .take_submitted_join_players()
                .into_iter()
                .map(|(_, join)| (join.at_client, join.info_id))
                .collect::<Vec<_>>(),
            vec![(3, 31), (4, 10)]
        );
    }

    #[test]
    fn preexecuted_join_snapshot_is_client_scoped_for_duplicate_info_id() {
        let resource = |id, filename: &[u8]| clonk_engine::NetworkResourceCore {
            resource_type: clonk_network::HostResourceType::Player as u8,
            id,
            loadable: true,
            filename: clonk_engine::LegacyCString::from_bytes(filename.to_vec()).unwrap(),
            ..Default::default()
        };
        let wrong_resource = resource(17, b"Wrong.c4p");
        let target_resource = resource(18, b"Target.c4p");
        let wrong = clonk_engine::ControlPlayerInfoEntry {
            id: 7,
            name: clonk_engine::LegacyCString::from_bytes(b"Wrong".to_vec()).unwrap(),
            resource: Some(wrong_resource),
            ..Default::default()
        };
        let target = clonk_engine::ControlPlayerInfoEntry {
            id: 7,
            name: clonk_engine::LegacyCString::from_bytes(b"Target".to_vec()).unwrap(),
            player_type: clonk_engine::PLAYER_INFO_TYPE_SCRIPT,
            resource: Some(target_resource.clone()),
            ..Default::default()
        };

        let mut app = new_state_only_running_sandbox_app();
        app.control_clients.register(3, true, false);
        app.control_player_infos.replace_snapshot(
            7,
            [
                clonk_engine::PlayerInfoControlData {
                    client_id: 4,
                    players: vec![wrong],
                    ..Default::default()
                },
                clonk_engine::PlayerInfoControlData {
                    client_id: 3,
                    players: vec![target.clone()],
                    ..Default::default()
                },
            ],
        );
        let (manager, _event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(host_network_settings()));

        app.broadcast_and_preexecute_player_info(
            clonk_engine::PlayerInfoControlData {
                client_id: 3,
                players: vec![target],
                by_client: 0,
                ..Default::default()
            },
            false,
            true,
        )
        .expect("preexecute target-client PlayerInfo");

        let controls = commands.take_preexecuted_player_infos();
        let [(_, captured)] = controls.as_slice() else {
            panic!("expected one preexecuted target-client control");
        };
        let [captured] = captured.as_slice() else {
            panic!("expected one target-client join snapshot row");
        };
        assert_eq!(captured.player_type, clonk_engine::PLAYER_INFO_TYPE_SCRIPT);
        assert_eq!(captured.resource.as_ref(), Some(&target_resource));
    }

    #[test]
    fn host_updated_admission_emits_clean_full_follow_up_after_direct_apply() {
        let same_name =
            clonk_engine::LegacyCString::from_bytes(b"Same".to_vec()).expect("valid player name");
        let mut app = new_state_only_running_sandbox_app();
        app.control_player_infos.replace_snapshot(
            1,
            [clonk_engine::PlayerInfoControlData {
                client_id: 2,
                players: vec![clonk_engine::ControlPlayerInfoEntry {
                    id: 1,
                    name: same_name.clone(),
                    color: 0x00f4_0000,
                    original_color: 0x00f4_0000,
                    league_score: 10,
                    ..Default::default()
                }],
                ..Default::default()
            }],
        );
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(host_network_settings()));
        app.host_join_snapshot = clonk_network::HostConfig::default().initial_join_snapshot;
        event_tx
            .send(NetworkEvent::PlayerInfoUpdateRequest {
                origin: 3,
                request: clonk_network::PlayerInfoUpdateRequest {
                    client_id: 3,
                    flags: clonk_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS,
                    players: vec![clonk_engine::ControlPlayerInfoEntry {
                        name: same_name,
                        color: 0x0000_00f4,
                        original_color: 0x0000_00f4,
                        ..Default::default()
                    }],
                },
                by_host: false,
            })
            .expect("queue lower-priority duplicate admission");
        app.process_network_events()
            .expect("resolve the incoming duplicate name");

        let broadcasts = commands.take_broadcast_player_infos();
        let [admitted, clean_follow_up] = broadcasts.as_slice() else {
            panic!("expected updated admission and clean full follow-up");
        };
        assert_ne!(
            admitted.flags & clonk_engine::CLIENT_PLAYER_INFO_FLAG_UPDATED,
            0
        );
        assert_eq!(admitted.players[0].forced_name.as_bytes(), b"Same (2)");
        assert_eq!(clean_follow_up.client_id, 3);
        assert_eq!(
            clean_follow_up.flags
                & (clonk_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS
                    | clonk_engine::CLIENT_PLAYER_INFO_FLAG_UPDATED),
            0
        );
        assert_eq!(clean_follow_up.players, admitted.players);
        assert!(app.control_player_infos.get(2).is_some());
    }

    #[test]
    fn host_direct_remote_player_info_refreshes_join_data_for_later_consumers() {
        // Game.PlayerInfos aliases Game.Parameters.PlayerInfos, and SendJoinData
        // copies those live parameters. A runtime admission therefore has to be
        // present in the next client's JoinData after its direct control runs
        // (src/C4Game.cpp:65-71; src/C4Network2.cpp:1820-1844;
        // src/C4Network2Players.cpp:233-239).
        let mut app = new_state_only_running_sandbox_app();
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(host_network_settings()));
        app.host_join_snapshot = clonk_network::HostConfig::default().initial_join_snapshot;
        event_tx
            .send(NetworkEvent::PlayerInfoUpdateRequest {
                origin: 9,
                request: clonk_network::PlayerInfoUpdateRequest {
                    client_id: 3,
                    flags: clonk_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS,
                    players: vec![clonk_engine::ControlPlayerInfoEntry {
                        name: clonk_engine::LegacyCString::from_bytes(b"Runtime Remote".to_vec())
                            .expect("valid player name"),
                        ..Default::default()
                    }],
                },
                by_host: false,
            })
            .expect("queue runtime PlayerInfo request");
        app.process_network_events()
            .expect("admit runtime PlayerInfo request");
        let (broadcasts, published) = commands.take_team_control_updates();
        let [authoritative] = broadcasts.as_slice() else {
            panic!("expected one authoritative PlayerInfo control");
        };
        assert_eq!(authoritative.players[0].id, 1);
        let latest = published.last().expect("updated JoinData is published");
        assert_eq!(published.len(), 1);
        assert_eq!(latest.parameters.player_infos.last_player_id, 1);
        let [client] = latest.parameters.player_infos.clients.as_slice() else {
            panic!("runtime client row is retained in JoinData");
        };
        assert_eq!((client.client_id, client.flags), (3, 0));
        let [player] = client.players.as_slice() else {
            panic!("runtime player row is retained in JoinData");
        };
        assert_eq!(player.id, 1);
        assert_eq!(player.name.as_bytes(), b"Runtime Remote");
        assert_eq!(published.last(), app.host_join_snapshot.as_ref());
    }

    #[test]
    fn host_synchronized_player_info_refreshes_join_data() {
        let mut app = new_state_only_running_sandbox_app();
        let (manager, _event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(host_network_settings()));
        app.host_join_snapshot = clonk_network::HostConfig::default().initial_join_snapshot;
        let authoritative = app
            .control_player_infos
            .admit_request(
                clonk_network::PlayerInfoUpdateRequest {
                    client_id: 4,
                    flags: clonk_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS,
                    players: vec![clonk_engine::ControlPlayerInfoEntry::default()],
                },
                app.network_max_players,
            )
            .expect("runtime PlayerInfo is admitted");

        app.apply_ready_controls(7, vec![NetworkControl::PlayerInfo(authoritative)])
            .expect("synchronized PlayerInfo executes");

        let published = commands.take_published_join_snapshots();
        let latest = published.last().expect("updated JoinData is published");
        assert_eq!(latest.parameters.player_infos.last_player_id, 1);
        assert_eq!(latest.parameters.player_infos.clients[0].client_id, 4);
        assert_eq!(latest.parameters.player_infos.clients[0].players[0].id, 1);
        assert_eq!(published.last(), app.host_join_snapshot.as_ref());
    }

    #[test]
    fn host_direct_player_info_rebalances_random_teams_and_broadcasts_changed_packet() {
        // HandlePlayerInfo runs RecheckPlayers followed by the control-host
        // RecheckTeams. The third unjoined player makes a 3/0 split, so the
        // first member moves once. The incoming Updated flag and the move
        // both mark the same owner, but SendUpdatedPlayers emits that
        // client's complete, clean packet only once
        // (src/C4Network2Players.cpp:245-275; src/C4Teams.cpp:688-730).
        let mut app = new_state_only_running_sandbox_app();
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(host_network_settings()));

        let mut metadata = set_control_test_metadata(
            false,
            vec![
                set_control_test_team(1, vec![10, 20], 0),
                set_control_test_team(2, Vec::new(), 0),
            ],
        );
        metadata.team_distribution = clonk_engine::InitialNetworkTeamDistribution::Random;
        app.engine
            .set_teams(runtime_teams_from_initial_metadata(&metadata));
        app.network_team_assignment = Some(NetworkTeamAssignmentState::from_prepared_host(
            metadata,
        ));
        app.control_player_infos.replace_snapshot(
            30,
            [clonk_engine::PlayerInfoControlData {
                client_id: 3,
                players: vec![
                    set_control_test_player(10, 1, 0),
                    set_control_test_player(20, 1, 0),
                ],
                ..Default::default()
            }],
        );

        event_tx
            .send(NetworkEvent::DirectControl(NetworkControl::PlayerInfo(
                clonk_engine::PlayerInfoControlData {
                    client_id: 3,
                    flags: clonk_engine::CLIENT_PLAYER_INFO_FLAG_UPDATED,
                    players: vec![
                        set_control_test_player(10, 1, 0),
                        set_control_test_player(20, 1, 0),
                        set_control_test_player(30, 1, 0),
                    ],
                    by_client: 0,
                },
            )))
            .expect("queue host-authored PlayerInfo addition");
        app.process_network_events()
            .expect("apply host-authored PlayerInfo addition");

        let teams = app
            .network_team_assignment
            .as_ref()
            .expect("host team assignment remains installed")
            .teams();
        assert_eq!(teams.teams[0].player_ids, vec![20, 30]);
        assert_eq!(teams.teams[1].player_ids, vec![10]);
        assert_eq!(app.control_player_infos.get(10).unwrap().team, 2);
        assert_eq!(app.control_player_infos.get(20).unwrap().team, 1);
        assert_eq!(app.control_player_infos.get(30).unwrap().team, 1);

        let broadcasts = commands.take_broadcast_player_infos();
        let [updated] = broadcasts.as_slice() else {
            panic!("expected one rebalanced PlayerInfo packet, got {broadcasts:?}");
        };
        assert_eq!((updated.client_id, updated.by_client), (3, 0));
        assert_eq!(
            updated.flags
                & (clonk_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS
                    | clonk_engine::CLIENT_PLAYER_INFO_FLAG_UPDATED),
            0,
        );
        assert_eq!(
            updated
                .players
                .iter()
                .map(|player| (player.id, player.team))
                .collect::<Vec<_>>(),
            vec![(10, 2), (20, 1), (30, 1)],
        );
    }

