        app.engine.clear_scenario_script();
        app.engine
            .install_scenario_script_with_convention(
                "OwnerlessViewportOffset.c",
                &format!(
                    "#strict 3\nfunc Probe() {{ SetFilmView({target}); SetViewOffset({target}, 13, 17); }}"
                ),
                true,
            )
            .expect("install ownerless offset probe");
