    #[test]
    fn l013_speed_keys_flash_clamp_and_honor_keyconfig_priority() {
        let mut app = new_running_sandbox_app();
        app.handle_modifiers_changed(ModifiersState::SHIFT)
            .expect("set default speed-key modifiers");
        app.handle_key(VirtualKeyCode::NumpadAdd, ElementState::Pressed)
            .expect("Shift+Numpad+ speeds up without terminating");
        assert!(app.full_speed);
        assert_eq!(app.frame_skip, 2);
        assert_eq!(
            app.runtime_flash_message.as_ref().map(|message| message.text.as_str()),
            Some("Speed: 2x")
        );
        app.handle_key(VirtualKeyCode::NumpadAdd, ElementState::Released)
            .expect("speed-up release has no callback");
        app.handle_key(VirtualKeyCode::NumpadAdd, ElementState::Pressed)
            .expect("repeated speed-up press");
        assert_eq!(app.frame_skip, 3);

        for expected in [2, 1] {
            app.handle_key(VirtualKeyCode::NumpadSubtract, ElementState::Pressed)
                .expect("Shift+Numpad- slows down without terminating");
            assert_eq!(app.frame_skip, expected);
        }
        assert!(!app.full_speed);
        assert_eq!(
            app.runtime_flash_message.as_ref().map(|message| message.text.as_str()),
            Some("Speed: 1x")
        );

        app.frame_skip = 50;
        app.full_speed = false;
        app.handle_key(VirtualKeyCode::NumpadAdd, ElementState::Pressed)
            .expect("upper-bound speed-up still flashes");
        assert_eq!(app.frame_skip, 50);
        assert!(app.full_speed);
        assert_eq!(
            app.runtime_flash_message.as_ref().map(|message| message.text.as_str()),
            Some("Speed: 50x")
        );

        let mut rebound = new_running_sandbox_app();
        rebound.runtime_key_config_cache = OnceLock::new();
        rebound
            .runtime_key_config_cache
            .set(Ok(parse_runtime_key_config(
                b"[Keys]\nGameSpeedUp=G\nGameSlowDown=H\n",
            )
            .expect("parse rebound speed keys")))
            .expect("install rebound speed keys");
        rebound
            .handle_key(VirtualKeyCode::G, ElementState::Pressed)
            .expect("rebound speed-up key");
        assert_eq!(rebound.frame_skip, 2);
        rebound
            .handle_key(VirtualKeyCode::H, ElementState::Pressed)
            .expect("rebound speed-down key");
        assert_eq!(rebound.frame_skip, 1);
        assert!(!rebound.full_speed);

        let mut global_collision = new_running_sandbox_app();
        global_collision.app_paths = None;
        global_collision.runtime_key_config_cache = OnceLock::new();
        global_collision
            .runtime_key_config_cache
            .set(Ok(parse_runtime_key_config(
                b"[Keys]\nSoundToggle=G\nGameSpeedUp=G\n",
            )
            .expect("parse earlier-global collision")))
            .expect("install earlier-global collision");
        let sound_enabled = global_collision
            .audio
            .as_ref()
            .expect("sandbox audio context")
            .options
            .sound_enabled;
        global_collision
            .handle_key(VirtualKeyCode::G, ElementState::Pressed)
            .expect("earlier registered global owns collision");
        assert_eq!(
            global_collision
                .audio
                .as_ref()
                .expect("sandbox audio context")
                .options
                .sound_enabled,
            !sound_enabled
        );
        assert_eq!(global_collision.frame_skip, 1);
        assert!(!global_collision.full_speed);
        assert!(global_collision.runtime_flash_message.is_none());

        let mut collision = new_running_sandbox_app();
        collision.runtime_key_config_cache = OnceLock::new();
        collision
            .runtime_key_config_cache
            .set(Ok(parse_runtime_key_config(
                b"[Keys]\nKbd1Key1=G\nGameSpeedUp=G\n",
            )
            .expect("parse player/global collision")))
            .expect("install player/global collision");
        collision
            .handle_key(VirtualKeyCode::G, ElementState::Pressed)
            .expect("higher-priority player binding owns collision");
        assert_eq!(collision.frame_skip, 1);
        assert!(!collision.full_speed);
        assert!(collision.runtime_flash_message.is_none());
        collision
            .handle_key(VirtualKeyCode::G, ElementState::Released)
            .expect("player binding owns collision release");
    }

    fn runtime_flash_text(app: &GameApp) -> Option<&str> {
        app.runtime_flash_message
            .as_ref()
            .map(|message| message.text.as_str())
    }

    #[test]
    fn l031_debug_keys_toggle_render_flags_and_exact_flashes() {
        let names = RuntimeFlashProducerBoundary::ALL.map(|producer| match producer {
            RuntimeFlashProducerBoundary::ObserverPrompt => "ObserverPrompt",
            RuntimeFlashProducerBoundary::ObserverClear => "ObserverClear",
            RuntimeFlashProducerBoundary::RuntimeJoin => "RuntimeJoin",
            RuntimeFlashProducerBoundary::ControlRate => "ControlRate",
            RuntimeFlashProducerBoundary::FairCrew => "FairCrew",
        });
        assert_eq!(names.len(), 5);
        assert_eq!(names.into_iter().collect::<HashSet<_>>().len(), 5);

        let mut app = new_running_sandbox_app();
        app.handle_modifiers_changed(ModifiersState::CTRL)
            .expect("set exact debug modifiers");
        app.handle_key(VirtualKeyCode::F5, ElementState::Pressed)
            .expect("enable debug mode");
        assert!(app.engine.debug_mode());
        assert_eq!(runtime_flash_text(&app), Some("Debug mode: on"));
        app.bindings.rebind(ControlBindingId::Left, VirtualKeyCode::F5);
        app.engine
            .player_mut(app.local_owner)
            .expect("local player")
            .control
            .pressed_coms = 1 << clonk_engine::COM_LEFT;
        app.handle_key(VirtualKeyCode::F5, ElementState::Released)
            .expect("debug mode has no Up callback");
        assert_ne!(
            app.engine
                .player(app.local_owner)
                .expect("local player")
                .control
                .pressed_coms
                & (1 << clonk_engine::COM_LEFT),
            0,
            "debug callback Up must not leak into modifier-blind player control"
        );

        app.handle_key(VirtualKeyCode::F6, ElementState::Pressed)
            .expect("enable vertices and entrances");
        let flags = app.graphics.debug_draw_flags();
        assert!(flags.show_vertices && flags.show_entrance);
        assert_eq!(runtime_flash_text(&app), Some("Entrance+Vertices: on"));
        app.handle_key(VirtualKeyCode::F6, ElementState::Pressed)
            .expect("disable vertices and entrances");
        let flags = app.graphics.debug_draw_flags();
        assert!(!flags.show_vertices && !flags.show_entrance);
        assert_eq!(runtime_flash_text(&app), Some("Entrance+Vertices: off"));

        for (expected, action, command, pathfinder) in [
            ("Actions", true, false, false),
            ("Commands", false, true, false),
            ("Pathfinder", false, false, true),
            ("Actions/Commands/Pathfinder: off", false, false, false),
        ] {
            app.handle_key(VirtualKeyCode::F7, ElementState::Pressed)
                .expect("cycle the action overlay");
            let flags = app.graphics.debug_draw_flags();
            assert_eq!(
                (flags.show_action, flags.show_command, flags.show_pathfinder),
                (action, command, pathfinder)
            );
            assert_eq!(runtime_flash_text(&app), Some(expected));
        }

        app.handle_key(VirtualKeyCode::F8, ElementState::Pressed)
            .expect("enable solid-mask display");
        assert!(app.graphics.debug_draw_flags().show_solid_mask);
        assert_eq!(runtime_flash_text(&app), Some("SolidMasks: on"));
        app.handle_key(VirtualKeyCode::F8, ElementState::Pressed)
            .expect("disable solid-mask display");
        assert!(!app.graphics.debug_draw_flags().show_solid_mask);
        assert_eq!(runtime_flash_text(&app), Some("SolidMasks: off"));

        let mut flags = app.graphics.debug_draw_flags();
        flags.show_net_status = true;
        app.graphics.set_debug_draw_flags(flags);
        app.handle_key(VirtualKeyCode::F5, ElementState::Pressed)
            .expect("disable debug mode");
        assert!(!app.engine.debug_mode());
        assert_eq!(
            app.graphics.debug_draw_flags(),
            clonk_frontend::DebugDrawFlags::default()
        );
        assert_eq!(runtime_flash_text(&app), Some("Debug mode: off"));
        assert_eq!(app.mode, AppMode::Running);
        assert!(!app.exit_requested);
    }

    /// Run a test body on an explicitly sized thread. Debug builds keep one
    /// O0 stack slot per by-value `GameApp` in a frame, so bodies that
    /// accumulate a dozen apps sit right at libtest's default thread stack;
    /// 16 MiB restores the headroom without touching the body itself.
    fn run_on_multi_app_test_stack(body: fn()) {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(body)
            .expect("spawn multi-app test worker")
            .join()
            .expect("multi-app test worker completes");
    }

    #[test]
    fn l031_debug_key_gates_remaps_and_native_priority_are_nonfatal() {
        // Thirteen sandbox apps live in this one debug-build frame; their
        // combined O0 stack slots sit right at the default test-thread stack.
        run_on_multi_app_test_stack(l031_debug_key_gates_remaps_and_native_priority_body);
    }

    fn l031_debug_key_gates_remaps_and_native_priority_body() {
        for key in [VirtualKeyCode::F6, VirtualKeyCode::F7, VirtualKeyCode::F8] {
            let mut app = new_running_sandbox_app();
            app.handle_modifiers_changed(ModifiersState::CTRL)
                .expect("set exact debug modifiers");
            app.handle_key(key, ElementState::Pressed)
                .expect("a denied overlay callback is not fatal");
            assert_eq!(runtime_flash_text(&app), Some("No debug mode!"));
            assert_eq!(
                app.graphics.debug_draw_flags(),
                clonk_frontend::DebugDrawFlags::default()
            );
            assert!(!app.exit_requested);
        }

        let mut denied = new_running_sandbox_app();
        denied.engine.set_allow_debug(false);
        denied
            .handle_modifiers_changed(ModifiersState::CTRL)
            .expect("set exact debug modifiers");
        denied
            .handle_key(VirtualKeyCode::F5, ElementState::Pressed)
            .expect("AllowDebug denial is not fatal");
        assert!(!denied.engine.debug_mode());
        assert_eq!(runtime_flash_text(&denied), Some("Debug mode: not allowed"));

        let mut missing_resources = new_running_sandbox_app();
        missing_resources.runtime_key_config_cache = OnceLock::new();
        missing_resources
            .runtime_key_config_cache
            .set(Err("missing custom key list".to_string()))
            .expect("install missing debug key configuration");
        missing_resources.runtime_flash_resources_cache = OnceLock::new();
        missing_resources
            .runtime_flash_resources_cache
            .set(Err("missing language table".to_string()))
            .expect("install missing debug resources");
        missing_resources
            .handle_modifiers_changed(ModifiersState::CTRL)
            .expect("set exact debug modifiers");
        missing_resources
            .handle_key(VirtualKeyCode::F5, ElementState::Pressed)
            .expect("missing flash resources cannot make the debug key fatal");
        assert!(missing_resources.engine.debug_mode());
        assert_eq!(
            runtime_flash_text(&missing_resources),
            Some("[Undefined: IDS_CTL_DEBUGMODE]: [Undefined: IDS_CTL_ON]")
        );

        let mut disabled_binding = new_running_sandbox_app();
        disabled_binding.runtime_key_config_cache = OnceLock::new();
        disabled_binding
            .runtime_key_config_cache
            .set(Ok(parse_runtime_key_config(
                b"[Keys]\nDbgModeToggle=None\n",
            )
            .expect("parse disabled debug binding")))
            .expect("install disabled debug binding");
        disabled_binding
            .handle_modifiers_changed(ModifiersState::CTRL)
            .expect("set disabled default debug chord");
        disabled_binding
            .handle_key(VirtualKeyCode::F5, ElementState::Pressed)
            .expect("a replaced Ctrl+F5 binding is inert rather than fatal");
        assert!(!disabled_binding.engine.debug_mode());
        assert!(disabled_binding.runtime_flash_message.is_none());

        let mut debug_collision = new_running_sandbox_app();
        debug_collision.engine.set_allow_debug(false);
        debug_collision.runtime_key_config_cache = OnceLock::new();
        debug_collision
            .runtime_key_config_cache
            .set(Ok(parse_runtime_key_config(
                b"[Keys]\nDbgModeToggle=G\nDbgShowVtxToggle=G\n",
            )
            .expect("parse same-priority debug collision")))
            .expect("install same-priority debug collision");
        debug_collision
            .handle_key(VirtualKeyCode::G, ElementState::Pressed)
            .expect("denied debug callbacks fall through in registration order");
        assert_eq!(runtime_flash_text(&debug_collision), Some("No debug mode!"));

        let mut modified_player = new_running_sandbox_app();
        modified_player
            .bindings
            .rebind(ControlBindingId::Left, VirtualKeyCode::F5);
        modified_player
            .handle_modifiers_changed(ModifiersState::CTRL)
            .expect("set Ctrl for exact-modifier player priority");
        modified_player
            .handle_key(VirtualKeyCode::F5, ElementState::Pressed)
            .expect("bare player F5 does not steal Ctrl+F5");
        assert!(modified_player.engine.debug_mode());

        let mut context_priority = new_running_sandbox_app();
        context_priority.runtime_key_config_cache = OnceLock::new();
        context_priority
            .runtime_key_config_cache
            .set(Ok(parse_runtime_key_config(
                b"[Keys]\nDbgModeToggle=R\n",
            )
            .expect("parse context/debug collision")))
            .expect("install context/debug collision");
        context_priority
            .open_context_menu_at(
                vec![ContextMenuEntry::<AppContextMenuCommand>::new("Remain off")
                    .with_hotkey('R')],
                GuiPoint::new(20.0, 20.0),
            )
            .expect("open higher-priority context menu");
        context_priority
            .handle_key(VirtualKeyCode::R, ElementState::Pressed)
            .expect("context hotkey precedes remapped debug callback");
        assert!(!context_priority.engine.debug_mode());
        assert!(context_priority.runtime_flash_message.is_none());

        let mut chat_priority = new_running_sandbox_app();
        chat_priority.runtime_key_config_cache = OnceLock::new();
        chat_priority
            .runtime_key_config_cache
            .set(Ok(parse_runtime_key_config(
                b"[Keys]\nDbgModeToggle=Return\n",
            )
            .expect("parse chat/debug collision")))
            .expect("install chat/debug collision");
        chat_priority.start_running_chat(RunningChatMode::All);
        chat_priority
            .handle_key(VirtualKeyCode::Return, ElementState::Pressed)
            .expect("focused chat Return precedes remapped debug callback");
        assert!(!chat_priority.engine.debug_mode());
        assert!(!chat_priority.running_chat_active());

        let mut modified_chat_fallthrough = new_running_sandbox_app();
        modified_chat_fallthrough.runtime_key_config_cache = OnceLock::new();
        modified_chat_fallthrough
            .runtime_key_config_cache
            .set(Ok(parse_runtime_key_config(
                b"[Keys]\nDbgModeToggle=Ctrl+Alt+G\n",
            )
            .expect("parse modified chat/debug collision")))
            .expect("install modified chat/debug collision");
        modified_chat_fallthrough.start_running_chat(RunningChatMode::All);
        modified_chat_fallthrough
            .handle_modifiers_changed(ModifiersState::CTRL | ModifiersState::ALT)
            .expect("set Ctrl+Alt chat/debug modifiers");
        modified_chat_fallthrough
            .handle_key(VirtualKeyCode::G, ElementState::Pressed)
            .expect("an unowned Ctrl+Alt chat chord reaches the debug callback");
        assert!(modified_chat_fallthrough.engine.debug_mode());
        assert!(modified_chat_fallthrough.running_chat_active());

        let mut vote_priority = new_running_sandbox_app();
        vote_priority.runtime_key_config_cache = OnceLock::new();
        vote_priority
            .runtime_key_config_cache
            .set(Ok(parse_runtime_key_config(
                b"[Keys]\nDbgModeToggle=Return\n",
            )
            .expect("parse vote/debug collision")))
            .expect("install vote/debug collision");
        vote_priority
            .push_message_dialog(
                clonk_frontend::message_dialog::MessageDialogState::new(
                    "Vote?",
                    "Voting",
                    clonk_frontend::message_dialog::MessageDialogButtons::YES_NO,
                    clonk_frontend::message_dialog::MessageDialogIcon::CONFIRM,
                    clonk_frontend::message_dialog::MessageDialogSize::Regular,
                    true,
                ),
                MessageDialogContinuation::LeagueSurrender,
            )
            .expect("show exclusive vote for debug priority");
        vote_priority
            .handle_key(VirtualKeyCode::Return, ElementState::Pressed)
            .expect("exclusive vote Return precedes remapped debug callback");
        assert!(!vote_priority.engine.debug_mode());
        assert!(vote_priority.runtime_flash_message.is_none());
        assert_eq!(vote_priority.message_dialogs.len(), 1);
        vote_priority
            .handle_key(VirtualKeyCode::Return, ElementState::Released)
            .expect("exclusive vote owns the matching Return release");
        assert!(vote_priority.message_dialogs.is_empty());
        assert_eq!(vote_priority.mode, AppMode::Running);

        let mut game_over_priority = new_game_over_keyboard_app();
        game_over_priority.runtime_key_config_cache = OnceLock::new();
        game_over_priority
            .runtime_key_config_cache
            .set(Ok(parse_runtime_key_config(
                b"[Keys]\nDbgModeToggle=Return\n",
            )
            .expect("parse game-over/debug collision")))
            .expect("install game-over/debug collision");
        game_over_priority
            .handle_key(VirtualKeyCode::Return, ElementState::Pressed)
            .expect("game-over Return precedes remapped debug callback");
        assert!(!game_over_priority.engine.debug_mode());
        assert!(game_over_priority.running_chat_active());

        let mut disable = new_running_sandbox_app();
        disable.engine.set_allow_debug(false);
        disable.engine.set_debug_mode(true);
        disable
            .graphics
            .set_debug_draw_flags(clonk_frontend::DebugDrawFlags {
                show_vertices: true,
                show_entrance: true,
                show_action: true,
                show_command: true,
                show_pathfinder: true,
                show_solid_mask: true,
                show_net_status: true,
            });
        disable
            .handle_modifiers_changed(ModifiersState::CTRL)
            .expect("set exact debug modifiers");
        disable
            .handle_key(VirtualKeyCode::F5, ElementState::Pressed)
            .expect("an already-enabled mode may always be disabled");
        assert!(!disable.engine.debug_mode());
        assert_eq!(
            disable.graphics.debug_draw_flags(),
            clonk_frontend::DebugDrawFlags::default()
        );

        let mut later_collision = new_running_sandbox_app();
        later_collision.runtime_key_config_cache = OnceLock::new();
        later_collision
            .runtime_key_config_cache
            .set(Ok(parse_runtime_key_config(
                b"[Keys]\nDbgShowVtxToggle=G\nGameSpeedUp=G\n",
            )
            .expect("parse denied-debug/later-global collision")))
            .expect("install denied-debug/later-global collision");
        later_collision
            .handle_key(VirtualKeyCode::G, ElementState::Pressed)
            .expect("denied debug callback falls through to later speed callback");
        assert!(!later_collision.engine.debug_mode());
        assert_eq!(later_collision.frame_skip, 2);
        assert!(later_collision.full_speed);
        assert_eq!(runtime_flash_text(&later_collision), Some("Speed: 2x"));

        let mut rebound = new_running_sandbox_app();
        rebound.runtime_key_config_cache = OnceLock::new();
        rebound
            .runtime_key_config_cache
            .set(Ok(parse_runtime_key_config(
                b"[Keys]\nDbgModeToggle=G\nDbgShowVtxToggle=H\n",
            )
            .expect("parse rebound debug keys")))
            .expect("install rebound debug keys");
        rebound
            .handle_key(VirtualKeyCode::G, ElementState::Pressed)
            .expect("rebound debug mode key");
        assert!(rebound.engine.debug_mode());
        rebound
            .handle_key(VirtualKeyCode::H, ElementState::Pressed)
            .expect("rebound vertex key");
        assert!(rebound.graphics.debug_draw_flags().show_vertices);

        let mut player_collision = new_running_sandbox_app();
        player_collision.runtime_key_config_cache = OnceLock::new();
        player_collision
            .runtime_key_config_cache
            .set(Ok(parse_runtime_key_config(
                b"[Keys]\nKbd1Key1=G\nDbgModeToggle=G\n",
            )
            .expect("parse player/debug collision")))
            .expect("install player/debug collision");
        player_collision
            .handle_key(VirtualKeyCode::G, ElementState::Pressed)
            .expect("PRIO_PlrControl owns the debug collision");
        assert!(!player_collision.engine.debug_mode());
        assert!(player_collision.runtime_flash_message.is_none());

        let mut global_collision = new_running_sandbox_app();
        global_collision.runtime_key_config_cache = OnceLock::new();
        global_collision
            .runtime_key_config_cache
            .set(Ok(parse_runtime_key_config(
                b"[Keys]\nSoundToggle=G\nDbgModeToggle=G\n",
            )
            .expect("parse earlier-global/debug collision")))
            .expect("install earlier-global/debug collision");
        let sound_enabled = global_collision
            .audio
            .as_ref()
            .expect("sandbox audio")
            .options
            .sound_enabled;
        global_collision
            .handle_key(VirtualKeyCode::G, ElementState::Pressed)
            .expect("earlier SoundToggle owns the collision");
        assert_eq!(
            global_collision
                .audio
                .as_ref()
                .expect("sandbox audio")
                .options
                .sound_enabled,
            !sound_enabled
        );
        assert!(!global_collision.engine.debug_mode());
        assert!(global_collision.runtime_flash_message.is_none());

        let mut game_over = new_game_over_keyboard_app();
        game_over.engine.set_debug_mode(true);
        game_over
            .handle_modifiers_changed(ModifiersState::CTRL)
            .expect("set Ctrl+F8 under game over");
        game_over
            .handle_key(VirtualKeyCode::F8, ElementState::Pressed)
            .expect("Generic debug callback precedes exclusive GUI input");
        assert!(game_over.graphics.debug_draw_flags().show_solid_mask);
        assert!(game_over.game_over_dialog.is_some());
        assert_eq!(runtime_flash_text(&game_over), Some("SolidMasks: on"));
        assert!(!game_over.exit_requested);
    }

    #[test]
    fn l031_always_debug_survives_rust_saves_and_rearms_restored_rounds() {
        for (config, expected) in [
            (&b""[..], false),
            (&b"[General]\nDebugMode=true\n"[..], true),
            (&b"[General]\nDebugMode=1\n"[..], true),
            (&b"[General]\nDebugMode= true\n"[..], false),
            (&b"[General]\nDebugMode=invalid\n"[..], false),
        ] {
            let mut engine = Engine::new();
            arm_graphical_engine_debug_mode(&mut engine, config);
            assert_eq!(engine.debug_mode(), expected);
        }

        let enabled_config = b"[General]\nDebugMode=true\n";
        let mut allowed = Engine::new();
        arm_graphical_engine_debug_mode(&mut allowed, enabled_config);
        let state = allowed.capture_state();
        let mut restored = Engine::new();
        restored
            .restore_state(&state)
            .expect("restore process-independent round state");
        assert!(!restored.debug_mode(), "DebugMode is not serialized");
        arm_graphical_engine_debug_mode(&mut restored, enabled_config);
        assert!(restored.debug_mode(), "round restore reapplies AlwaysDebug");
        let mut denied = Engine::new();
        denied.set_allow_debug(false);
        arm_graphical_engine_debug_mode(&mut denied, enabled_config);
        assert!(!denied.debug_mode());
        let mut disabled = Engine::new();
        arm_graphical_engine_debug_mode(&mut disabled, b"");
        assert!(!disabled.debug_mode());

        let _lock = env_lock().lock();
        reset_cached_app_paths();
        let user_data = tempdir().expect("isolated AlwaysDebug config");
        let (_guard, paths) = exact_loader_test_paths(user_data.path(), None);
        persist_native_config_values(
            &paths,
            "General",
            &[("DebugMode", clonk_app::NativeConfigValue::RawAscii("true"))],
        )
        .expect("enable native AlwaysDebug");

        persist_config_value(&paths, "Network", "Comment", "preserve debug")
            .expect("save unrelated config value");
        let saved = fs::read(paths.config_file()).expect("read unrelated config save");
        assert_eq!(
            clonk_app::configured_native_boolean(&saved, "General", "DebugMode"),
            Some(true)
        );
        let mut next_round = Engine::new();
        arm_configured_graphical_engine_debug_mode(&mut next_round, Some(&paths));
        assert!(next_round.debug_mode());
        reset_cached_app_paths();
    }

    #[test]
    fn runtime_music_flash_recurses_through_every_player_and_engine_menu_screen() {
        let every_player_menu_page = || {
            let entry = GoalRuleEntry {
                definition_id: "CLNK".to_string(),
                name: "Entry".to_string(),
                description: None,
                fulfilled: false,
            };
            vec![
                IngameMenuState::main_menu(&MainMenuConditions::default())
                    .expect("default player main menu"),
                IngameMenuState::hostility_menu(&[]),
                IngameMenuState::observer_menu(&[], ObserverTarget::Free),
                IngameMenuState::team_selection_menu(&[TeamSelectionEntry {
                    id: 1,
                    caption: "Team".to_string(),
                    icon_spec: None,
                    color: 0,
                    has_participants: false,
                }]),
                IngameMenuState::goals_menu(std::slice::from_ref(&entry)),
                IngameMenuState::rules_menu(std::slice::from_ref(&entry)),
                IngameMenuState::new_player_menu(&[ingame_menu::NewPlayerEntry {
                    file: "Player.c4p".to_string(),
                    name: "Player".to_string(),
                }]),
                IngameMenuState::savegame_menu(&[SaveSlotState { free: true }; 10]),
                IngameMenuState::options_menu(
                    &OptionFlags {
                        sound: true,
                        music: true,
                        mouse_shown: true,
                        mouse: true,
                    },
                    0,
                ),
                IngameMenuState::display_menu(&DisplayFlags::default(), 0),
                IngameMenuState::surrender_menu(),
                IngameMenuState::client_disconnect_menu(),
                IngameMenuState::host_disconnect_menu(&[HostDisconnectClientEntry {
                    client_id: 0,
                    caption: "Host (Host)".to_string(),
                    activated: true,
                }]),
            ]
        };
        let default_pages = every_player_menu_page();
        let rebound_pages = every_player_menu_page();
        let sound_pages = every_player_menu_page();
        assert_eq!(default_pages.len(), 13);
        let page_index = |page: ingame_menu::MenuPage| match page {
            ingame_menu::MenuPage::Main => 0,
            ingame_menu::MenuPage::Hostility => 1,
            ingame_menu::MenuPage::Observer => 2,
            ingame_menu::MenuPage::TeamSelection => 3,
            ingame_menu::MenuPage::Goals => 4,
            ingame_menu::MenuPage::Rules => 5,
            ingame_menu::MenuPage::NewPlayer => 6,
            ingame_menu::MenuPage::Savegame => 7,
            ingame_menu::MenuPage::Options => 8,
            ingame_menu::MenuPage::Display => 9,
            ingame_menu::MenuPage::Surrender => 10,
            ingame_menu::MenuPage::ClientDisconnect => 11,
            ingame_menu::MenuPage::HostDisconnect => 12,
        };
        let test_music_bytes = silent_pcm_wav(10);
        let load_test_music = |app: &GameApp| {
            app.audio
                .as_ref()
                .expect("test audio")
                .system
                .load_music(&test_music_bytes)
                .expect("load lightweight runtime music fixture")
        };
        let prime_music_toggle_off = |app: &mut GameApp, music: &MusicHandle| {
            app.audio
                .as_ref()
                .expect("test audio")
                .system
                .play_music(music, true)
                .expect("start lightweight runtime music fixture");
            app.runtime_music_enabled = true;
        };

        let mut default_app = new_classic_lightweight_running_sandbox_app();
        let default_music = load_test_music(&default_app);
        let mut rebound_app = new_classic_lightweight_running_sandbox_app();
        rebound_app
            .bindings
            .rebind(ControlBindingId::Left, VirtualKeyCode::F3);
        rebound_app
            .engine
            .player_mut(rebound_app.local_owner)
            .expect("local player")
            .control
            .control_style = true;
        let mut sound_app = new_classic_lightweight_running_sandbox_app();
        let mut covered = [false; 13];
        for ((default_menu, rebound_menu), sound_menu) in default_pages
            .into_iter()
            .zip(rebound_pages)
            .zip(sound_pages)
        {
            let page = default_menu.page();
            covered[page_index(page)] = true;
            assert_eq!(rebound_menu.page(), page);
            assert_eq!(sound_menu.page(), page);

            default_app
                .ingame_menu
                .replace(default_app.local_owner, Some(default_menu));
            prime_music_toggle_off(&mut default_app, &default_music);
            default_app
                .handle_key(VirtualKeyCode::F3, ElementState::Pressed)
                .expect("music producer reaches every player-menu page");
            let draws_before = default_app
                .runtime_flash_message
                .as_ref()
                .expect("localized flash")
                .remaining_draws;
            let mut frame = vec![0_u8; 320 * 200 * 4];
            default_app
                .render(&mut frame)
                .unwrap_or_else(|error| panic!("render flash over {page:?}: {error:#}"));
            assert_eq!(
                default_app
                    .runtime_flash_message
                    .as_ref()
                    .expect("music text lasts more than one draw")
                    .remaining_draws,
                draws_before - 1,
                "page {page:?}"
            );
            assert_eq!(
                default_app.ingame_menu.as_ref().map(IngameMenuState::page),
                Some(page)
            );
            default_app
                .handle_key(VirtualKeyCode::F3, ElementState::Released)
                .expect("release music producer");

            rebound_app
                .ingame_menu
                .replace(rebound_app.local_owner, Some(rebound_menu));
            rebound_app
                .handle_key(VirtualKeyCode::F3, ElementState::Pressed)
                .expect("player priority owns F3 on every page");
            assert!(rebound_app.runtime_flash_message.is_none(), "page {page:?}");
            assert!(rebound_app.ingame_menu.is_some(), "page {page:?}");
            rebound_app
                .handle_key(VirtualKeyCode::F3, ElementState::Released)
                .expect("release rebound player control");
            assert!(!rebound_app
                .pressed_engine_keys
                .contains(&VirtualKeyCode::F3));
            assert_eq!(
                rebound_app
                    .engine
                    .player(rebound_app.local_owner)
                    .expect("local player")
                    .control
                    .pressed_coms
                    & (1 << clonk_engine::COM_LEFT),
                0
            );

            sound_app
                .ingame_menu
                .replace(sound_app.local_owner, Some(sound_menu));
            let sound_before = sound_app
                .audio
                .as_ref()
                .expect("test audio")
                .options
                .sound_enabled;
            sound_app
                .handle_modifiers_changed(ModifiersState::CTRL)
                .expect("set Ctrl");
            sound_app
                .handle_key(VirtualKeyCode::F3, ElementState::Pressed)
                .expect("Ctrl+F3 reaches every player-menu page");
            assert_eq!(
                sound_app
                    .audio
                    .as_ref()
                    .expect("test audio")
                    .options
                    .sound_enabled,
                !sound_before,
                "page {page:?}"
            );
            assert!(sound_app.runtime_flash_message.is_none(), "page {page:?}");
            assert!(sound_app.ingame_menu.is_some(), "page {page:?}");
            sound_app
                .handle_key(VirtualKeyCode::F3, ElementState::Released)
                .expect("release sound producer");
            sound_app
                .handle_modifiers_changed(ModifiersState::empty())
                .expect("release Ctrl");
        }
        assert!(covered.into_iter().all(|covered| covered));

        let mut default_app = new_classic_lightweight_running_sandbox_app();
        let default_music = load_test_music(&default_app);
        let mut rebound = new_classic_lightweight_running_sandbox_app();
        rebound
            .bindings
            .rebind(ControlBindingId::Left, VirtualKeyCode::F3);
        rebound
            .engine
            .player_mut(rebound.local_owner)
            .expect("local player")
            .control
            .control_style = true;
        let mut sound = new_classic_lightweight_running_sandbox_app();
        for style in 0..=3 {
            for text_progressing in [false, true] {
                let install_menu = |app: &mut GameApp| {
                    let cursor = app
                        .engine
                        .crew_cursor(app.local_owner)
                        .expect("sandbox cursor");
                    let mut menu = two_item_script_menu(cursor);
                    menu.style = style;
                    menu.text_progressing = text_progressing;
                    app.engine
                        .apply_object_update(
                            cursor,
                            ObjectUpdate {
                                menu: Some(Some(menu)),
                                ..ObjectUpdate::default()
                            },
                        )
                        .expect("install engine menu style");
                    app.snapshot = app.engine.snapshot();
                };

                install_menu(&mut default_app);
                prime_music_toggle_off(&mut default_app, &default_music);
                default_app
                    .handle_key(VirtualKeyCode::F3, ElementState::Pressed)
                    .expect("music producer reaches every engine menu style");
                let draws_before = default_app
                    .runtime_flash_message
                    .as_ref()
                    .expect("localized flash")
                    .remaining_draws;
                let mut frame = vec![0_u8; 320 * 200 * 4];
                default_app.render(&mut frame).unwrap_or_else(|error| {
                    panic!("render style {style}, progress {text_progressing}: {error:#}")
                });
                assert_eq!(
                    default_app
                        .runtime_flash_message
                        .as_ref()
                        .expect("music text lasts more than one draw")
                        .remaining_draws,
                    draws_before - 1
                );
                assert!(default_app
                    .engine
                    .cursor_object_menu(default_app.local_owner)
                    .is_some());
                default_app
                    .handle_key(VirtualKeyCode::F3, ElementState::Released)
                    .expect("release music producer");

                install_menu(&mut rebound);
                rebound
                    .handle_key(VirtualKeyCode::F3, ElementState::Pressed)
                    .expect("player F3 owns every engine menu style");
                assert!(rebound.runtime_flash_message.is_none());
                assert!(rebound
                    .engine
                    .cursor_object_menu(rebound.local_owner)
                    .is_some());
                rebound
                    .handle_key(VirtualKeyCode::F3, ElementState::Released)
                    .expect("release rebound player control");
                assert!(!rebound.pressed_engine_keys.contains(&VirtualKeyCode::F3));
                assert_eq!(
                    rebound
                        .engine
                        .player(rebound.local_owner)
                        .expect("local player")
                        .control
                        .pressed_coms
                        & (1 << clonk_engine::COM_LEFT),
                    0
                );

                install_menu(&mut sound);
                let before = sound
                    .audio
                    .as_ref()
                    .expect("test audio")
                    .options
                    .sound_enabled;
                sound
                    .handle_modifiers_changed(ModifiersState::CTRL)
                    .expect("set Ctrl");
                sound
                    .handle_key(VirtualKeyCode::F3, ElementState::Pressed)
                    .expect("Ctrl+F3 reaches every engine menu style");
                assert_eq!(
                    sound
                        .audio
                        .as_ref()
                        .expect("test audio")
                        .options
                        .sound_enabled,
                    !before
                );
                assert!(sound.runtime_flash_message.is_none());
                assert!(sound.engine.cursor_object_menu(sound.local_owner).is_some());
                sound
                    .handle_key(VirtualKeyCode::F3, ElementState::Released)
                    .expect("release sound producer");
                sound
                    .handle_modifiers_changed(ModifiersState::empty())
                    .expect("release Ctrl");
            }
        }
    }

    #[test]
    fn runtime_music_flash_reaches_every_nonexclusive_running_layer() {
        let assert_f3_renders = |app: &mut GameApp, layer: &str| {
            app.handle_key(VirtualKeyCode::F3, ElementState::Pressed)
                .unwrap_or_else(|error| panic!("F3 over {layer}: {error}"));
            let before = app
                .runtime_flash_message
                .as_ref()
                .unwrap_or_else(|| panic!("missing flash over {layer}"))
                .remaining_draws;
            let mut frame = vec![0_u8; 320 * 200 * 4];
            app.render(&mut frame)
                .unwrap_or_else(|error| panic!("render F3 over {layer}: {error:#}"));
            assert_eq!(
                app.runtime_flash_message
                    .as_ref()
                    .expect("music text lasts more than one draw")
                    .remaining_draws,
                before - 1,
                "layer {layer}"
            );
        };

        let mut message = new_running_sandbox_app();
        message
            .push_message_dialog(
                clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                    "Music",
                    "Remain open",
                    clonk_frontend::message_dialog::MessageDialogIcon::NOTIFY,
                ),
                MessageDialogContinuation::None,
            )
            .expect("push running message");
        assert_f3_renders(&mut message, "message dialog");
        assert_eq!(message.message_dialogs.len(), 1);

        let mut context = new_running_sandbox_app();
        context
            .open_context_menu_at(
                vec![ContextMenuEntry::<AppContextMenuCommand>::new(
                    "Remain open",
                )],
                GuiPoint::new(24.0, 24.0),
            )
            .expect("open context");
        assert_f3_renders(&mut context, "context menu");
        assert!(context.context_menu.is_some());

        let mut scoreboard = new_scoreboard_test_app(
            r#"global func Initialize()
            {
                SetScoreboardData(SBRD_Caption, SBRD_Caption, "Scores");
            }"#,
        );
        toggle_scoreboard(&mut scoreboard, ModifiersState::empty());
        assert_f3_renders(&mut scoreboard, "scoreboard");
        assert!(scoreboard.scoreboard_dialog.is_some());

        for mode in [
            SaveBrowserMode::Save {
                suggested_label: "Slot".to_string(),
            },
            SaveBrowserMode::Load,
        ] {
            let mut save_browser = new_running_sandbox_app();
            save_browser.save_browser = Some(SaveBrowserState::new(mode.clone(), Vec::new()));
            save_browser
                .handle_key(VirtualKeyCode::F3, ElementState::Pressed)
                .expect("F3 reaches typed save/load state");
            let flash_before = save_browser.runtime_flash_message.clone();
            let mut frame = vec![0x6d; 320 * 200 * 4];
            let error = save_browser
                .render(&mut frame)
                .expect_err("save/load must fail before generic pixels");
            assert_eq!(
                error.downcast_ref::<ClassicParityBoundary>(),
                Some(&ClassicParityBoundary::SaveBrowser(mode.clone()))
            );
            assert!(frame.iter().all(|byte| *byte == 0x6d));
            assert_eq!(save_browser.runtime_flash_message, flash_before);
        }

        for mode in [
            AppObjectMenuMode::Inventory,
            AppObjectMenuMode::Container,
            AppObjectMenuMode::Context,
            AppObjectMenuMode::Build,
        ] {
            let mut object = new_running_sandbox_app();
            assert!(object
                .open_object_menu()
                .expect("open defensive object state"));
            object
                .object_menu
                .as_mut()
                .expect("defensive object state")
                .set_mode_for_parity_test(mode);
            object
                .handle_key(VirtualKeyCode::F3, ElementState::Pressed)
                .expect("F3 reaches typed app-owned object-menu state");
            let flash_before = object.runtime_flash_message.clone();
            let mut frame = vec![0x4c; 320 * 200 * 4];
            let error = object
                .render(&mut frame)
                .expect_err("object menu must fail before generic pixels");
            assert_eq!(
                error.downcast_ref::<ClassicParityBoundary>(),
                Some(&ClassicParityBoundary::AppObjectMenu(mode))
            );
            assert!(frame.iter().all(|byte| *byte == 0x4c));
            assert_eq!(object.runtime_flash_message, flash_before);
            assert!(object.object_menu.is_some());
        }

        let mut observer = new_running_sandbox_app();
        observer
            .engine
            .remove_player(observer.local_owner)
            .expect("remove local player");
        observer.engine.set_local_players([]);
        observer.snapshot = observer.engine.snapshot();
        observer
            .handle_key(VirtualKeyCode::F3, ElementState::Pressed)
            .expect("Generic F3 reaches ownerless observer state");
        let mut frame = vec![0x7a; 320 * 200 * 4];
        observer
            .render(&mut frame)
            .expect("ownerless observer viewport renders");
        assert!(frame.iter().any(|byte| *byte != 0x7a));
    }

    #[test]
    fn runtime_f3_priority_matrix_covers_every_recursive_running_layer() {
        #[derive(Clone, Copy, Debug)]
        enum Layer {
            Message,
            Context,
            Scoreboard,
            Save,
            Load,
            Object,
            Observer,
            GameOver,
            GameOverNext,
        }

        let make_layer = |layer| {
            let mut app = match layer {
                Layer::Scoreboard => {
                    let mut app = new_scoreboard_test_app(
                        r#"global func Initialize()
                        {
                            SetScoreboardData(SBRD_Caption, SBRD_Caption, "Scores");
                        }"#,
                    );
                    toggle_scoreboard(&mut app, ModifiersState::empty());
                    app
                }
                Layer::GameOver | Layer::GameOverNext => new_classic_running_sandbox_app(),
                _ => new_running_sandbox_app(),
            };
            match layer {
                Layer::Message => app
                    .push_message_dialog(
                        clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                            "Audio",
                            "Nonexclusive",
                            clonk_frontend::message_dialog::MessageDialogIcon::NOTIFY,
                        ),
                        MessageDialogContinuation::None,
                    )
                    .expect("open message"),
                Layer::Context => {
                    app.open_context_menu_at(
                        vec![
                            ContextMenuEntry::<AppContextMenuCommand>::new("Root")
                                .with_submenu(vec![ContextMenuEntry::new("Child")]),
                        ],
                        GuiPoint::new(24.0, 24.0),
                    )
                    .expect("open context");
                }
                Layer::Save => {
                    app.save_browser = Some(SaveBrowserState::new(
                        SaveBrowserMode::Save {
                            suggested_label: "Slot".to_string(),
                        },
                        Vec::new(),
                    ));
                }
                Layer::Load => {
                    app.save_browser =
                        Some(SaveBrowserState::new(SaveBrowserMode::Load, Vec::new()));
                }
                Layer::Object => {
                    assert!(app.open_object_menu().expect("open object state"));
                }
                Layer::Observer => {
                    app.engine
                        .remove_player(app.local_owner)
                        .expect("remove local player");
                    app.engine.set_local_players([]);
                    app.snapshot = app.engine.snapshot();
                }
                Layer::GameOver | Layer::GameOverNext => {
                    if matches!(layer, Layer::GameOverNext) {
                        let mut state = app.engine.capture_state();
                        state.next_mission = clonk_engine::NextMissionState {
                            path: "Next.c4s".to_string(),
                            text: "Next".to_string(),
                            description: "Continue".to_string(),
                        };
                        app.engine
                            .restore_state(&state)
                            .expect("restore next mission");
                        app.snapshot = app.engine.snapshot();
                    }
                    app.handle_game_over().expect("open evaluation");
                }
                Layer::Scoreboard => {}
            }
            app
        };

        for layer in [
            Layer::Message,
            Layer::Context,
            Layer::Scoreboard,
            Layer::Save,
            Layer::Load,
            Layer::Object,
            Layer::Observer,
            Layer::GameOver,
            Layer::GameOverNext,
        ] {
            let player_scope = !matches!(
                layer,
                Layer::Observer | Layer::GameOver | Layer::GameOverNext
            );

            let mut default_app = make_layer(layer);
            default_app
                .handle_key(VirtualKeyCode::F3, ElementState::Pressed)
                .unwrap_or_else(|error| panic!("default F3 on {layer:?}: {error}"));
            assert!(default_app.runtime_flash_message.is_some(), "{layer:?}");
            if matches!(layer, Layer::GameOver | Layer::GameOverNext) {
                let before = default_app
                    .runtime_flash_message
                    .as_ref()
                    .expect("game-over flash")
                    .remaining_draws;
                let mut frame = vec![0_u8; 320 * 200 * 4];
                default_app
                    .render(&mut frame)
                    .unwrap_or_else(|error| panic!("render F3 on {layer:?}: {error:#}"));
                assert_eq!(
                    default_app
                        .runtime_flash_message
                        .as_ref()
                        .expect("music text lasts more than one draw")
                        .remaining_draws,
                    before - 1
                );
            }

            let mut rebound = make_layer(layer);
            rebound
                .bindings
                .rebind(ControlBindingId::Left, VirtualKeyCode::F3);
            if let Ok(player) = rebound.engine.player_mut(rebound.local_owner) {
                player.control.control_style = true;
            }
            rebound
                .handle_key(VirtualKeyCode::F3, ElementState::Pressed)
                .unwrap_or_else(|error| panic!("rebound F3 on {layer:?}: {error}"));
            assert_eq!(
                rebound.runtime_flash_message.is_none(),
                player_scope,
                "{layer:?}"
            );

            let mut sound = make_layer(layer);
            let before = sound
                .audio
                .as_ref()
                .expect("test audio")
                .options
                .sound_enabled;
            sound
                .handle_modifiers_changed(ModifiersState::CTRL)
                .expect("set Ctrl");
            sound
                .handle_key(VirtualKeyCode::F3, ElementState::Pressed)
                .unwrap_or_else(|error| panic!("Ctrl+F3 on {layer:?}: {error}"));
            assert_eq!(
                sound
                    .audio
                    .as_ref()
                    .expect("test audio")
                    .options
                    .sound_enabled,
                !before,
                "{layer:?}"
            );
            assert!(sound.runtime_flash_message.is_none(), "{layer:?}");
        }
    }

    #[test]
    fn runtime_flash_draws_above_f1_help_and_below_recursive_context_gui() {
        let mut help = new_classic_running_sandbox_app();
        help.status_text.clear();
        help.snapshot.hud.messages.clear();
        help.handle_key(VirtualKeyCode::F1, ElementState::Pressed)
            .expect("show help beneath flash");
        help.set_runtime_flash_message("AAAA", RuntimeHelpCharset::Windows1252)
            .expect("install flash above help");
        let flash = help.runtime_flash_message.take().expect("flash state");
        let mut help_only = vec![0_u8; 320 * 200 * 4];
        help.render(&mut help_only).expect("render help-only frame");
        let mut expected = Surface::new(320, 200, PixelFormat::Rgba8888);
        expected.pixels_mut().copy_from_slice(&help_only);
        let gamma = help
            .graphics
            .active_gamma_ramp(&help.snapshot.environment.gamma);
        let fonts = help.assets.clonk_fonts.clone().expect("FontRegular");
        clonk_frontend::flash_message::render_flash_message(
            &mut expected,
            &fonts.text,
            &flash.text,
            flash.y,
            Some(&gamma),
            &MessageFontImages::default(),
        );
        help.runtime_flash_message = Some(flash);
        let mut actual = vec![0_u8; 320 * 200 * 4];
        help.render(&mut actual).expect("render help then flash");
        assert_eq!(actual, expected.pixels());

        let mut context = new_classic_running_sandbox_app();
        context.status_text.clear();
        context.snapshot.hud.messages.clear();
        context
            .open_context_menu_at(
                vec![
                    ContextMenuEntry::<AppContextMenuCommand>::new("Root").with_submenu(vec![
                        ContextMenuEntry::new("Child")
                            .with_submenu(vec![ContextMenuEntry::new("Context above flash")]),
                    ]),
                ],
                GuiPoint::new(120.0, 55.0),
            )
            .expect("open overlapping recursive context");
        for depth in 0..2 {
            context
                .handle_key(VirtualKeyCode::Right, ElementState::Pressed)
                .unwrap_or_else(|error| panic!("open context depth {depth}: {error}"));
            context
                .handle_key(VirtualKeyCode::Right, ElementState::Released)
                .unwrap_or_else(|error| panic!("release context depth {depth}: {error}"));
        }
        context
            .set_runtime_flash_message("AAAAAAAAAAAA", RuntimeHelpCharset::Windows1252)
            .expect("install flash beneath context");
        let menu = context.context_menu.take().expect("detach context");
        let flash = context.runtime_flash_message.clone().expect("flash state");
        let mut flash_only = vec![0_u8; 320 * 200 * 4];
        context.render(&mut flash_only).expect("render flash only");
        let mut expected = Surface::new(320, 200, PixelFormat::Rgba8888);
        expected.pixels_mut().copy_from_slice(&flash_only);
        let gamma = context
            .graphics
            .active_gamma_ramp(&context.snapshot.environment.gamma);
        menu.render(&mut expected, Some(&gamma))
            .expect("compose topmost context");
        context.context_menu = Some(menu);
        context.runtime_flash_message = Some(flash);
        let mut actual = vec![0_u8; 320 * 200 * 4];
        context
            .render(&mut actual)
            .expect("render flash below recursive context");
        assert_eq!(actual, expected.pixels());
    }

    #[test]
    fn runtime_f1_help_columns_match_cpp_rows_keys_and_us_labels() {
        let table = parse_runtime_help_language_table(
            include_bytes!(concat!(
                env!("CARGO_MANIFEST_DIR"),
                "/../../../planet/System.c4g/LanguageUS.txt"
            )),
            "LanguageUS.txt",
        )
        .expect("parse shipped language table");
        let columns = build_runtime_help_columns(&table).expect("build shipped help columns");
        let speed_up = if cfg!(target_os = "windows") {
            "Shift+Add"
        } else if cfg!(target_os = "linux") {
            "Shift+KP_Add"
        } else {
            "Shift+Keypad +"
        };

        assert_eq!(columns.left.lines().count(), 17);
        assert_eq!(columns.left.matches("<c ffff00>").count(), 11);
        assert_eq!(columns.right.lines().count(), 12);
        assert_eq!(columns.right.matches("<c ffff00>").count(), 6);
        assert_eq!(
            columns.left,
            "[Game Functions]\n\n<c ffff00>F1</c> - Help\n<c ffff00>F3</c> - Music\n<c ffff00>Ctrl+F3</c> - Sound\n<c ffff00>F4</c> - Network\n\n<c ffff00>F2/Return</c> - Send message\n<c ffff00>Shift+Up</c> - Scroll messages back\n<c ffff00>Shift+Down</c> - Scroll messages forward\n\n<c ffff00>Alt+C</c> - IRC-Chat\n\n<c ffff00>Tab</c> - Scoreboard (if available)\n\n<c ffff00>F9</c> - Screenshot\n<c ffff00>Ctrl+F9</c> - Screenshot (full game area)\n"
        );
        assert_eq!(
            columns.right,
            format!(
                "\n\n<c ffff00>{speed_up}</c> - Increase game speed\n<c ffff00></c> - Decrease game speed\n\n\n[Debug]\n\n<c ffff00>Ctrl+F5</c> - Debug mode\n<c ffff00>Ctrl+F6</c> - Entrance+Vertices\n<c ffff00>Ctrl+F7</c> - Actions/Commands/Pathfinder\n<c ffff00>Ctrl+F8</c> - SolidMasks\n"
            )
        );

        let duplicate = parse_runtime_help_language_table(
            b"IDS_CON_HELP=First\nIDS_CON_HELP=Second\n",
            "duplicate fixture",
        )
        .expect("parse duplicate fixture");
        assert_eq!(
            duplicate.get("IDS_CON_HELP").map(String::as_str),
            Some("First")
        );
    }

