    #[test]
    fn running_context_menu_renders_above_runtime_f1_help() {
        let mut app = new_classic_running_sandbox_app();
        app.status_text.clear();
        app.snapshot.hud.messages.clear();
        let mut baseline = vec![0_u8; 320 * 200 * 4];
        app.render(&mut baseline).expect("render running baseline");
        app.open_context_menu_at(
            vec![ContextMenuEntry::<AppContextMenuCommand>::new(
                "Context above help",
            )],
            GuiPoint::new(120.0, 105.0),
        )
        .expect("open running context menu");
        let mut context_only = vec![0_u8; 320 * 200 * 4];
        app.render(&mut context_only)
            .expect("render visible running context");
        assert_ne!(context_only, baseline, "running context must draw pixels");

        app.handle_key(VirtualKeyCode::F1, ElementState::Pressed)
            .expect("toggle help beneath context");
        let context = app.context_menu.take().expect("detach running context");
        let mut help_only = vec![0_u8; 320 * 200 * 4];
        app.render(&mut help_only)
            .expect("render help without context");
        let mut expected = Surface::new(320, 200, PixelFormat::Rgba8888);
        expected.pixels_mut().copy_from_slice(&help_only);
        let gamma = app
            .graphics
            .active_gamma_ramp(&app.snapshot.environment.gamma);
        context
            .render(&mut expected, Some(&gamma))
            .expect("compose expected topmost context");
        app.context_menu = Some(context);
        let mut help_and_context = vec![0_u8; 320 * 200 * 4];
        app.render(&mut help_and_context)
            .expect("render help below running context");
        assert_ne!(
            help_and_context, context_only,
            "help remains visible outside the panel"
        );
        assert_eq!(
            help_and_context,
            expected.pixels(),
            "running render must compose the context after F1 help"
        );
    }

    #[test]
    fn runtime_f1_recurses_through_all_engine_menu_styles_and_progress_states() {
        let mut app = new_classic_running_sandbox_app();
        let mut rebound = new_classic_running_sandbox_app();
        rebound
            .bindings
            .rebind(ControlBindingId::Left, VirtualKeyCode::F1);
        rebound
            .engine
            .player_mut(rebound.local_owner)
            .expect("local rebound player")
            .control
            .control_style = true;
        let mut menu_only = vec![0_u8; 320 * 200 * 4];
        let mut menu_and_help = vec![0_u8; 320 * 200 * 4];
        for style in 0..=3 {
            for text_progressing in [false, true] {
                let cursor = app
                    .engine
                    .crew_cursor(app.local_owner)
                    .expect("sandbox cursor");
                let mut menu = two_item_script_menu(cursor);
                menu.style = style;
                menu.text_progressing = text_progressing;
                app.engine
                    .apply_object_update(
                        cursor,
                        ObjectUpdate {
                            menu: Some(Some(menu)),
                            ..ObjectUpdate::default()
                        },
                    )
                    .expect("install engine menu style");
                app.snapshot = app.engine.snapshot();
                menu_only.fill(0);
                app.render(&mut menu_only)
                    .expect("render engine menu before F1");
                app.handle_key(VirtualKeyCode::F1, ElementState::Pressed)
                    .expect("default F1 toggles over engine menu");
                menu_and_help.fill(0);
                app.render(&mut menu_and_help)
                    .expect("render F1 above engine menu");
                assert!(
                    app.runtime_help_visible,
                    "style {style}, progress {text_progressing}"
                );
                assert_ne!(menu_and_help, menu_only);
                assert!(app.engine.cursor_object_menu(app.local_owner).is_some());
                app.handle_key(VirtualKeyCode::F1, ElementState::Released)
                    .expect("release default help key");
                app.handle_key(VirtualKeyCode::F1, ElementState::Pressed)
                    .expect("hide default help before the next engine menu");
                app.handle_key(VirtualKeyCode::F1, ElementState::Released)
                    .expect("release default help reset");
                assert!(!app.runtime_help_visible);

                let rebound_cursor = rebound
                    .engine
                    .crew_cursor(rebound.local_owner)
                    .expect("rebound sandbox cursor");
                let mut rebound_menu = two_item_script_menu(rebound_cursor);
                rebound_menu.style = style;
                rebound_menu.text_progressing = text_progressing;
                rebound
                    .engine
                    .apply_object_update(
                        rebound_cursor,
                        ObjectUpdate {
                            menu: Some(Some(rebound_menu)),
                            ..ObjectUpdate::default()
                        },
                    )
                    .expect("install rebound engine menu style");
                rebound.snapshot = rebound.engine.snapshot();
                rebound
                    .handle_key(VirtualKeyCode::F1, ElementState::Pressed)
                    .expect("player F1 owns every engine menu style");
                assert!(!rebound.runtime_help_visible);
                assert!(rebound
                    .engine
                    .cursor_object_menu(rebound.local_owner)
                    .is_some());
                rebound
                    .handle_key(VirtualKeyCode::F1, ElementState::Released)
                    .expect("release rebound player control");
                assert!(!rebound.pressed_engine_keys.contains(&VirtualKeyCode::F1));
                assert_eq!(
                    rebound
                        .engine
                        .player(rebound.local_owner)
                        .expect("local rebound player")
                        .control
                        .pressed_coms
                        & (1 << clonk_engine::COM_LEFT),
                    0
                );
            }
        }
    }

    #[test]
    fn non_autostop_player_f1_release_falls_through_without_a_stuck_latch() {
        let mut app = new_running_sandbox_app();
        app.bindings
            .rebind(ControlBindingId::Left, VirtualKeyCode::F1);
        app.engine
            .player_mut(app.local_owner)
            .expect("local player")
            .control
            .control_style = false;
        app.handle_key(VirtualKeyCode::F1, ElementState::Pressed)
            .expect("classic control owns F1 down");
        assert!(app.pressed_engine_keys.contains(&VirtualKeyCode::F1));
        app.handle_key(VirtualKeyCode::F1, ElementState::Released)
            .expect("classic control release falls through lower priorities");
        assert!(!app.pressed_engine_keys.contains(&VirtualKeyCode::F1));
        assert!(!app.runtime_help_visible);

        let mut release_only = new_running_sandbox_app();
        release_only
            .bindings
            .rebind(ControlBindingId::Left, VirtualKeyCode::F1);
        release_only
            .engine
            .player_mut(release_only.local_owner)
            .expect("local player")
            .control
            .control_style = false;
        assert!(release_only.show_startup_hint);
        release_only
            .handle_key(VirtualKeyCode::F1, ElementState::Released)
            .expect("up-only classic control falls through");
        assert!(release_only.show_startup_hint);
        assert!(!release_only.runtime_help_visible);
    }

    #[test]
    fn unresolved_runtime_help_language_fails_typed_before_pixels() {
        let mut input_app = new_running_sandbox_app();
        input_app.runtime_key_config_cache = OnceLock::new();
        input_app
            .runtime_key_config_cache
            .set(Err("Extra.c4g/KeyConfig.txt override".to_string()))
            .expect("empty input key-config cache");
        let error = input_app
            .handle_key(VirtualKeyCode::F1, ElementState::Pressed)
            .expect_err("unrepresented key config must fail before toggling");
        assert!(matches!(
            error,
            EngineError::ClassicMenuParityBoundary { .. }
        ));
        assert!(!input_app.runtime_help_visible);

        let mut app = new_classic_running_sandbox_app();
        app.runtime_help_visible = true;
        app.runtime_help_text_cache = OnceLock::new();
        app.runtime_help_text_cache
            .set(Err("LanguageZZ.txt cannot be resolved".to_string()))
            .expect("empty help text cache");
        let before_surface = app.graphics.surface().pixels().to_vec();
        let mut frame = vec![0x6d; 320 * 200 * 4];
        let sentinel = frame.clone();

        let error = app
            .render(&mut frame)
            .expect_err("unresolved localized help cannot draw a partial overlay");
        assert!(error.to_string().contains("runtime F1 help resources"));
        assert!(error.to_string().contains("LanguageZZ.txt"));
        assert_eq!(frame, sentinel);
        assert_eq!(app.graphics.surface().pixels(), before_surface.as_slice());
    }

    #[test]
    fn modified_f1_retains_downstream_priority_without_toggling_help() {
        for modifiers in [
            ModifiersState::ALT,
            ModifiersState::CTRL,
            ModifiersState::SHIFT,
            ModifiersState::ALT | ModifiersState::CTRL,
            ModifiersState::ALT | ModifiersState::SHIFT,
            ModifiersState::CTRL | ModifiersState::SHIFT,
            ModifiersState::ALT | ModifiersState::CTRL | ModifiersState::SHIFT,
            ModifiersState::LOGO | ModifiersState::SHIFT,
        ] {
            let mut app = new_running_sandbox_app();
            app.status_text.clear();
            app.snapshot.hud.messages.clear();
            app.handle_modifiers_changed(modifiers)
                .expect("set keyboard modifiers");
            let before = runtime_global_ui_snapshot(&app);
            let mut before_pixels = vec![0_u8; 320 * 200 * 4];
            app.render(&mut before_pixels)
                .expect("render before modified F1");

            app.handle_key(VirtualKeyCode::F1, ElementState::Pressed)
                .expect("modified F1 reaches the ordinary downstream route");
            app.handle_key(VirtualKeyCode::F1, ElementState::Released)
                .expect("modified F1 release reaches the downstream route");

            let after = runtime_global_ui_snapshot(&app);
            assert_eq!(after.status_text, before.status_text);
            assert_eq!(after.message_dialogs, before.message_dialogs);
            assert_eq!(after.game_over_open, before.game_over_open);
            assert_eq!(after.ingame_page, before.ingame_page);
            assert_eq!(after.object_menu_open, before.object_menu_open);
            assert_eq!(after.context_menu_open, before.context_menu_open);
            assert_eq!(after.runtime_help_visible, before.runtime_help_visible);
            assert_eq!(after.pressed_engine_keys, before.pressed_engine_keys);
            assert_eq!(
                after.message_dialog_consumed_keys,
                before.message_dialog_consumed_keys
            );
            let mut after_pixels = vec![0_u8; 320 * 200 * 4];
            app.render(&mut after_pixels)
                .expect("render after modified F1");
            assert_eq!(after_pixels, before_pixels);
        }
    }

    #[test]
    fn runtime_client_list_maps_native_lifecycle_readiness_and_wait() {
        use clonk_frontend::runtime_client_list::RuntimeClientStatusIcon;

        let state = |status, control_ready, wait_ms| network::RuntimeNetworkClientState {
            client_id: 7,
            status,
            control_ready,
            wait_ms,
        };
        for lifecycle in [
            clonk_network::RemoteBarrierState::Joining,
            clonk_network::RemoteBarrierState::Chasing,
            clonk_network::RemoteBarrierState::NotReady,
        ] {
            assert_eq!(
                GameApp::runtime_client_row_network_state(
                    false,
                    Some(&state(lifecycle, true, -12)),
                ),
                (RuntimeClientStatusIcon::Loading, Some(-12))
            );
        }
        assert_eq!(
            GameApp::runtime_client_row_network_state(
                false,
                Some(&state(clonk_network::RemoteBarrierState::Ready, false, 9)),
            ),
            (RuntimeClientStatusIcon::NetWait, Some(9))
        );
        assert_eq!(
            GameApp::runtime_client_row_network_state(
                false,
                Some(&state(clonk_network::RemoteBarrierState::Ready, true, 4)),
            ),
            (RuntimeClientStatusIcon::Ready, Some(4))
        );
        assert_eq!(
            GameApp::runtime_client_row_network_state(
                false,
                Some(&state(clonk_network::RemoteBarrierState::Removing, true, 2)),
            ),
            (RuntimeClientStatusIcon::Kick, Some(2))
        );
        assert_eq!(
            GameApp::runtime_client_row_network_state(
                true,
                Some(&state(clonk_network::RemoteBarrierState::Ready, false, 99)),
            ),
            (RuntimeClientStatusIcon::NetWait, None)
        );
    }

    #[test]
    fn l140_network_status_collector_uses_native_client_next_control_baselines() {
        let mut app = new_running_sandbox_app();
        let (_events, _commands) = install_running_network_stub(&mut app, 0, 40, 4);
        let mut inactive = message_client(9, b"Inactive");
        inactive.activated = false;
        app.control_clients.replace_snapshot([
            message_client(0, b"Host"),
            message_client(7, b"Remote"),
            inactive,
        ]);
        app.refresh_network_client_next_control_ticks();
        app.network_control_clock = Some(NetworkControlClock::new(44, 4));
        app.network
            .as_ref()
            .expect("network stub")
            .set_test_runtime_client_states([
                network::RuntimeNetworkClientState {
                    client_id: 7,
                    status: clonk_network::RemoteBarrierState::Ready,
                    control_ready: false,
                    wait_ms: -12,
                },
                network::RuntimeNetworkClientState {
                    client_id: 9,
                    status: clonk_network::RemoteBarrierState::NotReady,
                    control_ready: true,
                    wait_ms: 5,
                },
            ]);
        app.graphics
            .set_debug_draw_flags(clonk_frontend::DebugDrawFlags {
                show_net_status: true,
                ..clonk_frontend::DebugDrawFlags::default()
            });

        app.update_network_status_overlay();

        let text = app
            .graphics
            .network_status_text()
            .expect("enabled network status text");
        assert!(
            text.contains(
                "|- Active client Remote (ID 7) (wait -12 ms, behind 4) (ready to start) (!ctrl)"
            ),
            "{text}"
        );
        assert!(
            text.contains(
                "|- Inactive client Inactive (ID 9) (wait 5 ms, behind 44) (!rdy)"
            ),
            "{text}"
        );

        app.refresh_network_client_next_control_ticks();
        app.update_network_status_overlay();
        assert!(
            app.graphics
                .network_status_text()
                .expect("refreshed network status text")
                .contains(
                    "|- Active client Remote (ID 7) (wait -12 ms, behind 0) (ready to start) (!ctrl)"
                )
        );
    }

    #[test]
    fn runtime_f4_toggles_only_live_network_dialog_and_consumes_edges() {
        for (role, opens) in [
            (RuntimeNetworkRole::Offline, false),
            (RuntimeNetworkRole::Host, true),
            (RuntimeNetworkRole::Client, true),
            (RuntimeNetworkRole::Ambiguous, false),
        ] {
            let mut app = new_running_sandbox_app();
            configure_runtime_network_role(&mut app, role);
            app.handle_key(VirtualKeyCode::F4, ElementState::Pressed)
                .expect("runtime F4 press is handled locally");
            assert_eq!(app.runtime_client_list.is_some(), opens, "role {role:?}");
            assert_eq!(app.mode, AppMode::Running);
            assert!(!app.exit_requested);

            let before_release = runtime_global_ui_snapshot(&app);
            app.handle_key(VirtualKeyCode::F4, ElementState::Released)
                .expect("runtime F4 release is consumed");
            assert_eq!(runtime_global_ui_snapshot(&app), before_release);

            app.handle_key(VirtualKeyCode::F4, ElementState::Pressed)
                .expect("second runtime F4 press toggles off");
            assert!(app.runtime_client_list.is_none());
        }
    }

    #[test]
    fn runtime_f4_gamepad_high_requires_active_dialog_and_other_input_reaches_gameplay() {
        let mut active = new_running_sandbox_app();
        let (_events, mut commands) = install_running_network_stub(&mut active, 0, 40, 4);
        route_primary_gamepad_to_local_owner(&mut active);
        active
            .handle_key(VirtualKeyCode::F4, ElementState::Pressed)
            .expect("open active runtime F4 dialog");
        assert!(active.runtime_client_list_strong_gamepad_callback_is_active());
        assert!(active.runtime_client_list_draw_active());

        active
            .process_gamepad_event_batch([
                GamepadEvent::Axis {
                    slot: GamepadSlot::new(0),
                    axis: LegacyGamepadAxis::new(0, true),
                    state: ElementState::Pressed,
                },
                GamepadEvent::Direction {
                    slot: GamepadSlot::new(0),
                    button: ControlButton::Right,
                    state: ElementState::Pressed,
                },
            ])
            .expect("normal F4 leaves player-control gamepad directions in base scope");
        let submitted = commands.take_submitted_local();
        assert_eq!(submitted.len(), 1);
        assert!(matches!(
            submitted[0].1,
            ControlEvent::Press(ControlButton::Right)
        ));

        active
            .process_gamepad_event_batch([
                GamepadEvent::GuiButton {
                    slot: GamepadSlot::new(0),
                    class: GuiButtonClass::High,
                    state: ElementState::Pressed,
                },
                GamepadEvent::Action {
                    slot: GamepadSlot::new(0),
                    action: GamepadActionType::MenuToggle,
                    state: ElementState::Pressed,
                },
            ])
            .expect("active F4 strong High callback owns its raw alias cluster");
        assert!(active.runtime_client_list.is_none());
        assert!(active.ingame_menu.is_none());
        assert!(commands.take_submitted_local().is_empty());

        let mut inactive = new_running_sandbox_app();
        configure_runtime_network_role(&mut inactive, RuntimeNetworkRole::Host);
        inactive
            .push_message_dialog(
                clonk_frontend::message_dialog::MessageDialogState::regular_ok(
                    "Notice",
                    "The older F4 dialog remains inactive",
                    clonk_frontend::message_dialog::MessageDialogIcon::NOTIFY,
                ),
                MessageDialogContinuation::None,
            )
            .expect("show ordinary dialog before F4");
        inactive
            .handle_key(VirtualKeyCode::F4, ElementState::Pressed)
            .expect("insert F4 below the existing z+1 message");
        assert!(!inactive.runtime_client_list_strong_gamepad_callback_is_active());
        assert!(!inactive.runtime_client_list_draw_active());
        inactive
            .process_gamepad_event_batch([GamepadEvent::GuiButton {
                slot: GamepadSlot::new(0),
                class: GuiButtonClass::High,
                state: ElementState::Pressed,
            }])
            .expect("inactive F4 has no strong High callback");
        assert!(inactive.runtime_client_list.is_some());
        assert_eq!(inactive.message_dialogs.len(), 1);
    }

