    #[test]
    fn host_vote_pause_lifecycle_matches_pause_vote_result() {
        // The running host pauses for any active vote. Approved VT_Pause(1)
        // leaves that pause in place; an approved VT_Pause(0) begun while
        // already paused restores GS_Go once no ballots remain
        // (src/C4Network2.cpp:2861-2883,2929-2938;
        // src/C4Game.cpp:1024-1054).
        let mut pause_app = new_state_only_running_sandbox_app();
        pause_app
            .engine
            .player_mut(pause_app.local_owner)
            .expect("host player")
            .set_at_client(clonk_engine::PlayerAtClient::HOST);
        let (pause_snapshot, pause_reference) = default_exact_host_reference();
        pause_app.control_clients = ControlClientRegistry::default();
        pause_app
            .control_clients
            .replace_snapshot(pause_snapshot.parameters.clients.clients.clone());
        pause_app.host_join_snapshot = Some(pause_snapshot);
        pause_app.advertised_game_reference = Some(pause_reference);
        let (manager, _events, mut commands) = NetworkManager::test_stub_with_commands();
        pause_app.network = Some(manager);
        pause_app.network_mode = Some(NetworkMode::Host(HostSettings {
            bind_addr: SocketAddr::from(([127, 0, 0, 1], 0)),
            player_name: "Host".to_string(),
            prepared: None,
        }));
        let pause = clonk_engine::VoteControlData {
            vote_type: clonk_engine::VOTE_TYPE_PAUSE,
            approve: true,
            data: 1,
            by_client: 0,
        };

        pause_app
            .execute_league_vote(pause)
            .expect("start pause vote");

        let pause_changes = commands.take_status_changes();
        assert_eq!(pause_changes.len(), 1);
        assert_eq!(pause_changes[0].state, clonk_network::NETWORK_STATE_PAUSE);
        assert_eq!(
            pause_app
                .advertised_game_reference
                .as_ref()
                .expect("pause refreshes the retained reference")
                .summary()
                .state,
            "Paused"
        );
        pause_app.execute_league_vote_end(pause);
        assert!(commands.take_status_changes().is_empty());
        assert_eq!(
            pause_app
                .advertised_game_reference
                .as_ref()
                .expect("approved pause remains advertised")
                .summary()
                .state,
            "Paused"
        );

        let mut unpause_app = new_state_only_running_sandbox_app();
        unpause_app
            .engine
            .player_mut(unpause_app.local_owner)
            .expect("host player")
            .set_at_client(clonk_engine::PlayerAtClient::HOST);
        let (unpause_snapshot, unpause_reference) = default_exact_host_reference();
        unpause_app.control_clients = ControlClientRegistry::default();
        unpause_app
            .control_clients
            .replace_snapshot(unpause_snapshot.parameters.clients.clients.clone());
        unpause_app.host_join_snapshot = Some(unpause_snapshot);
        unpause_app.advertised_game_reference = Some(unpause_reference);
        let (manager, _events, mut commands) = NetworkManager::test_stub_with_commands();
        unpause_app.network = Some(manager);
        unpause_app.network_mode = Some(NetworkMode::Host(HostSettings {
            bind_addr: SocketAddr::from(([127, 0, 0, 1], 0)),
            player_name: "Host".to_string(),
            prepared: None,
        }));
        unpause_app.network_control_running = false;
        unpause_app.league_votes.paused_for_vote = true;
        unpause_app.host_reference_paused = true;
        unpause_app.publish_running_host_reference();
        let unpause = clonk_engine::VoteControlData { data: 0, ..pause };

        unpause_app
            .execute_league_vote(unpause)
            .expect("start unpause vote");
        assert!(commands.take_status_changes().is_empty());
        unpause_app.execute_league_vote_end(unpause);

        let go_changes = commands.take_status_changes();
        assert_eq!(go_changes.len(), 1);
        assert_eq!(go_changes[0].state, clonk_network::NETWORK_STATE_GO);
        assert_eq!(
            unpause_app
                .advertised_game_reference
                .as_ref()
                .expect("GO request refreshes the retained reference")
                .summary()
                .state,
            "Running"
        );
    }

    #[test]
    fn league_observer_part_uses_ordinary_network_clear_path() {
        // League changes Part into a self-kick vote only when
        // Game.Players.GetLocalByIndex(0) exists. An observer with no local
        // player follows the ordinary result+Network.Clear path
        // (src/C4MainMenu.cpp:820-831).
        let mut app = new_running_sandbox_app();
        let local_client = 7;
        app.engine
            .remove_player(app.local_owner)
            .expect("remove observer's synthetic local player");
        let (manager, _events, commands) =
            NetworkManager::test_stub_with_commands_for_client_id(local_client);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11_112)),
            "Observer",
        )));
        app.network_is_league = true;
        app.control_clients = ControlClientRegistry::default();
        app.control_clients
            .register(local_client as i32, false, true);
        let graceful_write = thread::spawn(move || commands.complete_graceful_part());

        app.apply_ingame_menu_action(MenuAction::Part)
            .expect("observer parts from league game");

        assert!(graceful_write.join().expect("graceful writer exits"));
        assert!(app.network.is_none());
        assert!(app.network_mode.is_none());
        assert!(matches!(app.mode, AppMode::Running));
        assert_eq!(
            app.snapshot.round_results.network_result,
            Some(clonk_engine::RoundResultsNetworkResult::NetworkError)
        );
        assert_eq!(
            app.snapshot.round_results.network_result_message.as_slice(),
            b"Game left via player menu.",
            "a league observer uses the ordinary localized Part verdict"
        );
    }

    #[test]
    fn synchronized_surrender_executes_only_for_the_runtime_player_owner() {
        // C4Control executes CID_SurrenderPlayer through
        // C4ControlInternalPlayerScriptBase::Allowed, which requires the
        // runtime C4Player::AtClient to equal iByClient
        // (src/C4Control.cpp:93-109,1546-1578).
        let mut app = new_state_only_running_sandbox_app();
        let player = app.local_owner;
        app.engine
            .player_mut(player)
            .expect("local player")
            .set_at_client(clonk_engine::PlayerAtClient::new(3));
        assert_eq!(
            app.engine.player(player).expect("local player").at_client(),
            clonk_engine::PlayerAtClient::new(3)
        );

        app.apply_ready_controls(
            0,
            vec![NetworkControl::SurrenderPlayer(
                clonk_engine::SurrenderPlayerControlData {
                    player,
                    by_client: 7,
                },
            )],
        )
        .expect("execute spoofed surrender control");
        assert!(!app
            .engine
            .player(player)
            .expect("local player")
            .surrendered());

        app.apply_ready_controls(
            1,
            vec![NetworkControl::SurrenderPlayer(
                clonk_engine::SurrenderPlayerControlData {
                    player,
                    by_client: 3,
                },
            )],
        )
        .expect("execute owner surrender control");
        assert!(app
            .engine
            .player(player)
            .expect("local player")
            .surrendered());
    }

    #[test]
    fn next_mission_action_launches_the_catalog_target() {
        // C4GameOverDlg's Next button passes Game.NextMission through
        // C4Application::SetNextMission/QuitGame and starts that scenario
        // (C4GameOverDlg.cpp:335-382; C4Application.cpp:373-399).
        let fixture = tempdir().expect("next-mission fixture");
        let user_data = tempdir().expect("isolated user data");
        let (_guard, paths) = exact_loader_test_paths(user_data.path(), None);
        configure_test_startup_participant(&paths, user_data.path());
        let mut app = new_menu_app_with_paths(320, 200, &paths);
        app.start_sandbox_scenario(FrontendScenario::fallback())
            .expect("start sandbox scenario");
        wait_for_running(&mut app);
        let target_path = fixture.path().join("Tutorial02.c4s");
        let carried_definition = fixture.path().join("Carry.c4d");
        fs::create_dir_all(&target_path).expect("target scenario");
        fs::create_dir_all(&carried_definition).expect("carried definition");
        fs::write(
            target_path.join("Scenario.txt"),
            "[Head]\nTitle=The First Hut\n",
        )
        .expect("target Scenario.txt");
        fs::write(
            carried_definition.join("DefCore.txt"),
            "[DefCore]\nid=CARY\nName=Carry\nCategory=1\n",
        )
        .expect("carried DefCore.txt");
        fs::write(carried_definition.join("Script.c"), "// carried\n").expect("carried Script.c");
        write_test_definition_graphics(&carried_definition);
        let mut target = FrontendScenario::fallback();
        target.identifier = "Tutorial.c4f/Tutorial02.c4s".to_string();
        target.title = "The First Hut".to_string();
        target.path = Some(target_path);
        app.scenario_catalog
            .insert(target.identifier.clone(), target.clone());
        app.active_definition_load = Some(ScenarioDefinitionLoad::Fixed {
            modules: vec![carried_definition.to_string_lossy().into_owned()],
            definition_root: None,
        });

        let mut state = app.engine.capture_state();
        state.next_mission = clonk_engine::NextMissionState {
            path: "Tutorial.c4f\\Tutorial02.c4s".to_string(),
            text: "Next tutorial".to_string(),
            description: "Continue learning".to_string(),
        };
        app.engine.restore_state(&state).expect("state restores");

        app.handle_game_over_action(GameOverAction::NextMission)
            .expect("next mission starts");
        wait_for_running(&mut app);

        assert_eq!(
            app.active_scenario
                .as_ref()
                .map(|scenario| scenario.identifier.as_str()),
            Some("Tutorial.c4f/Tutorial02.c4s")
        );
        assert!(matches!(
            app.active_definition_load.as_ref(),
            Some(ScenarioDefinitionLoad::Fixed {
                modules,
                definition_root: None,
            }) if modules == &[carried_definition.to_string_lossy().as_ref()]
        ));
        assert!(app.game_over_dialog.is_none());
    }

    #[test]
    fn game_over_restart_and_next_mission_follow_control_host_film_policy() {
        // C4GameOverDlg admits these two controls only for the control host
        // or exact cinematic Film 2. Ordinary Film 1 is intentionally not an
        // override, and 1280 is the first width that retains Restart beside a
        // configured Next Mission (C4GameOverDlg.cpp:115-142,232-258).
        let mut app = new_classic_running_sandbox_app();
        let mut state = app.engine.capture_state();
        state.next_mission = clonk_engine::NextMissionState {
            path: "Tutorial.c4f\\Tutorial02.c4s".into(),
            text: "Next tutorial".into(),
            description: "Continue learning".into(),
        };
        app.engine.restore_state(&state).expect("restore next mission");

        for (control_host, film, width, expected) in [
            (
                false,
                0,
                1280,
                vec![GameOverAction::End, GameOverAction::Continue],
            ),
            (
                false,
                1,
                1280,
                vec![GameOverAction::End, GameOverAction::Continue],
            ),
            (
                true,
                0,
                1279,
                vec![
                    GameOverAction::End,
                    GameOverAction::Continue,
                    GameOverAction::NextMission,
                ],
            ),
            (
                true,
                0,
                1280,
                vec![
                    GameOverAction::End,
                    GameOverAction::Continue,
                    GameOverAction::Restart,
                    GameOverAction::NextMission,
                ],
            ),
            (
                false,
                2,
                1279,
                vec![
                    GameOverAction::End,
                    GameOverAction::Continue,
                    GameOverAction::NextMission,
                ],
            ),
            (
                false,
                2,
                1280,
                vec![
                    GameOverAction::End,
                    GameOverAction::Continue,
                    GameOverAction::Restart,
                    GameOverAction::NextMission,
                ],
            ),
        ] {
            app.dismiss_game_over_dialog();
            app.resize(width, 720).expect("resize evaluation fixture");
            set_test_scenario_head_flags(&mut app, 0, film);
            app.engine.set_control_host(control_host);
            app.finish_game_over_after_league()
                .expect("construct evaluation dialog");
            assert_eq!(
                app.game_over_dialog
                    .as_ref()
                    .expect("evaluation dialog")
                    .actions(),
                expected,
                "control_host={control_host}, Film={film}, width={width}"
            );
        }
    }

    #[test]
    fn evaluation_dialog_joins_frozen_results_by_player_info_id() {
        // C4GameOverDlg consumes C4RoundResults goals/player records, and
        // C4PlayerInfoListBox joins each record through C4PlayerInfo::GetID,
        // never C4Player::Number (C4GameOverDlg.cpp:145-220;
        // C4PlayerInfoListBox.cpp:132-143,344-425,1529-1592).
        let mut snapshot = make_snapshot(Vec::new(), Vec::new());
        snapshot.players = vec![
            PlayerState {
                id: 99,
                player_info_id: 41,
                name: "Player".into(),
                status: PlayerStatus::Eliminated,
                won: true,
                color: Some(RgbColor::new(0xe8, 0, 0)),
                ..PlayerState::default()
            },
            PlayerState {
                id: 41,
                player_info_id: 7,
                name: "Decoy".into(),
                status: PlayerStatus::Active,
                won: false,
                ..PlayerState::default()
            },
        ];
        snapshot.round_results = clonk_engine::RoundResultsState {
            goals: vec!["SCRG".into()],
            fulfilled_goals: vec!["SCRG".into()],
            players: vec![
                clonk_engine::RoundResultsPlayerState {
                    player_info_id: 41,
                    total_playing_time: 3_661,
                    score_old: 10,
                    score_new: Some(110),
                    league_progress_data: None,
                    league_performance: 0,
                    custom_evaluation_strings: String::new(),
                    ..clonk_engine::RoundResultsPlayerState::default()
                },
                clonk_engine::RoundResultsPlayerState {
                    player_info_id: 99,
                    total_playing_time: 9,
                    score_old: 900,
                    score_new: Some(901),
                    league_progress_data: None,
                    league_performance: 0,
                    custom_evaluation_strings: "wrong runtime-number join".into(),
                    ..clonk_engine::RoundResultsPlayerState::default()
                },
            ],
            ..clonk_engine::RoundResultsState::default()
        };
        let next_mission = clonk_engine::NextMissionState {
            path: "Tutorial.c4f\\Tutorial02.c4s".into(),
            text: "Next tutorial".into(),
            description: "Continue learning".into(),
        };
        let picture = ImageData::new(1, 1, vec![12, 34, 56, 255]);
        let player_icon = ImageData::new(1, 1, vec![65, 43, 21, 255]);

        let dialog = build_game_over_dialog(
            &snapshot,
            &[],
            false,
            99,
            1024,
            true,
            "decoy title".into(),
            &next_mission,
            |definition_id, fulfilled| {
                (
                    (definition_id == "SCRG").then(|| picture.clone()),
                    if fulfilled {
                        "Goal Scenario goal fulfilled: Complete the scenario".into()
                    } else {
                        "Goal Scenario goal not fulfilled: Complete the scenario".into()
                    },
                )
            },
            |player_info_id| (player_info_id == 41).then(|| player_icon.clone()),
        );

        assert_eq!(
            dialog.actions(),
            vec![
                GameOverAction::End,
                GameOverAction::Continue,
                GameOverAction::NextMission,
            ],
            "Tutorial02 is exposed through the classic next-mission button"
        );
        assert_eq!(dialog.evaluation().goals().len(), 1);
        let goal = &dialog.evaluation().goals()[0];
        assert_eq!(goal.definition_id, "SCRG");
        assert!(goal.fulfilled);
        assert_eq!(
            goal.tooltip,
            "Goal Scenario goal fulfilled: Complete the scenario"
        );
        assert_eq!(
            goal.picture.as_ref().map(|image| image.pixels().to_vec()),
            Some(vec![12, 34, 56, 255])
        );
        let player = dialog
            .evaluation()
            .player_by_info_id(41)
            .expect("result joins the profile ID");
        assert_eq!(player.name, "Player");
        assert!(player.won, "won comes from frozen player info, not Active");
        assert_eq!(player.color_dw, 0x00e8_0000);
        assert_eq!(player.total_playing_time, 3_661);
        assert_eq!((player.score_old, player.score_new), (10, Some(110)));
        assert_eq!(player.big_icon.as_ref(), Some(&player_icon));
        assert_eq!(
            dialog.evaluation().players().count(),
            1,
            "a result keyed like the runtime number must not attach to the player"
        );

        snapshot.round_results.hide_settlement_score = true;
        let hidden = build_game_over_dialog(
            &snapshot,
            &[],
            false,
            99,
            1024,
            true,
            "decoy title".into(),
            &next_mission,
            |_, _| (None, String::new()),
            |_| None,
        );
        let player = hidden
            .evaluation()
            .player_by_info_id(41)
            .expect("hidden result still joins the profile");
        assert_eq!(
            (player.score_old, player.score_new),
            (-1, None),
            "HideSettlementScoreInEvaluation suppresses the score line"
        );
    }

    #[test]
    fn evaluation_dialog_sources_global_text_and_fixed_team_context() {
        let mut snapshot = make_snapshot(Vec::new(), Vec::new());
        snapshot.players = vec![
            PlayerState {
                id: 20,
                player_info_id: 200,
                name: "Blue".into(),
                team: Some(2),
                won: false,
                ..PlayerState::default()
            },
            PlayerState {
                id: 10,
                player_info_id: 100,
                name: "Red winner".into(),
                team: Some(1),
                won: true,
                ..PlayerState::default()
            },
            PlayerState {
                id: 11,
                player_info_id: 101,
                name: "Red teammate".into(),
                team: Some(1),
                won: false,
                ..PlayerState::default()
            },
        ];
        snapshot.round_results = clonk_engine::RoundResultsState {
            custom_evaluation_strings: "Global summary|Second line".into(),
            players: [200, 100, 101]
                .into_iter()
                .map(|player_info_id| clonk_engine::RoundResultsPlayerState {
                    player_info_id,
                    custom_evaluation_strings: (player_info_id == 101)
                        .then_some("Personal note".to_string())
                        .unwrap_or_default(),
                    ..clonk_engine::RoundResultsPlayerState::default()
                })
                .collect(),
            ..clonk_engine::RoundResultsState::default()
        };
        let teams = [
            clonk_engine::TeamInfo::new(1, "Red", 0x00f4_0000),
            clonk_engine::TeamInfo::new(2, "Blue", 0x0000_00f4),
        ];
        let dialog = build_game_over_dialog(
            &snapshot,
            &teams,
            false,
            10,
            1024,
            true,
            "Scenario".into(),
            &clonk_engine::NextMissionState::default(),
            |_, _| (None, String::new()),
            |_| None,
        );

        assert_eq!(
            dialog.evaluation().custom_evaluation_strings(),
            "Global summary|Second line"
        );
        assert_eq!(dialog.evaluation().separate_team_ids(), Some([1, 2]));
        let players = dialog.evaluation().players().collect::<Vec<_>>();
        assert_eq!(
            players
                .iter()
                .map(|player| (player.player_info_id, player.team_id, player.won))
                .collect::<Vec<_>>(),
            vec![
                (200, Some(2), false),
                (100, Some(1), true),
                (101, Some(1), true),
            ],
            "fixed-team context retains source order and applies team-level victory"
        );
        assert_eq!(players[2].custom_evaluation_strings, "Personal note");
        let fonts = new_classic_running_sandbox_app()
            .assets
            .clonk_fonts
            .clone()
            .expect("classic fonts");
        let split_layout = dialog.classic_evaluation_layout(1024, 600, &fonts);
        assert_eq!(split_layout.player_lists.len(), 2);
        assert_eq!(
            split_layout
                .players
                .iter()
                .map(|player| (player.player_list_index, player.player_index))
                .collect::<Vec<_>>(),
            vec![(0, 1), (0, 2), (1, 0)]
        );

        let generated = build_game_over_dialog(
            &snapshot,
            &teams,
            true,
            10,
            1024,
            true,
            "Scenario".into(),
            &clonk_engine::NextMissionState::default(),
            |_, _| (None, String::new()),
            |_| None,
        );
        assert_eq!(generated.evaluation().separate_team_ids(), None);
        assert_eq!(
            generated
                .classic_evaluation_layout(1024, 600, &fonts)
                .player_lists
                .len(),
            1
        );
    }

    #[test]
    fn savegame_slot_path_uses_configured_folder_and_scenname_scheme() {
        let fixture = tempdir().expect("savegame path fixture");
        let user_data = fixture.path().join("user-data");
        let configured_folder = fixture.path().join("Configured Saves.c4f");
        let (_guard, paths) = exact_loader_test_paths(&user_data, None);
        persist_config_value(
            &paths,
            "General",
            "SaveGameFolder",
            configured_folder.to_string_lossy().into_owned(),
        )
        .expect("configure nondefault savegame folder");

        let mut app = new_state_only_lightweight_running_sandbox_app();
        app.app_paths = Some(paths.clone());

        let localized_title = "  Höhlenübung: Zurück  ";
        let mut old_style = FrontendScenario::fallback();
        old_style.path = Some(
            paths
                .install_root()
                .join("planet/Missions.c4f/01.c4s"),
        );
        old_style.identifier = "StaleAlias.c4f/Wrong999.c4s".to_string();
        old_style.title = localized_title.to_string();
        app.active_scenario = Some(old_style.clone());

        let old_slot = configured_folder
            .join("Missions.c4f")
            .join("Missions1.c4s");
        assert_eq!(app.savegame_slot_path(1), old_slot);
        assert_eq!(
            app.savegame_slot_path(10),
            configured_folder
                .join("Missions.c4f")
                .join("Missions10.c4s")
        );

        let mut new_style = old_style;
        new_style.identifier = "AnotherAlias.c4f/AlsoWrong.c4s".to_string();
        new_style.path = Some(
            paths
                .install_root()
                .join("planet/Tutorial.c4f/Tutorial007.c4s"),
        );
        app.active_scenario = Some(new_style);
        assert_eq!(
            app.savegame_slot_path(10),
            configured_folder
                .join("Tutorial.c4f")
                .join("Tutorial10.c4s")
        );

        let mut loose_numeric = FrontendScenario::fallback();
        loose_numeric.identifier = "Loose/01.c4s".to_string();
        loose_numeric.path = Some(paths.install_root().join("planet/Loose/01.c4s"));
        app.active_scenario = Some(loose_numeric);
        assert_eq!(
            app.savegame_slot_path(1),
            configured_folder.join("01.c4f").join("011.c4s"),
            "a regular directory is not Game.pParentGroup"
        );

        persist_config_value(
            &paths,
            "General",
            "SaveGameFolder",
            "Relative Saves.c4f",
        )
        .expect("configure relative savegame folder");
        assert_eq!(
            configured_savegame_directory(Some(&paths)),
            paths.install_root().join("Relative Saves.c4f")
        );
        persist_config_value(
            &paths,
            "General",
            "SaveGameFolder",
            configured_folder.to_string_lossy().into_owned(),
        )
        .expect("restore absolute savegame folder");

        assert!(looks_like_cpp_integer("+999999999999999999999999"));
        assert!(looks_like_cpp_integer("-01"));
    }

